    # =========================================================================
    # Float64 helper functions for calling primitives with pointer arguments
    # =========================================================================

    def _f64_alloc_temp(self, name: str):
        """Allocate 8 bytes on stack for a Float64 temporary, return pointer."""
        temp_ptr = self.builder.new_vreg(IRType.PTR, name)
        self.builder.emit(IRInstr(
            OpCode.SUB,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            Immediate(8, IRType.WORD),
            comment=f"alloc {name}"
        ))
        self.builder.emit(IRInstr(
            OpCode.MOV, temp_ptr,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.PTR),
            comment=f"{name} = SP"
        ))
        return temp_ptr

    def _f64_call_unary(self, func_name: str, result_ptr, src_ptr):
        """Call unary Float64 function: result = func(src)."""
        # Register runtime dependencies
        if self.builder.module:
            self.builder.module.need_runtime(func_name)
            if isinstance(src_ptr, Label):
                self.builder.module.need_runtime(src_ptr.name)
        self.builder.push(result_ptr)
        self.builder.push(src_ptr)
        self.builder.call(Label(func_name))
        self.builder.emit(IRInstr(
            OpCode.ADD,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            Immediate(4, IRType.WORD),
            comment=f"pop {func_name} args"
        ))

    def _f64_call_copy(self, dest_ptr, src_ptr):
        """Call _f64_copy with correct argument order: dest = copy of src.

        Note: _f64_copy has different calling convention than other unary functions:
        - dest_ptr at IX+4 (pushed last)
        - src_ptr at IX+6 (pushed first)
        """
        if self.builder.module:
            self.builder.module.need_runtime("_f64_copy")
            if isinstance(src_ptr, Label):
                self.builder.module.need_runtime(src_ptr.name)
        self.builder.push(src_ptr)   # pushed first -> IX+6
        self.builder.push(dest_ptr)  # pushed last -> IX+4
        self.builder.call(Label("_f64_copy"))
        self.builder.emit(IRInstr(
            OpCode.ADD,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            Immediate(4, IRType.WORD),
            comment="pop _f64_copy args"
        ))

    def _alloc_float64_temp(self, name: str = "_f64_tmp"):
        """Allocate 8 bytes on stack for a Float64 temporary, return pointer vreg."""
        result_ptr = self.builder.new_vreg(IRType.PTR, name)
        self.builder.emit(IRInstr(
            OpCode.SUB,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            Immediate(8, IRType.WORD),
            comment=f"allocate 8 bytes for {name}"
        ))
        self.builder.emit(IRInstr(
            OpCode.MOV, result_ptr,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.PTR),
            comment=f"{name} = SP"
        ))
        return result_ptr

    def _f64_call_binary(self, func_name: str, result_ptr, left_ptr, right_ptr):
        """Call binary Float64 function: result = func(left, right)."""
        # Register runtime dependencies
        if self.builder.module:
            self.builder.module.need_runtime(func_name)
            if isinstance(left_ptr, Label):
                self.builder.module.need_runtime(left_ptr.name)
            if isinstance(right_ptr, Label):
                self.builder.module.need_runtime(right_ptr.name)
        self.builder.push(result_ptr)
        self.builder.push(right_ptr)
        self.builder.push(left_ptr)
        self.builder.call(Label(func_name))
        self.builder.emit(IRInstr(
            OpCode.ADD,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            Immediate(6, IRType.WORD),
            comment=f"pop {func_name} args"
        ))

    # =========================================================================
    # Composite Float64 functions - inlined formulas calling primitives
    # These match the Ada implementations in adalib/ada-numerics-elementary_functions.adb
    # =========================================================================

    def _lower_float64_sinh(self, operand_expr):
        """sinh(x) = (E_X - 1.0/E_X) / 2.0  where E_X = exp(x)

        Matches Ada implementation in adalib/ada-numerics-elementary_functions.adb
        """
        x_ptr = self._lower_float64_operand(operand_expr)

        # Generate local constants
        const_1 = self._lower_float64_literal(1.0)
        const_2 = self._lower_float64_literal(2.0)

        # E_X = exp(x)
        exp_x = self._f64_alloc_temp("exp_x")
        self._f64_call_unary("_f64_e2x", exp_x, x_ptr)

        # inv_exp_x = 1.0 / E_X
        inv_exp_x = self._f64_alloc_temp("inv_exp_x")
        self._f64_call_binary("_f64_div", inv_exp_x, const_1, exp_x)

        # diff = E_X - 1.0/E_X
        diff = self._f64_alloc_temp("diff")
        self._f64_call_binary("_f64_sub", diff, exp_x, inv_exp_x)

        # result = diff / 2.0
        result = self._f64_alloc_temp("sinh_result")
        self._f64_call_binary("_f64_div", result, diff, const_2)

        return result

    def _lower_float64_cosh(self, operand_expr):
        """cosh(x) = (E_X + 1.0/E_X) / 2.0  where E_X = exp(x)

        Matches Ada implementation in adalib/ada-numerics-elementary_functions.adb
        """
        x_ptr = self._lower_float64_operand(operand_expr)

        # Generate local constants
        const_1 = self._lower_float64_literal(1.0)
        const_2 = self._lower_float64_literal(2.0)

        # E_X = exp(x)
        exp_x = self._f64_alloc_temp("exp_x")
        self._f64_call_unary("_f64_e2x", exp_x, x_ptr)

        # inv_exp_x = 1.0 / E_X
        inv_exp_x = self._f64_alloc_temp("inv_exp_x")
        self._f64_call_binary("_f64_div", inv_exp_x, const_1, exp_x)

        # sum = E_X + 1.0/E_X
        sum_val = self._f64_alloc_temp("sum")
        self._f64_call_binary("_f64_add", sum_val, exp_x, inv_exp_x)

        # result = sum / 2.0
        result = self._f64_alloc_temp("cosh_result")
        self._f64_call_binary("_f64_div", result, sum_val, const_2)

        return result

    def _lower_float64_tanh(self, operand_expr):
        """tanh(x) = (E_2X - 1.0) / (E_2X + 1.0)  where E_2X = exp(2*x)

        Matches Ada implementation in adalib/ada-numerics-elementary_functions.adb
        """
        x_ptr = self._lower_float64_operand(operand_expr)

        # Generate local constants
        const_1 = self._lower_float64_literal(1.0)
        const_2 = self._lower_float64_literal(2.0)

        # two_x = 2.0 * x
        two_x = self._f64_alloc_temp("two_x")
        self._f64_call_binary("_f64_mul", two_x, const_2, x_ptr)

        # E_2X = exp(2*x)
        exp_2x = self._f64_alloc_temp("exp_2x")
        self._f64_call_unary("_f64_e2x", exp_2x, two_x)

        # num = E_2X - 1.0
        num = self._f64_alloc_temp("num")
        self._f64_call_binary("_f64_sub", num, exp_2x, const_1)

        # den = E_2X + 1.0
        den = self._f64_alloc_temp("den")
        self._f64_call_binary("_f64_add", den, exp_2x, const_1)

        # result = num / den
        result = self._f64_alloc_temp("tanh_result")
        self._f64_call_binary("_f64_div", result, num, den)

        return result

    def _lower_float64_coth(self, operand_expr):
        """coth(x) = 1.0 / tanh(x)

        Matches Ada implementation in adalib/ada-numerics-elementary_functions.adb
        """
        # First compute tanh(x)
        tanh_result = self._lower_float64_tanh(operand_expr)

        # Generate local constant
        const_1 = self._lower_float64_literal(1.0)

        # result = 1.0 / tanh(x)
        result = self._f64_alloc_temp("coth_result")
        self._f64_call_binary("_f64_div", result, const_1, tanh_result)

        return result

    def _lower_float64_arcsinh(self, operand_expr):
        """arcsinh(x) = log(x + sqrt(x*x + 1))

        Inlined implementation using primitive Float64 operations.
        See Ada reference: adalib/ada-numerics-elementary_functions.adb
        """
        x_ptr = self._lower_float64_operand(operand_expr)

        # x_sq = x * x
        x_sq = self._f64_alloc_temp("x_sq")
        self._f64_call_binary("_f64_mul", x_sq, x_ptr, x_ptr)

        # x_sq_plus_1 = x*x + 1
        x_sq_plus_1 = self._f64_alloc_temp("x_sq_plus_1")
        self._f64_call_binary("_f64_add", x_sq_plus_1, x_sq, Label("_const_one_f64"))

        # sqrt_val = sqrt(x*x + 1)
        sqrt_val = self._f64_alloc_temp("sqrt_val")
        self._f64_call_unary("_f64_sqrt", sqrt_val, x_sq_plus_1)

        # sum = x + sqrt(x*x + 1)
        sum_val = self._f64_alloc_temp("sum")
        self._f64_call_binary("_f64_add", sum_val, x_ptr, sqrt_val)

        # result = log(x + sqrt(x*x + 1))
        result = self._f64_alloc_temp("arcsinh_result")
        self._f64_call_unary("_f64_log", result, sum_val)

        return result

    def _lower_float64_arccosh(self, operand_expr):
        """arccosh(x) = log(x + sqrt(x*x - 1))

        Inlined implementation using primitive Float64 operations.
        See Ada reference: adalib/ada-numerics-elementary_functions.adb
        """
        x_ptr = self._lower_float64_operand(operand_expr)

        # x_sq = x * x
        x_sq = self._f64_alloc_temp("x_sq")
        self._f64_call_binary("_f64_mul", x_sq, x_ptr, x_ptr)

        # x_sq_minus_1 = x*x - 1
        x_sq_minus_1 = self._f64_alloc_temp("x_sq_minus_1")
        self._f64_call_binary("_f64_sub", x_sq_minus_1, x_sq, Label("_const_one_f64"))

        # sqrt_val = sqrt(x*x - 1)
        sqrt_val = self._f64_alloc_temp("sqrt_val")
        self._f64_call_unary("_f64_sqrt", sqrt_val, x_sq_minus_1)

        # sum = x + sqrt(x*x - 1)
        sum_val = self._f64_alloc_temp("sum")
        self._f64_call_binary("_f64_add", sum_val, x_ptr, sqrt_val)

        # result = log(x + sqrt(x*x - 1))
        result = self._f64_alloc_temp("arccosh_result")
        self._f64_call_unary("_f64_log", result, sum_val)

        return result

    def _lower_float64_arctanh(self, operand_expr):
        """arctanh(x) = 0.5 * log((1 + x) / (1 - x))

        Inlined implementation using primitive Float64 operations.
        See Ada reference: adalib/ada-numerics-elementary_functions.adb
        """
        x_ptr = self._lower_float64_operand(operand_expr)

        # Generate local constants
        const_1 = self._lower_float64_literal(1.0)
        const_2 = self._lower_float64_literal(2.0)

        # one_plus_x = 1 + x
        one_plus_x = self._f64_alloc_temp("one_plus_x")
        self._f64_call_binary("_f64_add", one_plus_x, const_1, x_ptr)

        # one_minus_x = 1 - x
        one_minus_x = self._f64_alloc_temp("one_minus_x")
        self._f64_call_binary("_f64_sub", one_minus_x, const_1, x_ptr)

        # ratio = (1 + x) / (1 - x)
        ratio = self._f64_alloc_temp("ratio")
        self._f64_call_binary("_f64_div", ratio, one_plus_x, one_minus_x)

        # log_ratio = log((1 + x) / (1 - x))
        log_ratio = self._f64_alloc_temp("log_ratio")
        self._f64_call_unary("_f64_log", log_ratio, ratio)

        # result = log_ratio / 2.0 (equivalent to 0.5 * log_ratio)
        result = self._f64_alloc_temp("arctanh_result")
        self._f64_call_binary("_f64_div", result, log_ratio, const_2)

        return result

    def _lower_float64_arccoth(self, operand_expr):
        """arccoth(x) = 0.5 * log((x + 1) / (x - 1))

        Matches Ada implementation in adalib/ada-numerics-elementary_functions.adb
        """
        x_ptr = self._lower_float64_operand(operand_expr)

        # Generate local constants
        const_1 = self._lower_float64_literal(1.0)
        const_2 = self._lower_float64_literal(2.0)

        # x_plus_1 = x + 1
        x_plus_1 = self._f64_alloc_temp("x_plus_1")
        self._f64_call_binary("_f64_add", x_plus_1, x_ptr, const_1)

        # x_minus_1 = x - 1
        x_minus_1 = self._f64_alloc_temp("x_minus_1")
        self._f64_call_binary("_f64_sub", x_minus_1, x_ptr, const_1)

        # ratio = (x + 1) / (x - 1)
        ratio = self._f64_alloc_temp("ratio")
        self._f64_call_binary("_f64_div", ratio, x_plus_1, x_minus_1)

        # log_ratio = log((x + 1) / (x - 1))
        log_ratio = self._f64_alloc_temp("log_ratio")
        self._f64_call_unary("_f64_log", log_ratio, ratio)

        # result = log_ratio / 2.0 (equivalent to 0.5 * log_ratio)
        result = self._f64_alloc_temp("arccoth_result")
        self._f64_call_binary("_f64_div", result, log_ratio, const_2)

        return result

    def _lower_float64_exp_func(self, operand_expr):
        """Lower Float64 exp function call (Ada.Numerics.Elementary_Functions.Exp).

        Calls _f64_e2x(result_ptr, src_ptr).
        Note: Named _f64_e2x (8 chars) to avoid symbol collision with _f64_exp_int.
        Stack layout after call:
          - IX+4 = src_ptr (Float64 pointer)
          - IX+6 = result_ptr (Float64 pointer)
        """
        # Get the operand as a Float64 pointer
        operand_ptr = self._lower_float64_operand(operand_expr)

        # Allocate 8 bytes on stack for result
        result_ptr = self.builder.new_vreg(IRType.PTR, "_f64_exp_result")
        self.builder.emit(IRInstr(
            OpCode.SUB,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            Immediate(8, IRType.WORD),
            comment="allocate 8 bytes for exp result"
        ))
        self.builder.emit(IRInstr(
            OpCode.MOV, result_ptr,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.PTR),
            comment="result_ptr = SP"
        ))

        # Push arguments: result_ptr (IX+6), src_ptr (IX+4)
        self.builder.push(result_ptr)   # result location (IX+6)
        self.builder.push(operand_ptr)  # source operand (IX+4)

        self.builder.call(Label("_f64_e2x"))  # Named _f64_e2x to avoid 8-char symbol collision with _f64_exp_int

        # Clean up pushed arguments (2 pointers = 4 bytes)
        self.builder.emit(IRInstr(
            OpCode.ADD,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            Immediate(4, IRType.WORD),
            comment="pop exp args"
        ))

        return result_ptr

    def _lower_float64_log(self, operand_expr):
        """Lower Float64 log (natural logarithm) function call.

        Calls _f64_log(result_ptr, src_ptr).
        Stack layout after call:
          - IX+4 = src_ptr (Float64 pointer)
          - IX+6 = result_ptr (Float64 pointer)
        """
        # Get the operand as a Float64 pointer
        operand_ptr = self._lower_float64_operand(operand_expr)

        # Allocate 8 bytes on stack for result
        result_ptr = self.builder.new_vreg(IRType.PTR, "_f64_log_result")
        self.builder.emit(IRInstr(
            OpCode.SUB,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            Immediate(8, IRType.WORD),
            comment="allocate 8 bytes for log result"
        ))
        self.builder.emit(IRInstr(
            OpCode.MOV, result_ptr,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.PTR),
            comment="result_ptr = SP"
        ))

        # Push arguments: result_ptr (IX+6), src_ptr (IX+4)
        self.builder.push(result_ptr)   # result location (IX+6)
        self.builder.push(operand_ptr)  # source operand (IX+4)

        self.builder.call(Label("_f64_log"))

        # Clean up pushed arguments (2 pointers = 4 bytes)
        self.builder.emit(IRInstr(
            OpCode.ADD,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            Immediate(4, IRType.WORD),
            comment="pop log args"
        ))

        return result_ptr

    def _lower_float64_log10(self, operand_expr):
        """log10(x) = log(x) / ln(10)"""
        # Get the operand as a Float64 pointer
        x_ptr = self._lower_float64_operand(operand_expr)

        # log(x)
        log_x = self._f64_alloc_temp("log_x")
        self._f64_call_unary("_f64_log", log_x, x_ptr)

        # log(x) / ln(10)
        result = self._f64_alloc_temp("log10_result")
        self._f64_call_binary("_f64_div", result, log_x, Label("_const_ln10"))

        return result

    def _lower_float64_log2(self, operand_expr):
        """log2(x) - call runtime _f64_lg2 function."""
        # Get the operand as a Float64 pointer
        x_ptr = self._lower_float64_operand(operand_expr)

        # Call _f64_lg2 runtime function
        result = self._f64_alloc_temp("log2_result")
        self._f64_call_unary("_f64_lg2", result, x_ptr)

        return result

    def _lower_declare_expr(self, expr: DeclareExpr):
        """Lower a declare expression (Ada 2022).

        Syntax: (declare declarations begin expression)
        Example: (declare X : Integer := 5; begin X + 1)
        """
        if self.ctx is None:
            return Immediate(0, IRType.WORD)

        # Process declarations - dynamically allocate locals
        for decl in expr.declarations:
            if isinstance(decl, ObjectDecl):
                for name in decl.names:
                    # Determine size (default to 2 bytes for Integer)
                    size = 2

                    # Create a virtual register for this local
                    vreg = self.builder.new_vreg(IRType.WORD, f"_{name}_decl")

                    # Add to locals table
                    self.ctx.locals[name.lower()] = LocalVariable(
                        name=name,
                        vreg=vreg,
                        stack_offset=self.ctx.locals_size,
                        size=size,
                        ada_type=None,  # Could resolve type if needed
                    )
                    self.ctx.locals_size += size

                    # Update function's locals_size
                    if self.ctx.function:
                        self.ctx.function.locals_size = self.ctx.locals_size

                    # Emit stack allocation
                    self.builder.emit(IRInstr(
                        OpCode.SUB,
                        MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
                        MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
                        Immediate(size, IRType.WORD),
                        comment=f"alloc {name} for declare expr"
                    ))

                    # Initialize if there's an init expression
                    if decl.init_expr:
                        init_val = self._lower_expr(decl.init_expr)
                        self.builder.mov(vreg, init_val, comment=f"init {name}")
            else:
                # Handle other declaration types if needed
                self._lower_decl(decl)

        # Evaluate and return the result expression
        return self._lower_expr(expr.result_expr)

    def _lower_delta_aggregate(self, expr: DeltaAggregate):
        """Lower a delta aggregate (Ada 2022).

        Syntax: (base_expression with delta component_associations)
        Creates a copy with specified components modified.
        """
        if self.ctx is None:
            return Immediate(0, IRType.WORD)

        # Get the ADDRESS of the base expression (not the value)
        base_addr = self._get_expr_address(expr.base_expression)
        if base_addr is None:
            # Fallback: try _get_arg_address
            base_addr = self._get_arg_address(expr.base_expression)

        # Try to get the record type from the base expression
        record_type = self._get_expr_type(expr.base_expression)

        # Determine record size
        size = 4  # Default record size
        if record_type and hasattr(record_type, 'size_bits') and record_type.size_bits:
            size = (record_type.size_bits + 7) // 8

        # Allocate a temp local in the frame for the result
        temp_name = f"_delta_tmp_{self._delta_tmp_count}"
        self._delta_tmp_count += 1
        temp_local = LocalVariable(
            name=temp_name,
            vreg=self.builder.new_vreg(IRType.WORD, temp_name),
            size=size,
            stack_offset=self.ctx.locals_size,
            ada_type=record_type,
        )
        self.ctx.locals_size += size
        self.ctx.locals[temp_name] = temp_local
        # Update func.locals_size so codegen allocates enough stack space
        if self.ctx.locals_size > self.ctx.function.locals_size:
            self.ctx.function.locals_size = self.ctx.locals_size

        # Get address of the temp
        frame_offset = -(temp_local.stack_offset + temp_local.size)
        result_ptr = self.builder.new_vreg(IRType.PTR, "_delta_result")
        self.builder.emit(IRInstr(
            OpCode.LEA, result_ptr,
            MemoryLocation(offset=frame_offset, ir_type=IRType.PTR, is_frame_offset=True),
            comment=f"addr of delta temp ({size} bytes)"
        ))

        # Copy the base record to the temp location
        if size <= 8:
            # For small records, copy word by word
            for offset in range(0, size, 2):
                temp = self.builder.new_vreg(IRType.WORD, "_copy_tmp")
                self.builder.load(
                    temp,
                    MemoryLocation(base=base_addr, offset=offset, ir_type=IRType.WORD),
                    comment=f"delta copy word {offset} from base"
                )
                self.builder.store(
                    MemoryLocation(base=result_ptr, offset=offset, ir_type=IRType.WORD),
                    temp,
                    comment=f"delta copy word {offset} to result"
                )
        else:
            # For larger records, call memcpy
            self.builder.push(result_ptr)
            self.builder.push(base_addr)
            self.builder.push(Immediate(size, IRType.WORD))
            self.builder.call(Label("_memcpy"))
            for _ in range(3):
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)

        # Build field info map if we have the record type
        field_info = {}
        if record_type and isinstance(record_type, RecordType):
            for comp in record_type.components:
                field_info[comp.name.lower()] = {
                    'offset': comp.offset_bits // 8,
                    'size': (comp.size_bits + 7) // 8 if comp.size_bits else 2
                }

        # Process each component modification
        for assoc in expr.components:
            if assoc.choices:
                for choice in assoc.choices:
                    if isinstance(choice, ExprChoice) and isinstance(choice.expr, Identifier):
                        field_name = choice.expr.name.lower()
                        if field_name in field_info:
                            value = self._lower_expr(assoc.value)
                            offset = field_info[field_name]['offset']
                            self.builder.store(
                                MemoryLocation(base=result_ptr, offset=offset, ir_type=IRType.WORD),
                                value,
                                comment=f"delta set {field_name} at offset {offset}"
                            )
                        elif assoc.value:
                            value = self._lower_expr(assoc.value)
                            self.builder.store(
                                MemoryLocation(base=result_ptr, offset=0, ir_type=IRType.WORD),
                                value,
                            )

        return result_ptr

    def _lower_container_aggregate(self, expr: ContainerAggregate):
        """Lower a container aggregate (Ada 2022).

        Syntax: [component_associations]
        Example: [for I in 1 .. 10 => I * 2]
        """
        if self.ctx is None:
            return Immediate(0, IRType.WORD)

        # Container aggregates are similar to regular aggregates
        # but use square brackets and are for container types

        # Determine size needed
        num_components = len(expr.components) if hasattr(expr, 'components') else 0

        # Check for iterated components to determine final size
        total_elements = 0
        for comp in expr.components:
            if hasattr(comp, 'iterator') and comp.iterator:
                # Iterated component: for I in 1 .. 10 => expr
                if hasattr(comp.iterator, 'iterable') and isinstance(comp.iterator.iterable, RangeExpr):
                    low = self._eval_static(comp.iterator.iterable.low)
                    high = self._eval_static(comp.iterator.iterable.high)
                    if low is not None and high is not None:
                        total_elements += high - low + 1
                    else:
                        total_elements += 10  # Fallback
                else:
                    total_elements += 1
            else:
                total_elements += 1

        size = total_elements * 2  # Word-sized elements

        if size == 0:
            return Immediate(0, IRType.PTR)

        # Reserve stack space
        container_ptr = self.builder.new_vreg(IRType.PTR, "_container_ptr")
        self.builder.emit(IRInstr(
            OpCode.SUB, container_ptr,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.PTR),
            Immediate(size, IRType.WORD),
            comment=f"allocate container ({size} bytes)"
        ))

        # Store container metadata (length at offset 0)
        self.builder.emit(IRInstr(
            OpCode.STORE, container_ptr, Immediate(total_elements, IRType.WORD),
            comment="store container length"
        ))

        # Initialize elements
        offset = 2  # Skip length field
        for comp in expr.components:
            if hasattr(comp, 'iterator') and comp.iterator:
                # Iterated component: generate loop to fill elements
                iter_var_name = comp.iterator.name if hasattr(comp.iterator, 'name') else "_i"
                iter_var = self.builder.new_vreg(IRType.WORD, f"_iter_{iter_var_name}")

                if hasattr(comp.iterator, 'iterable') and isinstance(comp.iterator.iterable, RangeExpr):
                    low_val = self._lower_expr(comp.iterator.iterable.low)
                    high_val = self._lower_expr(comp.iterator.iterable.high)

                    # Initialize iterator
                    self.builder.mov(iter_var, low_val)

                    # Loop to fill elements
                    loop_start = self._new_label("container_loop")
                    loop_end = self._new_label("container_end")
                    offset_reg = self.builder.new_vreg(IRType.WORD, "_offset")
                    self.builder.mov(offset_reg, Immediate(offset, IRType.WORD))

                    # Register iterator as local for value expression
                    old_local = self.ctx.locals.get(iter_var_name.lower())
                    self.ctx.locals[iter_var_name.lower()] = LocalVariable(
                        name=iter_var_name, vreg=iter_var, stack_offset=0, size=2, ada_type=None
                    )

                    self.builder.label(loop_start)

                    # Check loop condition
                    cond = self.builder.new_vreg(IRType.WORD, "_cond")
                    self.builder.cmp_gt(cond, iter_var, high_val)
                    self.builder.jnz(cond, Label(loop_end))

                    # Evaluate value expression and store
                    value = self._lower_expr(comp.value)
                    addr = self.builder.new_vreg(IRType.PTR, "_elem_addr")
                    self.builder.add(addr, container_ptr, offset_reg)
                    self.builder.store(addr, value)

                    # Increment offset and iterator
                    self.builder.add(offset_reg, offset_reg, Immediate(2, IRType.WORD))
                    self.builder.add(iter_var, iter_var, Immediate(1, IRType.WORD))
                    self.builder.jmp(Label(loop_start))

                    self.builder.label(loop_end)

                    # Restore old local
                    if old_local is not None:
                        self.ctx.locals[iter_var_name.lower()] = old_local
                    elif iter_var_name.lower() in self.ctx.locals:
                        del self.ctx.locals[iter_var_name.lower()]
            else:
                # Simple component
                value = self._lower_expr(comp.value)
                self._store_at_offset(container_ptr, offset, value)
                offset += 2

        return container_ptr

    def _lower_target_name(self, expr: TargetName):
        """Lower target name '@' (Ada 2022).

        The '@' symbol refers to the target of the enclosing assignment.
        Example: X := @ + 1;  -- equivalent to X := X + 1;
        """
        if self.ctx is None:
            return Immediate(0, IRType.WORD)

        target = self.ctx.assignment_target
        if target is None:
            # No enclosing assignment - return zero (semantic error)
            return Immediate(0, IRType.WORD)

        # Load the current value of the assignment target
        # This reuses the expression lowering logic
        if isinstance(target, Identifier):
            name = target.name.lower()

            # Check locals
            if name in self.ctx.locals:
                local = self.ctx.locals[name]
                return local.vreg

            # Check params
            if name in self.ctx.params:
                param_vreg = self.ctx.params[name]
                # For byref parameters (out/in out), dereference the pointer to get value
                if name in self.ctx.byref_params:
                    result = self.builder.new_vreg(IRType.WORD, f"_{name}_val")
                    self.builder.emit(IRInstr(
                        OpCode.LOAD, result,
                        MemoryLocation(offset=0, ir_type=IRType.WORD, base=param_vreg),
                        comment=f"deref byref param {name}"
                    ))
                    return result
                return param_vreg

            # Check globals (module-level variables)
            if name in self.globals:
                return self._load_global(name)

        elif isinstance(target, IndexedComponent):
            # Array element: load the current value
            return self._lower_indexed_load(target)

        elif isinstance(target, SelectedName):
            # Record field: load the current value
            return self._lower_selected_load(target)

        # Fallback for unsupported target types
        return Immediate(0, IRType.WORD)

    def _lower_aggregate(self, expr: Aggregate):
        """Lower an aggregate expression.

        For Z80, aggregates are built on the stack as temporary values.
        Returns a pointer to the aggregate in stack memory.
        """
        if self.ctx is None:
            return Immediate(0, IRType.WORD)

        # Try to get the aggregate's type from context (if available)
        agg_type = getattr(expr, 'resolved_type', None)

        # Build field info map if this is a record type
        # Include inherited components from parent types for derived tagged records
        field_info = {}
        if isinstance(agg_type, RecordType):
            # Collect all components including inherited ones
            # Include discriminants first (they precede components in layout)
            # Also include variant part components (fields inside CASE variants)
            all_comps = []
            rt = agg_type
            while rt is not None:
                all_comps.extend(rt.discriminants)
                all_comps.extend(rt.components)
                vp = getattr(rt, 'variant_part', None)
                if vp is not None:
                    for variant in vp.variants:
                        all_comps.extend(variant.components)
                rt = rt.parent_type
            for comp in all_comps:
                # Use component_type.size_bits for actual field size (comp.size_bits
                # is only set for packed records)
                comp_size_bits = comp.size_bits
                if comp_size_bits is None and comp.component_type:
                    comp_size_bits = comp.component_type.size_bits
                field_info[comp.name.lower()] = {
                    'offset': comp.offset_bits // 8,
                    'size': (comp_size_bits + 7) // 8 if comp_size_bits else 2
                }

        # Determine size of aggregate
        # For multi-dimensional arrays, detect if components are inner aggregates
        # and compute flat total size (rows * cols * ... * elem_size).
        is_multidim_array = False
        if isinstance(agg_type, ArrayType):
            size = agg_type.size_bytes()
            if size == 0:
                # Unconstrained array — compute from component count
                num_components = len(expr.components)
                elem_size = 2  # default
                if hasattr(agg_type, 'component_type') and agg_type.component_type:
                    ct = agg_type.component_type
                    if hasattr(ct, 'size_bits') and ct.size_bits:
                        elem_size = max(2, (ct.size_bits + 7) // 8)
                    elif hasattr(ct, 'size_bytes') and callable(ct.size_bytes):
                        sz = ct.size_bytes()
                        if sz and sz > 0:
                            elem_size = sz
                # Check if this is a multi-dimensional array aggregate
                # (components are inner Aggregates representing rows/slices)
                if (num_components > 0 and expr.components
                        and not expr.components[0].choices
                        and isinstance(expr.components[0].value, Aggregate)):
                    is_multidim_array = True
                    # Count total scalar elements across all inner aggregates
                    total_scalars = 0
                    for comp in expr.components:
                        if isinstance(comp.value, Aggregate):
                            total_scalars += len(comp.value.components)
                        else:
                            total_scalars += 1
                    size = total_scalars * elem_size
                else:
                    size = num_components * elem_size
        elif isinstance(agg_type, RecordType):
            size = agg_type.size_bytes()
        else:
            # Fall back to component count
            num_components = len(expr.components)
            size = num_components * 2

        # Allocate stack space for the aggregate
        agg_addr = self.builder.new_vreg(IRType.PTR, "_agg_tmp")

        # Reserve stack space
        if size > 0:
            self.builder.emit(IRInstr(
                OpCode.SUB,
                MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
                MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
                Immediate(size, IRType.WORD),
                comment=f"allocate aggregate ({size} bytes)"
            ))
            # Point agg_addr to the allocated space
            self.builder.emit(IRInstr(
                OpCode.MOV, agg_addr,
                MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
                comment="aggregate base address"
            ))
            # Zero-initialize aggregate space to avoid garbage in unwritten bytes
            # (important for record aggregates where memcmp is used for comparison)
            for zero_off in range(0, size, 2):
                self.builder.store(
                    MemoryLocation(base=agg_addr, offset=zero_off, ir_type=IRType.WORD),
                    Immediate(0, IRType.WORD),
                    comment="zero-init" if zero_off == 0 else None,
                )

        # Track current positional offset for positional aggregates
        positional_offset = 0
        positional_field_index = 0  # Index into field_info for positional record fields
        others_value = None
        assigned_fields = set()  # Track which record fields have been explicitly assigned

        # First pass: find others clause if present
        for comp in expr.components:
            if comp.choices:
                for choice in comp.choices:
                    if isinstance(choice, OthersChoice):
                        others_value = comp.value
                        break

        # Second pass: process each component
        for comp in expr.components:
            # Skip others - handled separately
            is_others = False
            if comp.choices:
                for choice in comp.choices:
                    if isinstance(choice, OthersChoice):
                        is_others = True
                        break
            if is_others:
                continue

            # Determine where to store this value
            if comp.choices:
                # Named aggregate: (X => 1, Y => 2) or (1 .. 5 => 0)
                for choice in comp.choices:
                    if isinstance(choice, ExprChoice):
                        if isinstance(choice.expr, Identifier):
                            # Named field - look up its offset
                            field_name = choice.expr.name.lower()
                            if field_name in field_info:
                                offset = field_info[field_name]['offset']
                                field_size = field_info[field_name]['size']
                            else:
                                # Field not found in type info, use positional
                                offset = positional_offset
                                field_size = 2
                                positional_offset += 2
                            assigned_fields.add(field_name)
                            # Use correct IRType based on field size to avoid
                            # overwriting adjacent fields (e.g., 1-byte Boolean)
                            field_ir_type = IRType.BYTE if field_size == 1 else IRType.WORD
                            # Check if field is a multi-byte record type
                            if field_size > 2 and self._is_record_typed_field(field_name, agg_type):
                                src_addr = self._get_expr_address(comp.value)
                                if src_addr is not None:
                                    dst_addr = self.builder.new_vreg(IRType.PTR, f"_{field_name}_dst")
                                    self.builder.add(dst_addr, agg_addr, Immediate(offset, IRType.WORD))
                                    self._emit_memcpy(dst_addr, src_addr, field_size, f"field {field_name}")
                                else:
                                    value = self._lower_expr(comp.value)
                                    mem = MemoryLocation(base=agg_addr, offset=offset, ir_type=field_ir_type)
                                    self.builder.store(mem, value, comment=f"field {field_name}")
                            else:
                                value = self._lower_expr(comp.value)
                                mem = MemoryLocation(base=agg_addr, offset=offset, ir_type=field_ir_type)
                                self.builder.store(mem, value, comment=f"field {field_name}")
                        else:
                            # Index expression for array aggregate
                            value = self._lower_expr(comp.value)
                            idx = self._lower_expr(choice.expr)
                            # Calculate offset: (index - agg_lower_bound) * element_size
                            # Use type's lower bound as base; for sliding, both aggregate
                            # and target have matching lengths so this is consistent
                            elem_size = agg_type.element_size_bytes() if isinstance(agg_type, ArrayType) else 2
                            lower_bound = agg_type.bounds[0][0] if isinstance(agg_type, ArrayType) and agg_type.bounds else 1
                            adj_idx = self.builder.new_vreg(IRType.WORD, "_adj_idx")
                            self.builder.sub(adj_idx, idx, Immediate(lower_bound, IRType.WORD))
                            offset_reg = self.builder.new_vreg(IRType.WORD, "_idx_off")
                            self.builder.mul(offset_reg, adj_idx, Immediate(elem_size, IRType.WORD))
                            addr_reg = self.builder.new_vreg(IRType.PTR, "_elem_addr")
                            self.builder.add(addr_reg, agg_addr, offset_reg)
                            mem = MemoryLocation(base=addr_reg, offset=0, ir_type=IRType.WORD)
                            self.builder.store(mem, value)
                    elif isinstance(choice, RangeChoice):
                        # Range association: (6 .. 8 => 0)
                        # Offset computed as (loop_var - range_low) * elem_size
                        # This handles sliding: the aggregate fills positions 0, 1, 2, ...
                        value = self._lower_expr(comp.value)
                        low = self._lower_expr(choice.range_expr.low)
                        high = self._lower_expr(choice.range_expr.high)
                        elem_size = agg_type.element_size_bytes() if isinstance(agg_type, ArrayType) else 2
                        # Generate loop to fill range
                        loop_var = self.builder.new_vreg(IRType.WORD, "_range_idx")
                        self.builder.mov(loop_var, low)
                        loop_start = self.builder.new_label("agg_range_loop")
                        loop_end = self.builder.new_label("agg_range_end")
                        self.builder.label(loop_start)
                        self.builder.cmp(loop_var, high)
                        self.builder.jg(loop_end)
                        # Store value at offset: (loop_var - low) * elem_size
                        adj_idx = self.builder.new_vreg(IRType.WORD, "_adj_idx")
                        self.builder.sub(adj_idx, loop_var, low)
                        offset_reg = self.builder.new_vreg(IRType.WORD, "_range_off")
                        self.builder.mul(offset_reg, adj_idx, Immediate(elem_size, IRType.WORD))
                        addr_reg = self.builder.new_vreg(IRType.PTR, "_elem_addr")
                        self.builder.add(addr_reg, agg_addr, offset_reg)
                        mem = MemoryLocation(base=addr_reg, offset=0, ir_type=IRType.WORD)
                        self.builder.store(mem, value)
                        # Increment and loop
                        self.builder.add(loop_var, loop_var, Immediate(1, IRType.WORD))
                        self.builder.jmp(loop_start)
                        self.builder.label(loop_end)
            else:
                # Positional aggregate: (1, 2, 3)
                if is_multidim_array and isinstance(comp.value, Aggregate):
                    # Multi-dimensional array: flatten inner aggregate into outer
                    inner_agg = comp.value
                    for inner_comp in inner_agg.components:
                        if inner_comp.choices:
                            # Named inner component — just lower it normally
                            inner_val = self._lower_expr(inner_comp.value)
                            mem = MemoryLocation(base=agg_addr, offset=positional_offset, ir_type=IRType.WORD)
                            self.builder.store(mem, inner_val)
                            positional_offset += 2
                        else:
                            inner_val = self._lower_expr(inner_comp.value)
                            mem = MemoryLocation(base=agg_addr, offset=positional_offset, ir_type=IRType.WORD)
                            self.builder.store(mem, inner_val)
                            positional_offset += 2
                else:
                    value = self._lower_expr(comp.value)
                    # For record aggregates, use field_info to map positional
                    # index to the correct field offset and size
                    if isinstance(agg_type, RecordType) and field_info:
                        ordered = list(field_info.keys())
                        if positional_field_index < len(ordered):
                            pos_field = ordered[positional_field_index]
                            offset = field_info[pos_field]['offset']
                            fsize = field_info[pos_field]['size']
                            assigned_fields.add(pos_field)
                            # For composite fields (string/array > 2 bytes), copy data
                            # instead of storing the pointer
                            if fsize > 2 and isinstance(comp.value, (StringLiteral, Aggregate)):
                                dst_addr = self.builder.new_vreg(IRType.PTR, f"_{pos_field}_dst")
                                if offset != 0:
                                    self.builder.add(dst_addr, agg_addr, Immediate(offset, IRType.WORD))
                                else:
                                    self.builder.mov(dst_addr, agg_addr)
                                # For string literals, value is a pointer to string data
                                # For aggregates, value is a pointer to aggregate data
                                # Determine actual copy size from the expression
                                copy_size = fsize
                                if isinstance(comp.value, StringLiteral):
                                    copy_size = min(fsize, len(comp.value.value))
                                self._emit_memcpy(dst_addr, value, copy_size,
                                                  f"copy composite to field {pos_field}")
                                positional_field_index += 1
                                positional_offset += fsize
                                continue
                            field_ir_type = IRType.BYTE if fsize == 1 else IRType.WORD
                            mem = MemoryLocation(base=agg_addr, offset=offset,
                                                 ir_type=field_ir_type)
                        else:
                            mem = MemoryLocation(base=agg_addr, offset=positional_offset,
                                                 ir_type=IRType.WORD)
                        positional_field_index += 1
                    else:
                        mem = MemoryLocation(base=agg_addr, offset=positional_offset,
                                             ir_type=IRType.WORD)
                    self.builder.store(mem, value)
                    # Advance by actual field size when record field_info is available
                    if isinstance(agg_type, RecordType) and field_info:
                        ordered = list(field_info.keys())
                        if positional_field_index - 1 < len(ordered):
                            fsize = field_info[ordered[positional_field_index - 1]]['size']
                            positional_offset += max(fsize, 2) if fsize != 1 else 1
                        else:
                            positional_offset += 2
                    else:
                        positional_offset += 2

        # Handle others clause - fill remaining fields/elements
        if others_value is not None:
            # Check if the expression has side effects (allocator, function call)
            # If so, re-evaluate per element; otherwise evaluate once
            has_side_effects = isinstance(others_value, (FunctionCall, Allocator))
            if not has_side_effects:
                others_val = self._lower_expr(others_value)
            if isinstance(agg_type, RecordType):
                # For records: fill unassigned fields with OTHERS value.
                # Only fill fields from the active variant (determined by
                # which variant contains explicitly assigned fields).
                # Discriminants and common fields are always filled.
                active_variant_fields = set()
                vp = getattr(agg_type, 'variant_part', None)
                if vp is not None:
                    # Find which variant is active based on assigned fields
                    for variant in vp.variants:
                        variant_names = {c.name.lower() for c in variant.components}
                        if variant_names & assigned_fields:
                            # This variant has explicitly assigned fields
                            active_variant_fields = variant_names
                            break
                    if not active_variant_fields:
                        # No explicit variant field assigned; try to determine
                        # from discriminant value (e.g., positional TRUE/FALSE)
                        disc_name = vp.discriminant_name.lower()
                        disc_value = None
                        # Check if discriminant was set positionally or by name
                        for comp in expr.components:
                            if comp.choices:
                                for ch in comp.choices:
                                    if isinstance(ch, ExprChoice) and isinstance(ch.expr, Identifier):
                                        if ch.expr.name.lower() == disc_name:
                                            # Named disc assignment
                                            if isinstance(comp.value, Identifier):
                                                disc_value = comp.value.name.upper()
                                            elif isinstance(comp.value, IntegerLiteral):
                                                disc_value = str(comp.value.value)
                            else:
                                # First positional = discriminant
                                if isinstance(comp.value, Identifier):
                                    disc_value = comp.value.name.upper()
                                elif isinstance(comp.value, IntegerLiteral):
                                    disc_value = str(comp.value.value)
                                break  # Only first positional is discriminant
                        if disc_value:
                            # Match disc_value against variant choices
                            for variant in vp.variants:
                                for ch in variant.choices:
                                    choice_name = None
                                    if hasattr(ch, 'expr'):
                                        if hasattr(ch.expr, 'name'):
                                            choice_name = ch.expr.name.upper()
                                        elif hasattr(ch.expr, 'value'):
                                            choice_name = str(ch.expr.value)
                                    if choice_name == disc_value:
                                        active_variant_fields = {
                                            c.name.lower() for c in variant.components}
                                        break
                                if active_variant_fields:
                                    break
                        if not active_variant_fields:
                            # Still couldn't determine; default to all variants
                            for variant in vp.variants:
                                active_variant_fields.update(
                                    c.name.lower() for c in variant.components)

                # Collect fields eligible for OTHERS
                # Include: discriminants, common fields, active variant fields
                all_variant_fields = set()
                if vp is not None:
                    for variant in vp.variants:
                        all_variant_fields.update(
                            c.name.lower() for c in variant.components)

                for fname, finfo in field_info.items():
                    if fname in assigned_fields:
                        continue
                    # Skip fields from inactive variants
                    if fname in all_variant_fields and fname not in active_variant_fields:
                        continue
                    if has_side_effects:
                        others_val = self._lower_expr(others_value)
                    # Use correct IRType based on field size
                    field_ir_type = IRType.BYTE if finfo['size'] == 1 else IRType.WORD
                    mem = MemoryLocation(base=agg_addr, offset=finfo['offset'],
                                         ir_type=field_ir_type)
                    self.builder.store(mem, others_val,
                                       comment=f"others field {fname}")
            elif isinstance(agg_type, ArrayType):
                # For arrays: fill all elements from positional_offset to end
                element_size = 2  # default
                if agg_type.component_type:
                    es = agg_type.component_type.size_bytes()
                    if es and es > 0:
                        element_size = es
                total_elements = size // element_size if element_size > 0 else 0
                # positional_offset tracks bytes written positionally
                filled_elements = positional_offset // element_size if element_size > 0 else 0
                if filled_elements < total_elements:
                    # Generate loop to fill remaining elements
                    loop_idx = self.builder.new_vreg(IRType.WORD, "_oth_idx")
                    self.builder.mov(loop_idx, Immediate(filled_elements * element_size, IRType.WORD))
                    loop_end_off = total_elements * element_size
                    loop_start = self.builder.new_label("agg_others_loop")
                    loop_end = self.builder.new_label("agg_others_end")
                    self.builder.label(loop_start)
                    self.builder.cmp(loop_idx, Immediate(loop_end_off, IRType.WORD))
                    self.builder.jge(loop_end)
                    # Re-evaluate per element for side-effect expressions
                    if has_side_effects:
                        others_val = self._lower_expr(others_value)
                    addr_reg = self.builder.new_vreg(IRType.PTR, "_oth_addr")
                    self.builder.add(addr_reg, agg_addr, loop_idx)
                    mem = MemoryLocation(base=addr_reg, offset=0, ir_type=IRType.WORD)
                    self.builder.store(mem, others_val)
                    self.builder.add(loop_idx, loop_idx, Immediate(element_size, IRType.WORD))
                    self.builder.jmp(loop_start)
                    self.builder.label(loop_end)

        return agg_addr

    def _lower_aggregate_to_target(self, expr: Aggregate, target_addr, target_type,
                                    lower_bound_override=None):
        """Lower an aggregate directly to a target address.

        Used when the target type is known (e.g., record assignment).
        Supports:
        - Positional aggregates: (1, 2, 3)
        - Named aggregates: (X => 1, Y => 2)
        - Range associations: (1 .. 5 => 0)
        - Others clause: (others => 0)

        Args:
            lower_bound_override: If provided, use this as the lower bound for
                array offset calculations instead of deriving from the type.
                Useful when the type is unconstrained but the declaration has
                a known lower bound.
        """
        if self.ctx is None:
            return

        # For record aggregates with known target type
        if isinstance(target_type, RecordType):
            # Map component names to offsets, sizes, and types
            # Include inherited components from parent types
            field_info = {}
            ordered_fields = []

            # Collect inherited components first (from parent types)
            def collect_inherited(rec_type):
                if rec_type.parent_type:
                    collect_inherited(rec_type.parent_type)
                # Include discriminants first (they precede components in layout)
                for disc in rec_type.discriminants:
                    field_info[disc.name.lower()] = {
                        'offset': disc.offset_bits // 8,
                        'size': (disc.size_bits + 7) // 8 if disc.size_bits else 2,
                        'type': disc.component_type
                    }
                    ordered_fields.append(disc.name.lower())
                for comp in rec_type.components:
                    field_info[comp.name.lower()] = {
                        'offset': comp.offset_bits // 8,
                        'size': (comp.size_bits + 7) // 8 if comp.size_bits else 2,
                        'type': comp.component_type
                    }
                    ordered_fields.append(comp.name.lower())

            collect_inherited(target_type)

            # Track which fields have been assigned
            assigned_fields = set()
            positional_index = 0  # Current field index for positional assignment

            # First pass: handle explicit assignments
            others_value = None
            for comp_assoc in expr.components:
                if comp_assoc.choices:
                    for choice in comp_assoc.choices:
                        if isinstance(choice, OthersChoice):
                            others_value = comp_assoc.value
                            continue
                        if isinstance(choice, ExprChoice):
                            if isinstance(choice.expr, Identifier):
                                field_name = choice.expr.name.lower()
                                if field_name in field_info:
                                    offset = field_info[field_name]['offset']
                                    field_type = field_info[field_name]['type']
                                    field_size = field_info[field_name]['size']
                                    # Handle nested aggregates for record/array fields
                                    if isinstance(comp_assoc.value, Aggregate) and isinstance(field_type, (RecordType, ArrayType)):
                                        # Compute field address and recursively init
                                        field_addr = self.builder.new_vreg(IRType.PTR, f"_{field_name}_addr")
                                        self.builder.add(field_addr, target_addr, Immediate(offset, IRType.WORD))
                                        self._lower_aggregate_to_target(comp_assoc.value, field_addr, field_type)
                                    elif isinstance(comp_assoc.value, StringLiteral) and isinstance(field_type, ArrayType) and field_size > 2:
                                        # String literal into array/string field — copy data not pointer
                                        value = self._lower_expr(comp_assoc.value)
                                        field_addr = self.builder.new_vreg(IRType.PTR, f"_{field_name}_addr")
                                        self.builder.add(field_addr, target_addr, Immediate(offset, IRType.WORD))
                                        copy_size = min(field_size, len(comp_assoc.value.value))
                                        self._emit_memcpy(field_addr, value, copy_size,
                                                          f"copy string to named field {field_name}")
                                    else:
                                        value = self._lower_expr(comp_assoc.value)
                                        self._store_at_offset(target_addr, offset, value)
                                    assigned_fields.add(field_name)
                else:
                    # Positional assignment - use field order
                    if positional_index < len(ordered_fields):
                        field_name = ordered_fields[positional_index]
                        if field_name in field_info:
                            offset = field_info[field_name]['offset']
                            field_type = field_info[field_name]['type']
                            field_size = field_info[field_name]['size']
                            # Handle nested aggregates for record/array fields
                            if isinstance(comp_assoc.value, Aggregate) and isinstance(field_type, (RecordType, ArrayType)):
                                # Compute field address and recursively init
                                field_addr = self.builder.new_vreg(IRType.PTR, f"_{field_name}_addr")
                                self.builder.add(field_addr, target_addr, Immediate(offset, IRType.WORD))
                                self._lower_aggregate_to_target(comp_assoc.value, field_addr, field_type)
                            elif isinstance(comp_assoc.value, StringLiteral) and isinstance(field_type, ArrayType) and field_size > 2:
                                # String literal into array/string field — copy data not pointer
                                value = self._lower_expr(comp_assoc.value)
                                field_addr = self.builder.new_vreg(IRType.PTR, f"_{field_name}_addr")
                                self.builder.add(field_addr, target_addr, Immediate(offset, IRType.WORD))
                                copy_size = min(field_size, len(comp_assoc.value.value))
                                self._emit_memcpy(field_addr, value, copy_size,
                                                  f"copy string to field {field_name}")
                            else:
                                value = self._lower_expr(comp_assoc.value)
                                self._store_at_offset(target_addr, offset, value)
                            assigned_fields.add(field_name)
                        positional_index += 1

            # Second pass: apply 'others' to unassigned fields
            if others_value is not None:
                value = self._lower_expr(others_value)
                for field_name, info in field_info.items():
                    if field_name not in assigned_fields:
                        self._store_at_offset(target_addr, info['offset'], value)

        # For array aggregates
        elif isinstance(target_type, ArrayType):
            element_size = 2  # Default
            if target_type.component_type:
                element_size = (target_type.component_type.size_bits + 7) // 8
                # On Z80, non-packed array elements use 16-bit words minimum
                if not target_type.is_packed and element_size < 2:
                    # String arrays (Character component) stay at 1 byte
                    comp_name = getattr(target_type.component_type, 'name', '').lower()
                    if comp_name != 'character':
                        element_size = 2

            # Get array bounds
            lower_bound = 1
            upper_bound = 10  # Default
            if target_type.bounds:
                lower_bound = target_type.bounds[0][0]
                upper_bound = target_type.bounds[0][1]
            # Apply lower_bound override (for unconstrained arrays with known lower bound)
            if lower_bound_override is not None:
                lower_bound = lower_bound_override

            # Handle multi-dimensional arrays
            # For a 2D array like Matrix(1..3, 1..3), each row aggregate fills a slice
            is_multidim = target_type.bounds and len(target_type.bounds) > 1
            row_size = 0
            row_type = None
            if is_multidim:
                # Calculate row size: product of remaining dimensions * element_size
                row_count = 1
                for i in range(1, len(target_type.bounds)):
                    dim_low, dim_high = target_type.bounds[i]
                    row_count *= (dim_high - dim_low + 1)
                row_size = row_count * element_size
                # Create a 1D array type for each row
                row_type = ArrayType(
                    name="row",
                    component_type=target_type.component_type,
                    bounds=[target_type.bounds[1]] if len(target_type.bounds) > 1 else [(1, row_count)],
                    is_constrained=True,
                )

            # Track which indices have been assigned
            assigned_indices = set()
            others_value = None
            positional_index = lower_bound

            for comp_assoc in expr.components:
                if comp_assoc.choices:
                    for choice in comp_assoc.choices:
                        if isinstance(choice, OthersChoice):
                            others_value = comp_assoc.value
                        elif isinstance(choice, RangeChoice):
                            # Range association: (6 .. 8 => value)
                            # Use (idx - range_low) for offset: handles sliding when
                            # aggregate indices differ from target bounds
                            range_low = self._eval_static(choice.range_expr.low)
                            range_high = self._eval_static(choice.range_expr.high)
                            if range_low is not None and range_high is not None:
                                if is_multidim and row_type and isinstance(comp_assoc.value, Aggregate):
                                    # Multi-dim: recursively init each row
                                    for pos, idx in enumerate(range(range_low, range_high + 1)):
                                        offset = pos * row_size
                                        row_addr = self.builder.new_vreg(IRType.PTR, f"_row_{idx}_addr")
                                        self.builder.add(row_addr, target_addr, Immediate(offset, IRType.WORD))
                                        self._lower_aggregate_to_target(comp_assoc.value, row_addr, row_type)
                                        assigned_indices.add(idx)
                                else:
                                    value = self._lower_expr(comp_assoc.value)
                                    elem_ir_type = IRType.BYTE if element_size == 1 else IRType.WORD
                                    for pos, idx in enumerate(range(range_low, range_high + 1)):
                                        offset = pos * element_size
                                        self._store_at_offset(target_addr, offset, value, ir_type=elem_ir_type)
                                        assigned_indices.add(idx)
                            else:
                                # Dynamic range (e.g., 1 .. IDENT_INT(5) => 0)
                                # Generate a runtime loop to fill the range
                                dyn_low = self._lower_expr(choice.range_expr.low)
                                dyn_high = self._lower_expr(choice.range_expr.high)
                                value = self._lower_expr(comp_assoc.value)
                                # Loop: for i := dyn_low to dyn_high: store value at offset (i - lower_bound) * elem_size
                                loop_idx = self.builder.new_vreg(IRType.WORD, "_rng_i")
                                self.builder.mov(loop_idx, dyn_low)
                                loop_label = self.builder.new_label("agg_rng_lp")
                                done_label = self.builder.new_label("agg_rng_dn")
                                self.builder.label(loop_label)
                                # Check if i > dyn_high
                                loop_done = self.builder.new_vreg(IRType.WORD, "_rng_done")
                                self.builder.cmp_gt(loop_done, loop_idx, dyn_high)
                                self.builder.jnz(loop_done, done_label)
                                # Compute offset = (i - lower_bound) * element_size
                                dyn_offset = self.builder.new_vreg(IRType.WORD, "_rng_off")
                                self.builder.sub(dyn_offset, loop_idx, Immediate(lower_bound, IRType.WORD))
                                if element_size == 2:
                                    self.builder.add(dyn_offset, dyn_offset, dyn_offset)  # * 2
                                elif element_size != 1:
                                    self.builder.mul(dyn_offset, dyn_offset, Immediate(element_size, IRType.WORD))
                                # Store value at target_addr + offset
                                dyn_addr = self.builder.new_vreg(IRType.PTR, "_rng_addr")
                                self.builder.add(dyn_addr, target_addr, dyn_offset)
                                store_type = IRType.BYTE if element_size == 1 else IRType.WORD
                                self.builder.emit(IRInstr(
                                    OpCode.STORE,
                                    MemoryLocation(base=dyn_addr, offset=0, ir_type=store_type),
                                    value,
                                    comment="dynamic range aggregate store"
                                ))
                                # i += 1
                                self.builder.add(loop_idx, loop_idx, Immediate(1, IRType.WORD))
                                self.builder.jmp(loop_label)
                                self.builder.label(done_label)
                        elif isinstance(choice, ExprChoice):
                            # Named index: (5 => value) or (Index_Name => value)
                            idx = self._eval_static(choice.expr)
                            if idx is not None:
                                if is_multidim and row_type and isinstance(comp_assoc.value, Aggregate):
                                    offset = (idx - lower_bound) * row_size
                                    row_addr = self.builder.new_vreg(IRType.PTR, f"_row_{idx}_addr")
                                    self.builder.add(row_addr, target_addr, Immediate(offset, IRType.WORD))
                                    self._lower_aggregate_to_target(comp_assoc.value, row_addr, row_type)
                                else:
                                    value = self._lower_expr(comp_assoc.value)
                                    offset = (idx - lower_bound) * element_size
                                    elem_ir_type = IRType.BYTE if element_size == 1 else IRType.WORD
                                    self._store_at_offset(target_addr, offset, value, ir_type=elem_ir_type)
                                assigned_indices.add(idx)
                            else:
                                # Dynamic index expression (e.g., Ident_Int(1) => 0)
                                # Evaluate the index and value at runtime
                                idx_vreg = self._lower_expr(choice.expr)
                                value = self._lower_expr(comp_assoc.value)
                                # Compute offset = (idx - lower_bound) * element_size
                                dyn_offset = self.builder.new_vreg(IRType.WORD, "_dyn_idx_off")
                                self.builder.sub(dyn_offset, idx_vreg, Immediate(lower_bound, IRType.WORD))
                                if element_size == 2:
                                    self.builder.add(dyn_offset, dyn_offset, dyn_offset)  # * 2
                                elif element_size != 1:
                                    self.builder.mul(dyn_offset, dyn_offset, Immediate(element_size, IRType.WORD))
                                # Store value at target_addr + dyn_offset
                                dyn_addr = self.builder.new_vreg(IRType.PTR, "_dyn_elem_addr")
                                self.builder.add(dyn_addr, target_addr, dyn_offset)
                                store_type = IRType.BYTE if element_size == 1 else IRType.WORD
                                self.builder.emit(IRInstr(
                                    OpCode.STORE,
                                    MemoryLocation(base=dyn_addr, offset=0, ir_type=store_type),
                                    value,
                                    comment="dynamic index aggregate store"
                                ))
                else:
                    # Positional association
                    # For multi-dimensional arrays, use row_size for offset calculation
                    if is_multidim and row_type:
                        offset = (positional_index - lower_bound) * row_size
                        # Handle row aggregate for 2D arrays
                        if isinstance(comp_assoc.value, Aggregate):
                            # Compute row address and recursively init with row_type
                            row_addr = self.builder.new_vreg(IRType.PTR, f"_row_{positional_index}_addr")
                            self.builder.add(row_addr, target_addr, Immediate(offset, IRType.WORD))
                            self._lower_aggregate_to_target(comp_assoc.value, row_addr, row_type)
                        else:
                            value = self._lower_expr(comp_assoc.value)
                            self._store_at_offset(target_addr, offset, value)
                    else:
                        offset = (positional_index - lower_bound) * element_size
                        elem_ir_type = IRType.BYTE if element_size == 1 else IRType.WORD
                        # Handle nested aggregates for arrays of records/arrays
                        if isinstance(comp_assoc.value, Aggregate) and target_type.component_type:
                            comp_type = target_type.component_type
                            if isinstance(comp_type, (RecordType, ArrayType)):
                                # Compute element address and recursively init
                                elem_addr = self.builder.new_vreg(IRType.PTR, f"_elem_{positional_index}_addr")
                                self.builder.add(elem_addr, target_addr, Immediate(offset, IRType.WORD))
                                self._lower_aggregate_to_target(comp_assoc.value, elem_addr, comp_type)
                            else:
                                value = self._lower_expr(comp_assoc.value)
                                self._store_at_offset(target_addr, offset, value, ir_type=elem_ir_type)
                        else:
                            value = self._lower_expr(comp_assoc.value)
                            self._store_at_offset(target_addr, offset, value, ir_type=elem_ir_type)
                    assigned_indices.add(positional_index)
                    positional_index += 1

            # Apply 'others' to unassigned indices
            if others_value is not None:
                # Re-evaluate per element for side-effect expressions (allocator, function call)
                has_side_effects = isinstance(others_value, (FunctionCall, Allocator))
                if not has_side_effects:
                    value = self._lower_expr(others_value)
                elem_ir_type = IRType.BYTE if element_size == 1 else IRType.WORD
                for idx in range(lower_bound, upper_bound + 1):
                    if idx not in assigned_indices:
                        if has_side_effects:
                            value = self._lower_expr(others_value)
                        offset = (idx - lower_bound) * element_size
                        self._store_at_offset(target_addr, offset, value, ir_type=elem_ir_type)

    def _store_at_offset(self, base_addr, offset: int, value, ir_type=None) -> None:
        """Store a value at a given offset from a base address."""
        store_ir_type = ir_type or IRType.WORD
        if offset != 0:
            addr = self.builder.new_vreg(IRType.PTR, "_addr")
            self.builder.add(addr, base_addr, Immediate(offset, IRType.WORD))
            mem = MemoryLocation(base=addr, offset=0, ir_type=store_ir_type)
        else:
            mem = MemoryLocation(base=base_addr, offset=0, ir_type=store_ir_type)
        self.builder.store(mem, value)

    def _get_expr_address(self, expr) -> Optional[VReg]:
        """Get the address of an expression (for block copies of record-typed values).

        Returns a VReg containing the address, or None if the address cannot be determined.
        Used when we need to copy multi-byte values (e.g., record-typed component defaults).
        The Label name must be the final mangled assembly symbol (lowercase with _ prefix).
        """
        if isinstance(expr, Identifier):
            name = expr.name.lower()
            # Check locals
            if self.ctx and name in self.ctx.locals:
                local = self.ctx.locals[name]
                result = self.builder.new_vreg(IRType.PTR, f"_addr_{name}")
                frame_offset = -(local.stack_offset + local.size)
                self.builder.emit(IRInstr(
                    OpCode.LEA, result,
                    MemoryLocation(offset=frame_offset, ir_type=IRType.PTR, is_frame_offset=True),
                    comment=f"address of local {name}"
                ))
                return result
            # Check params (byref params like records/large arrays already hold an address)
            if self.ctx and name in self.ctx.params:
                param_vreg = self.ctx.params[name]
                if name in self.ctx.record_params or name in self.ctx.byref_params:
                    # Param is already a pointer — return it directly
                    return param_vreg
                # For value params, we can't easily get the stack address at IR level,
                # so return None and let the caller handle it
                return None
            # Check globals using _find_global_name (handles package prefix)
            if self.builder.module:
                global_name = self._find_global_name(name)
                if global_name and global_name.lower() != name.lower():
                    # Only use if we actually found a prefixed global (not just the name echoed back)
                    asm_label = f"_{global_name.lower()}" if not global_name.startswith("_") else global_name.lower()
                    result = self.builder.new_vreg(IRType.PTR, f"_addr_{name}")
                    self.builder.emit(IRInstr(
                        OpCode.LEA, result,
                        Label(asm_label),
                        comment=f"address of {name}"
                    ))
                    return result
                # Check if name is actually in globals (exact match)
                if global_name and any(gn.lower() == global_name.lower() for gn in self.builder.module.globals):
                    asm_label = f"_{global_name.lower()}" if not global_name.startswith("_") else global_name.lower()
                    result = self.builder.new_vreg(IRType.PTR, f"_addr_{name}")
                    self.builder.emit(IRInstr(
                        OpCode.LEA, result,
                        Label(asm_label),
                        comment=f"address of {name}"
                    ))
                    return result
        elif isinstance(expr, SelectedName):
            # Package-qualified name like C3900010.Default_Time
            full_dotted = self._get_selected_name_str(expr).lower()
            global_name = full_dotted.replace(".", "_")
            # Assembly label is "_" + lowercased name
            asm_label = f"_{global_name}"
            result = self.builder.new_vreg(IRType.PTR, f"_addr_{global_name}")
            self.builder.emit(IRInstr(
                OpCode.LEA, result,
                Label(asm_label),
                comment=f"address of {full_dotted}"
            ))
            return result
        return None

    def _get_global_name(self, name: str) -> Optional[str]:
        """Get the global symbol name for a given identifier name.

        Delegates to _find_global_name which searches using package prefix stack.
        """
        result = self._find_global_name(name)
        return result if result else None

    def _is_record_typed_field(self, field_name: str, record_type) -> bool:
        """Check if a field in a record type has a RecordType component type."""
        if not record_type or not isinstance(record_type, RecordType):
            return False
        # Search all components including inherited ones
        rt = record_type
        while rt is not None:
            for comp in rt.components:
                if comp.name.lower() == field_name and isinstance(comp.component_type, RecordType):
                    return True
            rt = rt.parent_type
        return False

    def _eval_static(self, expr: Expr) -> Optional[int]:
        """Try to evaluate an expression statically at compile time."""
        if isinstance(expr, IntegerLiteral):
            return expr.value
        if isinstance(expr, Identifier):
            # Try to look up constant value
            sym = self.symbols.lookup(expr.name)
            if sym and sym.kind == SymbolKind.CONSTANT:
                if hasattr(sym, 'value') and isinstance(sym.value, (int, float)):
                    return int(sym.value)
        if isinstance(expr, UnaryExpr):
            operand = self._eval_static(expr.operand)
            if operand is not None:
                if expr.op == UnaryOp.MINUS:
                    return -operand
                if expr.op == UnaryOp.PLUS:
                    return operand
        if isinstance(expr, BinaryExpr):
            left = self._eval_static(expr.left)
            right = self._eval_static(expr.right)
            if left is not None and right is not None:
                if expr.op == BinaryOp.ADD:
                    return left + right
                if expr.op == BinaryOp.SUB:
                    return left - right
                if expr.op == BinaryOp.MUL:
                    return left * right
                if expr.op == BinaryOp.DIV and right != 0:
                    return left // right
        return None

    def _lower_slice(self, expr: Slice):
        """Lower an array slice expression.

        A slice A(1..5) returns a view (pointer + bounds) of the array segment.
        For Z80 simplicity, returns a pointer to the first element of the slice.
        """
        if self.ctx is None:
            return Immediate(0, IRType.PTR)

        # Get the base array address
        base_addr = self._lower_expr(expr.prefix)

        # Get the low bound of the slice
        low_bound = self._lower_expr(expr.range_expr.low)

        # Determine element size
        element_size = 2  # Default to word
        array_low = 1  # Default array lower bound

        # Look up the array type to get element size
        if isinstance(expr.prefix, Identifier):
            name = expr.prefix.name.lower()
            sym = self.symbols.lookup(expr.prefix.name)

            # Check global symbol first
            if sym and sym.ada_type and isinstance(sym.ada_type, ArrayType):
                if sym.ada_type.component_type:
                    element_size = (sym.ada_type.component_type.size_bits + 7) // 8

                # Account for array's lower bound
                if sym.ada_type.bounds:
                    array_low = sym.ada_type.bounds[0][0]

            # Check local variables for string types
            elif self.ctx and name in self.ctx.locals:
                local = self.ctx.locals[name]
                if local.ada_type:
                    # Extract type name from local's ada_type
                    type_name = self._extract_type_name(local.ada_type)
                    if type_name and type_name.lower() == 'string':
                        element_size = 1  # Strings are Character arrays (1 byte)
                        array_low = 1  # Ada strings are 1-indexed

            # Check parameters
            elif self.ctx and name in self.ctx.params:
                param = self.ctx.params[name]
                if hasattr(param, 'ada_type') and param.ada_type:
                    type_name = self._extract_type_name(param.ada_type)
                    if type_name and type_name.lower() == 'string':
                        element_size = 1
                        array_low = 1

            # Calculate offset: (slice_low - array_low) * element_size
            if isinstance(low_bound, Immediate):
                # Adjust for array's lower bound
                offset = (low_bound.value - array_low) * element_size
                slice_addr = self.builder.new_vreg(IRType.PTR, "_slice")
                self.builder.add(slice_addr, base_addr, Immediate(offset, IRType.WORD))
                return slice_addr

        # Dynamic calculation for non-constant bounds
        # offset = (low_bound - array_low) * element_size
        adjusted = self.builder.new_vreg(IRType.WORD, "_adj_idx")
        self.builder.sub(adjusted, low_bound, Immediate(array_low, IRType.WORD))
        offset_val = self.builder.new_vreg(IRType.WORD, "_offset")

        # Multiply index by element size
        if element_size != 1:
            size_imm = Immediate(element_size, IRType.WORD)
            self.builder.mul(offset_val, adjusted, size_imm)
        else:
            self.builder.mov(offset_val, adjusted)

        # Add to base address
        slice_addr = self.builder.new_vreg(IRType.PTR, "_slice")
        self.builder.add(slice_addr, base_addr, offset_val)

        return slice_addr

    def _lower_slice_store(self, target: Slice, value) -> None:
        """Lower array slice assignment.

        A(1..5) := B(1..5) copies elements from source to target slice.
        This is a block memory copy operation.
        """
        if self.ctx is None:
            return

        # Get destination slice address
        dest_addr = self._lower_slice(target)

        # Get source slice address (value should be a pointer to source slice)
        src_addr = value

        # Calculate number of elements to copy
        low_bound = self._lower_expr(target.range_expr.low)
        high_bound = self._lower_expr(target.range_expr.high)

        # Determine element size
        element_size = 2  # Default to word
        if isinstance(target.prefix, Identifier):
            sym = self.symbols.lookup(target.prefix.name)
            if sym and sym.ada_type and isinstance(sym.ada_type, ArrayType):
                if sym.ada_type.component_type:
                    element_size = (sym.ada_type.component_type.size_bits + 7) // 8

        # Calculate byte count: (high - low + 1) * element_size
        if isinstance(low_bound, Immediate) and isinstance(high_bound, Immediate):
            # Constant bounds
            num_elements = high_bound.value - low_bound.value + 1
            byte_count = num_elements * element_size
            byte_count_vreg = Immediate(byte_count, IRType.WORD)
        else:
            # Dynamic bounds
            count = self.builder.new_vreg(IRType.WORD, "_count")
            self.builder.sub(count, high_bound, low_bound)
            self.builder.add(count, count, Immediate(1, IRType.WORD))
            if element_size != 1:
                byte_count_vreg = self.builder.new_vreg(IRType.WORD, "_bytes")
                self.builder.mul(byte_count_vreg, count, Immediate(element_size, IRType.WORD))
            else:
                byte_count_vreg = count

        # Call block copy runtime function
        # Stack layout: IX+4=count, IX+6=src, IX+8=dest
        # Push: dest first (IX+8), src (IX+6), count last (IX+4)
        self.builder.push(dest_addr)         # destination (IX+8)
        self.builder.push(src_addr)          # source (IX+6)
        self.builder.push(byte_count_vreg)   # count (IX+4)
        self.builder.call(Label("_memcpy"), comment="slice assignment")
        # Clean up stack (3 words)
        temp = self.builder.new_vreg(IRType.WORD, "_discard")
        self.builder.pop(temp)
        self.builder.pop(temp)
        self.builder.pop(temp)

    def _resolve_type(self, type_expr: Expr):
        """Resolve a type expression to an AdaType."""
        if isinstance(type_expr, Identifier):
            sym = self.symbols.lookup(type_expr.name)
            if sym and sym.kind in (SymbolKind.TYPE, SymbolKind.SUBTYPE,
                                     SymbolKind.TASK, SymbolKind.TASK_TYPE):
                return sym.ada_type
            # Fallback: search _body_declarations_stack and package declarations
            return self._resolve_local_type(type_expr)
        elif isinstance(type_expr, SubtypeIndication):
            if type_expr.type_mark:
                return self._resolve_type(type_expr.type_mark)
        elif isinstance(type_expr, SelectedName):
            # Try bare selector first
            sym = self.symbols.lookup(type_expr.selector)
            if sym and sym.kind in (SymbolKind.TYPE, SymbolKind.SUBTYPE):
                return sym.ada_type
            # Fallback: search package public_symbols
            return self._resolve_local_type(type_expr)
        elif isinstance(type_expr, IndexedComponent):
            # Discriminant constraint: TB(A => 0) parsed as IndexedComponent(prefix=TB)
            # Resolve the prefix as the base record type
            return self._resolve_type(type_expr.prefix)
        return None

    def _lower_identifier(self, expr: Identifier):
        """Lower an identifier reference."""
        if self.ctx is None:
            return Immediate(0, IRType.WORD)

        name = expr.name.lower()

        # Check inline parameters first (for inlined function calls)
        if hasattr(self, '_inline_params') and name in self._inline_params:
            return self._inline_params[name]

        # Check generic formal object substitution (e.g., formal 'F' -> actual 'FLO')
        if self._generic_type_map and name in self._generic_type_map:
            actual = self._generic_type_map[name]
            # Check if there's also a _subp_ entry - if so, it's a subprogram formal, not an object
            if f"_subp_{name}" not in self._generic_type_map:
                # It's a generic formal object - substitute with actual expression
                if isinstance(actual, str):
                    actual_expr = Identifier(name=actual)
                    return self._lower_identifier(actual_expr)
                else:
                    # AST expression node (e.g., IntegerLiteral, UnaryOp, etc.)
                    return self._lower_expr(actual)

        # Check generic formal object defaults (when no actual was provided)
        if self._generic_default_exprs and name in self._generic_default_exprs:
            default_expr = self._generic_default_exprs[name]
            return self._lower_expr(default_expr)

        # Check if this is a protected type component (inside a protected operation)
        if self.ctx.protected_obj_ptr is not None and self.ctx.protected_type is not None:
            # Look up the component in the protected type
            prot_type = self.ctx.protected_type
            offset = 1  # Skip lock byte (offset 0)
            for comp in prot_type.components:
                if comp.name.lower() == name:
                    # Found the component - access it through the protected object pointer
                    result = self.builder.new_vreg(IRType.WORD, f"_{name}_val")
                    if offset != 0:
                        comp_addr = self.builder.new_vreg(IRType.PTR, f"_{name}_addr")
                        self.builder.add(comp_addr, self.ctx.protected_obj_ptr, Immediate(offset, IRType.WORD))
                        self.builder.load(result, MemoryLocation(base=comp_addr, offset=0, ir_type=IRType.WORD),
                                         comment=f"load protected component {name}")
                    else:
                        self.builder.load(result, MemoryLocation(base=self.ctx.protected_obj_ptr, offset=0, ir_type=IRType.WORD),
                                         comment=f"load protected component {name}")
                    return result
                # Advance offset by component size
                comp_bytes = (comp.size_bits // 8) if comp.size_bits else 2
                offset += comp_bytes

        # Check locals with nested package body prefix FIRST (innermost scope wins).
        # When inside a nested package body like P (inside C83F01D1), the spec
        # variable X1 is stored as local "C83F01D1.P.X1".  The prefix stack
        # tracks the accumulated prefix "C83F01D1.P." so we can find it.
        # This must come before the unprefixed locals check so that P's X1
        # shadows the enclosing procedure's X1.
        if hasattr(self, '_nested_body_prefix_stack') and self._nested_body_prefix_stack:
            for prefix in reversed(self._nested_body_prefix_stack):
                if prefix:
                    prefixed = f"{prefix}{name}".lower()
                    if prefixed in self.ctx.locals:
                        local = self.ctx.locals[prefixed]
                        return local.vreg

        # Check locals
        if name in self.ctx.locals:
            # For task-promoted variables, always read from the DSEG shadow
            # so that modifications by task bodies (running on separate stacks)
            # are visible.
            dseg_label = self._task_promoted_vars.get(name)
            if dseg_label:
                result = self.builder.new_vreg(IRType.WORD, f"_{name}_dseg")
                self.builder.load(result,
                    MemoryLocation(is_global=True, symbol_name=dseg_label, ir_type=IRType.WORD),
                    comment=f"load {name} from DSEG shadow")
                return result
            local = self.ctx.locals[name]
            # For address-based renames (complex expressions), dereference the stored address
            # Simple renames share the source's vreg, so no dereferencing needed
            if getattr(local, 'is_address_rename', False):
                result = self.builder.new_vreg(IRType.WORD, f"_{name}_deref")
                self.builder.emit(IRInstr(
                    OpCode.LOAD, result,
                    MemoryLocation(offset=0, ir_type=IRType.WORD, base=local.vreg),
                    comment=f"deref rename {name}"
                ))
                return result
            # For Float64 types, return the address of the 8-byte value on stack
            # Need to resolve the type since ada_type may be AST node (SubtypeIndication)
            resolved_type = self._resolve_local_type(local.ada_type) if local.ada_type else None
            if resolved_type and self._is_float64_type(resolved_type):
                frame_offset = -(local.stack_offset + local.size)
                local_addr = self.builder.new_vreg(IRType.PTR, f"_{name}_addr")
                self.builder.emit(IRInstr(
                    OpCode.LEA,
                    dst=local_addr,
                    src1=MemoryLocation(offset=frame_offset, ir_type=IRType.PTR, is_frame_offset=True),
                    comment=f"address of {name}"
                ))
                return local_addr
            # For inline arrays (size > 2), return LEA to inline stack area
            # This ensures reads and writes target the same memory location
            if local.size > 2 and resolved_type and hasattr(resolved_type, 'kind'):
                from uada80.type_system import TypeKind as _TK
                if resolved_type.kind == _TK.ARRAY:
                    frame_offset = -(local.stack_offset + local.size)
                    local_addr = self.builder.new_vreg(IRType.PTR, f"_{name}_addr")
                    self.builder.emit(IRInstr(
                        OpCode.LEA,
                        dst=local_addr,
                        src1=MemoryLocation(offset=frame_offset, ir_type=IRType.PTR, is_frame_offset=True),
                        comment=f"address of inline array {name}"
                    ))
                    return local_addr
            return local.vreg

        # Check params
        if name in self.ctx.params:
            param_vreg = self.ctx.params[name]
            # For byref parameters (out/in out), dereference the pointer to get value
            if name in self.ctx.byref_params:
                result = self.builder.new_vreg(IRType.WORD, f"_{name}_val")
                self.builder.emit(IRInstr(
                    OpCode.LOAD, result,
                    MemoryLocation(offset=0, ir_type=IRType.WORD, base=param_vreg),
                    comment=f"deref byref param {name}"
                ))
                return result
            return param_vreg

        # Check for nested package variables (passed as hidden outer parameters)
        if hasattr(self, '_current_nested_package') and self._current_nested_package:
            pkg_name = self._current_nested_package
            prefixed_name = f"{pkg_name}.{name}"
            # Check if passed as hidden outer parameter
            outer_param_prefixed = f"_outer_{prefixed_name}"
            if outer_param_prefixed in self.ctx.params:
                ptr_vreg = self.ctx.params[outer_param_prefixed]
                result = self.builder.new_vreg(IRType.WORD, f"_{name}_outer")
                self.builder.emit(IRInstr(
                    OpCode.LOAD, result,
                    MemoryLocation(offset=0, ir_type=IRType.WORD, base=ptr_vreg),
                    comment=f"load {name} from package {pkg_name}"
                ))
                return result

        # Check enclosing scopes via static link (for nested subprograms)
        # For outer-scope variables, we have hidden byref parameters with names like "_outer_<varname>"
        outer_param_name = f"_outer_{name}"
        if outer_param_name in self.ctx.params:
            # This is an outer-scope variable passed as a hidden pointer
            ptr_vreg = self.ctx.params[outer_param_name]
            result = self.builder.new_vreg(IRType.WORD, f"_{name}_outer")
            self.builder.emit(IRInstr(
                OpCode.LOAD, result,
                MemoryLocation(offset=0, ir_type=IRType.WORD, base=ptr_vreg),
                comment=f"load {name} from enclosing scope"
            ))
            return result

        # Check named numbers (universal integer/real constants)
        if name in self.ctx.named_numbers:
            val = self.ctx.named_numbers[name]
            if isinstance(val, float):
                # Check context to determine if this should be integer or float
                if val == int(val):
                    val = int(val)  # Exact integer value as float (e.g., 1024.0)
                else:
                    val = int(val)  # Truncate non-integer floats for integer context
            return Immediate(val, IRType.WORD)

        # Check for boolean literals
        if name == "true":
            return Immediate(1, IRType.BOOL)
        if name == "false":
            return Immediate(0, IRType.BOOL)

        # Check for package-prefixed local variables (from 'use' clauses).
        # When 'use R' makes R's variables visible, they are stored as "r.y"
        # in ctx.locals but accessed as just "y". This search finds them.
        pkg_local = self._find_local_with_package_prefix(name)
        if pkg_local is not None and (name not in self.ctx.locals):
            # Found via package prefix - return the vreg (same logic as direct local)
            resolved_type = self._resolve_local_type(pkg_local.ada_type) if pkg_local.ada_type else None
            if resolved_type and self._is_float64_type(resolved_type):
                frame_offset = -(pkg_local.stack_offset + pkg_local.size)
                local_addr = self.builder.new_vreg(IRType.PTR, f"_{name}_addr")
                self.builder.emit(IRInstr(
                    OpCode.LEA,
                    dst=local_addr,
                    src1=MemoryLocation(offset=frame_offset, ir_type=IRType.PTR, is_frame_offset=True),
                ))
                return local_addr
            if pkg_local.size > 2 and resolved_type and hasattr(resolved_type, 'kind'):
                from uada80.type_system import TypeKind as _TK2
                if resolved_type.kind == _TK2.ARRAY:
                    frame_offset = -(pkg_local.stack_offset + pkg_local.size)
                    local_addr = self.builder.new_vreg(IRType.PTR, f"_{name}_addr")
                    self.builder.emit(IRInstr(
                        OpCode.LEA,
                        dst=local_addr,
                        src1=MemoryLocation(offset=frame_offset, ir_type=IRType.PTR, is_frame_offset=True),
                    ))
                    return local_addr
            return pkg_local.vreg

        # Check if this identifier is a parameterless function call
        # In Ada, Get_Value without () is still a function call if it's a function with no required params
        # Use resolved_symbol from semantic analysis if available (for overload resolution)
        sym = getattr(expr, 'resolved_symbol', None) or self.symbols.lookup(expr.name)
        if sym and sym.kind == SymbolKind.FUNCTION:
            # Check if function has no required parameters
            has_required_params = False
            if sym.parameters:
                for p in sym.parameters:
                    if p.default_value is None:
                        has_required_params = True
                        break
            if not has_required_params:
                # This is a parameterless function call - synthesize a FunctionCall and lower it
                func_call = FunctionCall(name=expr, args=[])
                return self._lower_function_call(func_call)

        # Also check for nested subprograms tracked locally (not in symbol table)
        if name in self._subprogram_param_modes:
            param_modes = self._subprogram_param_modes[name]
            if len(param_modes) == 0:
                # This is a parameterless nested function - call it
                func_call = FunctionCall(name=expr, args=[])
                return self._lower_function_call(func_call)

        # Check for enumeration literals in symbol table
        sym = self.symbols.lookup(expr.name)
        if sym and sym.is_constant and sym.ada_type:
            from uada80.type_system import EnumerationType
            if isinstance(sym.ada_type, EnumerationType):
                # Get the position value for this literal
                pos = sym.ada_type.positions.get(expr.name)
                if pos is not None:
                    return Immediate(pos, IRType.WORD)

        # Fallback: check local and enclosing type declarations for enum literals
        # Check _current_body_declarations and _body_declarations_stack to find
        # enum types declared in the current scope or enclosing package bodies
        decl_lists_to_check = []
        if hasattr(self, '_current_body_declarations') and self._current_body_declarations is not None:
            decl_lists_to_check.append(self._current_body_declarations)
        if hasattr(self, '_body_declarations_stack'):
            for decl_list in reversed(self._body_declarations_stack):
                if decl_list not in decl_lists_to_check:
                    decl_lists_to_check.append(decl_list)
        if decl_lists_to_check:
            from uada80.ast_nodes import EnumerationTypeDef
            for decl_list in decl_lists_to_check:
                for d in decl_list:
                    if isinstance(d, TypeDecl) and d.type_def:
                        if isinstance(d.type_def, EnumerationTypeDef) and d.type_def.literals:
                            # Check if this literal is in this enum type
                            for i, lit in enumerate(d.type_def.literals):
                                if lit.lower() == name:
                                    return Immediate(i, IRType.WORD)

        # Check for package-level global variables
        if self.builder.module:
            # Try with package prefix first (for variables in current package)
            # Package globals are stored as "Package_VarName"
            for pkg_prefix in reversed(self._package_prefix_stack):
                # Case-insensitive search: try to match any global with this prefix
                search_prefix = f"{pkg_prefix}_".lower()
                search_name = name.lower()
                for global_name in self.builder.module.globals:
                    if global_name.lower().startswith(search_prefix):
                        # Check if the variable name matches (after the prefix)
                        var_part = global_name[len(pkg_prefix) + 1:]  # Skip "Prefix_"
                        if var_part.lower() == search_name:
                            return self._load_global(global_name)

            # Try combined prefixes from the package prefix stack.
            # For nested packages like C83F01D1 containing P, the stack is
            # ["C83F01D1", "P"] and variables are named "C83F01D1_P_X1".
            # Build combined prefixes right-to-left: "C83F01D1_P", "C83F01D1".
            if len(self._package_prefix_stack) > 1:
                for i in range(len(self._package_prefix_stack) - 1, 0, -1):
                    combined_prefix = "_".join(self._package_prefix_stack[:i + 1])
                    combined_global = f"{combined_prefix}_{name}".lower()
                    for global_name in self.builder.module.globals:
                        if global_name.lower() == combined_global:
                            return self._load_global(global_name)

            # Also try without prefix (for variables in other packages)
            for global_name in self.builder.module.globals:
                if global_name.lower() == name.lower():
                    return self._load_global(global_name)

            # Check for variables from USE'd packages (globals ending with _<varname>)
            # This handles cases like looking up "A" finding "C23006B_PKG_A"
            search_suffix = f"_{name}".lower()
            for global_name in self.builder.module.globals:
                if global_name.lower().endswith(search_suffix):
                    return self._load_global(global_name)

        # Default
        return Immediate(0, IRType.WORD)

    def _operator_to_name(self, op: BinaryOp) -> Optional[str]:
        """Convert a binary operator to its Ada operator function name."""
        op_names = {
            BinaryOp.ADD: '"+'+'"',
            BinaryOp.SUB: '"-'+'"',
            BinaryOp.MUL: '"*'+'"',
            BinaryOp.DIV: '"/'+'"',
            BinaryOp.MOD: '"mod'+'"',
            BinaryOp.REM: '"rem'+'"',
            BinaryOp.EXP: '"**'+'"',
            BinaryOp.AND: '"and'+'"',
            BinaryOp.OR: '"or'+'"',
            BinaryOp.XOR: '"xor'+'"',
            BinaryOp.EQ: '"='+'"',
            BinaryOp.NE: '"/='+'"',
            BinaryOp.LT: '"<'+'"',
            BinaryOp.LE: '"<='+'"',
            BinaryOp.GT: '">'+'"',
            BinaryOp.GE: '">='+'"',
            BinaryOp.CONCAT: '"&'+'"',
        }
        return op_names.get(op)

    def _lookup_user_operator(self, op: BinaryOp, left: Expr, right: Expr) -> Optional[Symbol]:
        """Look up a user-defined operator for the given operands.

        Returns the Symbol for the user-defined operator function if one exists,
        otherwise returns None to use the built-in operator.
        """
        # Get the operator function name
        op_name = self._operator_to_name(op)
        if op_name is None:
            return None

        # Get operand types
        left_type = self._get_expr_type(left)
        right_type = self._get_expr_type(right)

        if left_type is None or right_type is None:
            return None

        # Don't look up operators for predefined types or scalar derived types - use built-ins
        predefined_type_names = {'integer', 'boolean', 'character', 'natural', 'positive',
                                 'float', 'duration', 'long_integer', 'short_integer'}

        def _is_scalar_type(t):
            """Check if type is a scalar type (or derived from one)."""
            if t is None:
                return False
            if hasattr(t, 'name') and t.name.lower() in predefined_type_names:
                return True
            if hasattr(t, 'kind') and t.kind in (TypeKind.INTEGER, TypeKind.MODULAR,
                                                   TypeKind.ENUMERATION, TypeKind.FLOAT,
                                                   TypeKind.FIXED):
                return True
            # Check base type chain for derived types
            base = getattr(t, 'base_type', None)
            if base is not None and base is not t:
                return _is_scalar_type(base)
            return False

        from uada80.type_system import TypeKind
        if _is_scalar_type(left_type):
            # For equality operators, still check for user overloads on composite types
            if op not in (BinaryOp.EQ, BinaryOp.NE):
                return None
            if not isinstance(left_type, (RecordType, ArrayType)):
                return None

        # Look up operator overloads
        overloads = self.symbols.all_overloads(op_name)
        if not overloads:
            # Also try without quotes (some symbol tables store operators differently)
            alt_name = op_name.strip('"')
            overloads = self.symbols.all_overloads(alt_name)

        # Also check locally-tracked operators (nested functions)
        if not overloads:
            # Check _subprogram_param_names for locally-defined operators
            alt_name = op_name.strip('"')
            if alt_name in self._subprogram_param_names:
                # Found a locally-defined operator - create a minimal symbol to represent it
                local_sym = Symbol(
                    name=alt_name,
                    kind=SymbolKind.FUNCTION,
                )
                return local_sym

        if not overloads:
            return None

        # Find matching overload based on operand types
        from uada80.type_system import types_compatible

        for sym in overloads:
            if sym.kind != SymbolKind.FUNCTION:
                continue
            if len(sym.parameters) != 2:
                continue

            # Check if parameter types match operand types
            param1_type = sym.parameters[0].ada_type if sym.parameters[0].ada_type else None
            param2_type = sym.parameters[1].ada_type if sym.parameters[1].ada_type else None

            if param1_type is None or param2_type is None:
                continue

            left_match = (param1_type.name == left_type.name or
                          types_compatible(param1_type, left_type))
            right_match = (param2_type.name == right_type.name or
                           types_compatible(param2_type, right_type))

            if left_match and right_match:
                # Skip intrinsic/inherited operators that have no body.
                # These are predefined operators (=, /=, <, etc.) inherited by
                # derived types — they should use the built-in inline code,
                # not generate a call to a non-existent function.
                if getattr(sym, 'is_intrinsic', False):
                    return None
                # Check if the operator has a real body (SubprogramBody definition)
                # Inherited operators from _inherit_primitive_operations have
                # definition pointing to the parent's spec, not a body.
                sym_def = getattr(sym, 'definition', None)
                if sym_def is not None and not isinstance(sym_def, SubprogramBody):
                    # Check if there's a corresponding body in nested labels
                    mangled = self._mangle_operator_name(sym.name.lower())
                    if mangled not in self._nested_subprogram_labels:
                        # No body exists for this operator — use built-in
                        return None
                return sym

        return None

    def _call_user_operator(self, sym: Symbol, left_operand: Expr, right_operand: Expr):
        """Generate a call to a user-defined operator function.

        Generates code to:
        1. Evaluate left and right operands
        2. Push arguments on stack (by value or by reference for records)
        3. Call the operator function
        4. Capture and return the result
        """
        result = self.builder.new_vreg(IRType.WORD, "_op_result")

        # Check if this operator has byref parameters (e.g., records)
        op_name = sym.name.lower()
        byref_params = self._subprogram_byref_params.get(op_name, [])

        # Determine if left operand should be passed by reference
        left_byref = len(byref_params) > 0 and byref_params[0]
        # Determine if right operand should be passed by reference
        right_byref = len(byref_params) > 1 and byref_params[1]

        # Evaluate and push operands (right-to-left for Z80 calling convention)
        if right_byref:
            right_val = self._get_arg_address(right_operand)
        else:
            right_val = self._lower_expr(right_operand)
        self.builder.push(right_val)

        if left_byref:
            left_val = self._get_arg_address(left_operand)
        else:
            left_val = self._lower_expr(left_operand)
        self.builder.push(left_val)

        # Call the operator function - mangle operator name for assembly
        op_func_name = self._mangle_operator_name(sym.name.lower())

        # Check for nested subprogram label (includes scope prefix)
        if op_func_name in self._nested_subprogram_labels:
            op_func_name = self._nested_subprogram_labels[op_func_name]

        self.builder.call(Label(op_func_name), comment=f"user-defined operator {sym.name}")

        # Capture result from HL register IMMEDIATELY after call
        # (before POPs which would clobber HL)
        self.builder.emit(IRInstr(
            OpCode.MOV, result,
            MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
            comment=f"capture {sym.name} result from HL"
        ))

        # Clean up stack (2 arguments)
        temp = self.builder.new_vreg(IRType.WORD, "_discard")
        self.builder.pop(temp)
        self.builder.pop(temp)

        return result

    def _lower_binary(self, expr: BinaryExpr):
        """Lower a binary expression."""
        op = expr.op

        # Handle short-circuit operators specially - don't evaluate right operand unconditionally
        if op == BinaryOp.AND_THEN:
            return self._lower_short_circuit_and(expr)
        elif op == BinaryOp.OR_ELSE:
            return self._lower_short_circuit_or(expr)

        # Check for user-defined operator overloading
        user_op = self._lookup_user_operator(op, expr.left, expr.right)
        if user_op is not None:
            return self._call_user_operator(user_op, expr.left, expr.right)

        # Check if this is a Float64 operation.
        # RealLiteral is universal_real in Ada — its type depends on context.
        # Don't let a bare RealLiteral force Float64 path (it might be fixed-point).
        # Only enter Float64 if at least one operand is a genuine Float variable/expr.
        # When called from _lower_float64_operand, it goes through a separate path.
        left_type = self._get_expr_type(expr.left)
        right_type = self._get_expr_type(expr.right)
        from uada80.type_system import FixedType as _FixedType
        is_fixed = isinstance(left_type, _FixedType) or isinstance(right_type, _FixedType)
        left_is_float = self._is_float64_type(left_type) and not isinstance(expr.left, RealLiteral)
        right_is_float = self._is_float64_type(right_type) and not isinstance(expr.right, RealLiteral)
        if not is_fixed and (left_is_float or right_is_float):
            if op in (BinaryOp.ADD, BinaryOp.SUB, BinaryOp.MUL, BinaryOp.DIV, BinaryOp.REM, BinaryOp.MOD):
                left_ptr = self._lower_float64_operand(expr.left)
                right_ptr = self._lower_float64_operand(expr.right)
                return self._lower_float64_binary(op, left_ptr, right_ptr, left_type or right_type)
            elif op in (BinaryOp.EQ, BinaryOp.NE, BinaryOp.LT, BinaryOp.LE, BinaryOp.GT, BinaryOp.GE):
                left_ptr = self._lower_float64_operand(expr.left)
                right_ptr = self._lower_float64_operand(expr.right)
                return self._lower_float64_comparison(op, left_ptr, right_ptr)
            elif op == BinaryOp.EXP and self._is_float64_type(left_type):
                # Float64 ** Integer exponentiation
                left_ptr = self._lower_float64_operand(expr.left)
                right_val = self._lower_expr(expr.right)  # Integer exponent
                return self._lower_float64_exp(left_ptr, right_val, left_type)

        # For composite comparisons (string, array, record), handle BEFORE
        # evaluating both sides with _lower_expr to avoid double-evaluation
        # of aggregates (which would allocate them on the stack twice).
        if op in (BinaryOp.EQ, BinaryOp.NE, BinaryOp.LT, BinaryOp.LE, BinaryOp.GT, BinaryOp.GE):
            # For record/array equality/inequality with aggregates, propagate the
            # type to the aggregate so it can be built with correct layout/size.
            if isinstance(left_type, (RecordType, ArrayType)) and isinstance(expr.right, Aggregate):
                if not getattr(expr.right, 'resolved_type', None):
                    expr.right.resolved_type = left_type
            elif isinstance(right_type, (RecordType, ArrayType)) and isinstance(expr.left, Aggregate):
                if not getattr(expr.left, 'resolved_type', None):
                    expr.left.resolved_type = right_type

            is_string = False
            if left_type and isinstance(left_type, ArrayType):
                if left_type.name == "String" or (left_type.component_type and
                    hasattr(left_type.component_type, 'name') and
                    left_type.component_type.name == "Character"):
                    is_string = True
            # Also check via _is_string_type (handles 'IMAGE, etc.)
            if not is_string and self._is_string_type(expr.left):
                is_string = True
            if is_string:
                str_arr_type = left_type if isinstance(left_type, ArrayType) else (
                    right_type if isinstance(right_type, ArrayType) else None)
                if op in (BinaryOp.LT, BinaryOp.LE, BinaryOp.GT, BinaryOp.GE):
                    # Use length-aware ordering (handles different-length strings)
                    left_ptr = self._get_composite_ptr(expr.left, expected_type=str_arr_type)
                    right_ptr = self._get_composite_ptr(expr.right, expected_type=str_arr_type)
                    return self._lower_string_ordering(op, left_ptr, right_ptr,
                                                       str_arr_type, expr)
                left = self._lower_expr(expr.left)
                right = self._lower_expr(expr.right)
                # Get string length for constrained comparison (avoids null-terminator issue)
                str_len = None
                if str_arr_type and str_arr_type.size_bits:
                    str_len = str_arr_type.size_bits // 8
                return self._lower_string_comparison(op, left, right, str_len=str_len)

            # Check if this is a general array comparison (non-string arrays)
            array_type_for_cmp = None
            if left_type and isinstance(left_type, ArrayType) and not is_string:
                array_type_for_cmp = left_type
            elif right_type and isinstance(right_type, ArrayType) and not is_string:
                array_type_for_cmp = right_type
            if array_type_for_cmp is not None:
                left_ptr = self._get_composite_ptr(expr.left, expected_type=array_type_for_cmp)
                right_ptr = self._get_composite_ptr(expr.right, expected_type=array_type_for_cmp)
                if op in (BinaryOp.EQ, BinaryOp.NE):
                    return self._lower_array_comparison(op, left_ptr, right_ptr, array_type_for_cmp, expr=expr)
                if op in (BinaryOp.LT, BinaryOp.LE, BinaryOp.GT, BinaryOp.GE):
                    return self._lower_array_ordering(op, left_ptr, right_ptr, array_type_for_cmp, expr)

            # Check if this is a record comparison (check both sides — one may be an aggregate with no type)
            record_type_for_cmp = None
            if left_type and isinstance(left_type, RecordType):
                record_type_for_cmp = left_type
            elif right_type and isinstance(right_type, RecordType):
                record_type_for_cmp = right_type
            if record_type_for_cmp is not None:
                left_ptr = self._get_composite_ptr(expr.left, expected_type=record_type_for_cmp)
                right_ptr = self._get_composite_ptr(expr.right, expected_type=record_type_for_cmp)
                return self._lower_record_comparison(op, left_ptr, right_ptr, record_type_for_cmp)

        # Boolean array AND/OR/XOR: element-wise operations (Ada RM 4.5.6)
        if op in (BinaryOp.AND, BinaryOp.OR, BinaryOp.XOR):
            ba_type = left_type if isinstance(left_type, ArrayType) else (
                right_type if isinstance(right_type, ArrayType) else None)
            if ba_type and self._is_boolean_array_type(ba_type):
                left_ptr = self._get_composite_ptr(expr.left, expected_type=ba_type)
                right_ptr = self._get_composite_ptr(expr.right, expected_type=ba_type)
                return self._lower_bool_array_binary(op, left_ptr, right_ptr, ba_type, expr)

        # Set fixed-point context for RealLiteral operands in binary expressions
        old_fx_delta = getattr(self, '_fixed_point_context_delta', None)
        if is_fixed:
            fx_type = left_type if isinstance(left_type, _FixedType) else right_type
            delta = getattr(fx_type, 'delta', None) or getattr(fx_type, 'small', None)
            if delta:
                self._fixed_point_context_delta = delta
        left = self._lower_expr(expr.left)
        right = self._lower_expr(expr.right)
        self._fixed_point_context_delta = old_fx_delta

        result = self.builder.new_vreg(IRType.WORD, "_tmp")

        if op == BinaryOp.ADD:
            self.builder.add(result, left, right)
        elif op == BinaryOp.SUB:
            self.builder.sub(result, left, right)
        elif op == BinaryOp.MUL:
            self.builder.mul(result, left, right)
        elif op == BinaryOp.DIV:
            self.builder.div(result, left, right)
        elif op == BinaryOp.AND:
            self.builder.and_(result, left, right)
        elif op == BinaryOp.OR:
            self.builder.or_(result, left, right)
        elif op == BinaryOp.XOR:
            self.builder.xor(result, left, right)
        elif op == BinaryOp.EQ:
            self.builder.cmp_eq(result, left, right)
        elif op == BinaryOp.NE:
            self.builder.cmp_ne(result, left, right)
        elif op == BinaryOp.LT:
            self.builder.cmp_lt(result, left, right)
        elif op == BinaryOp.LE:
            self.builder.cmp_le(result, left, right)
        elif op == BinaryOp.GT:
            self.builder.cmp_gt(result, left, right)
        elif op == BinaryOp.GE:
            self.builder.cmp_ge(result, left, right)
        elif op == BinaryOp.MOD:
            self.builder.emit(IRInstr(OpCode.MOD, result, left, right))
        elif op == BinaryOp.REM:
            # REM differs from MOD in sign handling for negative numbers
            # Ada REM: result has same sign as dividend
            self.builder.emit(IRInstr(OpCode.REM, result, left, right))
        elif op == BinaryOp.EXP:
            # Exponentiation: call runtime function
            # Push base first, then exponent (ends at lower offset)
            self.builder.push(left)   # base (IX+10 in runtime)
            self.builder.push(right)  # exponent (IX+8 in runtime)
            self.builder.call(Label("_exp16"))
            # Capture result from HL register BEFORE popping arguments
            self.builder.emit(IRInstr(
                OpCode.MOV, result,
                MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                comment="capture exponentiation result from HL"
            ))
            # Clean up stack (4 bytes for two 16-bit args)
            # Codegen expects: ADD _SP, immediate (dst=_SP, src1=immediate)
            self.builder.emit(IRInstr(
                OpCode.ADD,
                MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
                Immediate(4, IRType.WORD),
                comment="clean up stack after _exp16"
            ))
        elif op == BinaryOp.CONCAT:
            # Check if this is array concatenation or string concatenation
            # String = array of Character, use runtime strcat
            # Other arrays = element-wise copy
            expr_type = self._get_expr_type(expr)

            # Determine if this is a string type by checking:
            # 1. Type name is "String" (or "string")
            # 2. Component type is Character
            is_string_type = False
            if expr_type and expr_type.kind == TypeKind.ARRAY:
                type_name = getattr(expr_type, 'name', '').lower()
                if type_name == 'string':
                    is_string_type = True
                elif hasattr(expr_type, 'component_type') and expr_type.component_type:
                    comp_name = getattr(expr_type.component_type, 'name', '').lower()
                    if comp_name == 'character':
                        is_string_type = True

            is_array_concat = (expr_type and expr_type.kind == TypeKind.ARRAY and
                               not is_string_type)
            if is_array_concat:
                # Array concatenation: copy elements from both arrays
                result = self._lower_array_concat(expr, left, right)
            else:
                # String concatenation: call runtime function
                # _strcat expects: s1 at IX+8 (first push), s2 at IX+6 (second push)
                # Result = s1 + s2 = left + right
                self.builder.push(left)   # first string (s1) -> will be at IX+8
                self.builder.push(right)  # second string (s2) -> will be at IX+6
                self.builder.call(Label("_strcat"))
                # Capture result from HL register BEFORE stack cleanup
                # (pop uses HL which would overwrite the result)
                self.builder.emit(IRInstr(
                    OpCode.MOV, result,
                    MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                    comment="capture string concat result from HL"
                ))
                # Now clean up the stack (2 words = 4 bytes)
                self.builder.emit(IRInstr(
                    OpCode.ADD,
                    MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
                    Immediate(4, IRType.WORD),
                    comment="clean up 2 pushed arguments"
                ))
        else:
            # Default: move left to result
            self.builder.mov(result, left)

        # Apply modular masking for modular type arithmetic
        # For operations like B + 10 where B is mod 256, result must be masked
        if op in (BinaryOp.ADD, BinaryOp.SUB, BinaryOp.MUL):
            expr_type = self._get_expr_type(expr)
            if expr_type:
                from uada80.type_system import ModularType
                if isinstance(expr_type, ModularType):
                    modulus = expr_type.modulus
                    # Check if modulus is a power of 2 (use AND for efficiency)
                    if modulus > 0 and (modulus & (modulus - 1)) == 0:
                        mask = modulus - 1
                        masked = self.builder.new_vreg(IRType.WORD, "_mod_masked")
                        self.builder.and_(masked, result, Immediate(mask, IRType.WORD))
                        result = masked
                    else:
                        # Non-power-of-2: use MOD operation
                        masked = self.builder.new_vreg(IRType.WORD, "_mod_result")
                        self.builder.emit(IRInstr(OpCode.MOD, masked, result, Immediate(modulus, IRType.WORD)))
                        result = masked

        return result

    def _lower_array_concat(self, expr: BinaryExpr, left_addr, right_addr):
        """Lower array concatenation A & B.

        Creates a new array on the stack with elements from both arrays.
        Returns the address of the new array.
        """
        if self.ctx is None:
            return Immediate(0, IRType.WORD)

        # Get the array type to determine element size and bounds
        array_type = self._get_expr_type(expr)
        if not array_type or not isinstance(array_type, ArrayType):
            # Fallback to string concatenation
            return left_addr

        # Get element size (assume 2 bytes for Integer)
        elem_size = 2
        if array_type.component_type:
            elem_size = (array_type.component_type.size_bits + 7) // 8

        # Get the sizes of the left and right arrays
        left_type = self._get_expr_type(expr.left)
        right_type = self._get_expr_type(expr.right)

        left_len = 0
        right_len = 0
        if left_type and isinstance(left_type, ArrayType) and left_type.bounds:
            low, high = left_type.bounds[0]
            left_len = high - low + 1
        if right_type and isinstance(right_type, ArrayType) and right_type.bounds:
            low, high = right_type.bounds[0]
            right_len = high - low + 1

        total_len = left_len + right_len
        total_size = total_len * elem_size

        # Allocate space on stack for the result array
        result_addr = self.builder.new_vreg(IRType.PTR, "_concat_result")
        if total_size > 0:
            self.builder.emit(IRInstr(
                OpCode.SUB,
                MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
                MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
                Immediate(total_size, IRType.WORD),
                comment=f"allocate {total_size} bytes for concat result"
            ))
            # Get SP into result_addr
            self.builder.emit(IRInstr(
                OpCode.MOV, result_addr,
                MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
                comment="concat result address"
            ))

        # Determine IR type for element access — use BYTE for 1-byte elements (Character)
        elem_ir_type = IRType.BYTE if elem_size == 1 else IRType.WORD

        # Use memcpy for efficiency when arrays are large enough
        if left_len > 0 and total_size > 0:
            left_size = left_len * elem_size
            self._emit_memcpy(result_addr, left_addr, left_size, "concat left")

        # Copy elements from right array
        if right_len > 0 and total_size > 0:
            right_size = right_len * elem_size
            right_dest = self.builder.new_vreg(IRType.PTR, "_concat_right_dst")
            self.builder.add(right_dest, result_addr, Immediate(left_len * elem_size, IRType.WORD))
            self._emit_memcpy(right_dest, right_addr, right_size, "concat right")

        return result_addr

    def _lower_short_circuit_and(self, expr: BinaryExpr):
        """Lower short-circuit AND THEN.

        Evaluates left operand first. If false, returns false without
        evaluating right operand. Only evaluates right if left is true.
        """
        result = self.builder.new_vreg(IRType.WORD, "_and_then")

        # Create labels (new_label returns a string, not Label object)
        eval_right = self.builder.new_label("and_eval_right")
        short_circuit = self.builder.new_label("and_short")
        done = self.builder.new_label("and_done")

        # Evaluate left operand
        left = self._lower_expr(expr.left)

        # Check if left is false (0)
        is_false = self.builder.new_vreg(IRType.WORD, "_is_false")
        self.builder.cmp_eq(is_false, left, Immediate(0, IRType.WORD))
        self.builder.jnz(is_false, short_circuit)  # If false, short-circuit

        # Left was true, evaluate right
        self.builder.label(eval_right)
        right = self._lower_expr(expr.right)
        self.builder.mov(result, right)  # Result is right operand's value
        self.builder.jmp(done)

        # Short circuit: left was false, result is false
        self.builder.label(short_circuit)
        self.builder.mov(result, Immediate(0, IRType.WORD))

        self.builder.label(done)
        return result

    def _lower_short_circuit_or(self, expr: BinaryExpr):
        """Lower short-circuit OR ELSE.

        Evaluates left operand first. If true, returns true without
        evaluating right operand. Only evaluates right if left is false.
        """
        result = self.builder.new_vreg(IRType.WORD, "_or_else")

        # Create labels (new_label returns a string, not Label object)
        eval_right = self.builder.new_label("or_eval_right")
        short_circuit = self.builder.new_label("or_short")
        done = self.builder.new_label("or_done")

        # Evaluate left operand
        left = self._lower_expr(expr.left)

        # Check if left is true (non-zero)
        is_true = self.builder.new_vreg(IRType.WORD, "_is_true")
        self.builder.cmp_ne(is_true, left, Immediate(0, IRType.WORD))
        self.builder.jnz(is_true, short_circuit)  # If true, short-circuit

        # Left was false, evaluate right
        self.builder.label(eval_right)
        right = self._lower_expr(expr.right)
        self.builder.mov(result, right)  # Result is right operand's value
        self.builder.jmp(done)

        # Short circuit: left was true, result is true (use left's value)
        self.builder.label(short_circuit)
        self.builder.mov(result, left)

        self.builder.label(done)
        return result

    def _lower_string_comparison(self, op: BinaryOp, left, right, str_len=None):
        """Lower string comparison operations.

        For constrained strings with known length, uses _memcmp (length-based).
        For unconstrained strings, uses _str_cmp (null-terminated).
        Returns comparison result as 0/1 for boolean False/True.
        """
        result = self.builder.new_vreg(IRType.WORD, "_str_cmp_result")

        # Use _memcmp for EQ/NE when string length is known (avoids null-terminator
        # dependency for inline constrained strings)
        if str_len and op in (BinaryOp.EQ, BinaryOp.NE):
            # _memcmp(ptr1, ptr2, size) -> 0 if equal, 1 if different
            # Stack convention: ptr1 at IX+8, ptr2 at IX+6, size at IX+4
            self.builder.push(left)   # ptr1 (pushed first = highest stack position)
            self.builder.push(right)  # ptr2
            self.builder.push(Immediate(str_len, IRType.WORD))  # size (pushed last = lowest)
            self.builder.call(Label("_memcmp"), comment="string memcmp")

            cmp_result = self.builder.new_vreg(IRType.WORD, "_cmp")
            self.builder.emit(IRInstr(
                OpCode.MOV, cmp_result,
                MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                comment="capture string comparison result"
            ))

            temp = self.builder.new_vreg(IRType.WORD, "_discard")
            self.builder.pop(temp)
            self.builder.pop(temp)
            self.builder.pop(temp)

            if op == BinaryOp.EQ:
                self.builder.cmp_eq(result, cmp_result, Immediate(0, IRType.WORD))
            else:  # NE
                self.builder.cmp_ne(result, cmp_result, Immediate(0, IRType.WORD))

            return result

        # Fall back to _str_cmp for ordering or unknown-length strings
        # _str_cmp: returns negative if left < right, 0 if equal, positive if left > right
        self.builder.push(right)  # second string
        self.builder.push(left)   # first string
        self.builder.call(Label("_str_cmp"), comment="string comparison")

        # Get comparison result from HL BEFORE cleaning stack (pop clobbers HL!)
        cmp_result = self.builder.new_vreg(IRType.WORD, "_cmp")
        self.builder.emit(IRInstr(
            OpCode.MOV, cmp_result,
            MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
            comment="capture string comparison result"
        ))

        # Now clean up the stack
        temp = self.builder.new_vreg(IRType.WORD, "_discard")
        self.builder.pop(temp)
        self.builder.pop(temp)

        # Convert strcmp-style result to boolean based on operator
        if op == BinaryOp.EQ:
            # Equal: result == 0
            self.builder.cmp_eq(result, cmp_result, Immediate(0, IRType.WORD))
        elif op == BinaryOp.NE:
            # Not equal: result != 0
            self.builder.cmp_ne(result, cmp_result, Immediate(0, IRType.WORD))
        elif op == BinaryOp.LT:
            # Less than: result < 0
            self.builder.cmp_lt(result, cmp_result, Immediate(0, IRType.WORD))
        elif op == BinaryOp.LE:
            # Less or equal: result <= 0
            self.builder.cmp_le(result, cmp_result, Immediate(0, IRType.WORD))
        elif op == BinaryOp.GT:
            # Greater than: result > 0
            self.builder.cmp_gt(result, cmp_result, Immediate(0, IRType.WORD))
        elif op == BinaryOp.GE:
            # Greater or equal: result >= 0
            self.builder.cmp_ge(result, cmp_result, Immediate(0, IRType.WORD))
        else:
            # Default: equality
            self.builder.cmp_eq(result, cmp_result, Immediate(0, IRType.WORD))

        return result

    def _lower_string_ordering(self, op: BinaryOp, left_ptr, right_ptr,
                                arr_type, expr):
        """Lower lexicographic ordering for string/character arrays.

        Uses _str_ncmp(ptr1, len1, ptr2, len2) which handles different lengths
        and does not rely on null termination.
        """
        result = self.builder.new_vreg(IRType.WORD, "_sord")

        # Get lengths for each side individually (they may differ)
        left_type = self._get_expr_type(expr.left) if expr else None
        right_type = self._get_expr_type(expr.right) if expr else None
        left_len = self._get_string_length(expr.left,
            left_type if isinstance(left_type, ArrayType) else arr_type)
        right_len = self._get_string_length(expr.right,
            right_type if isinstance(right_type, ArrayType) else arr_type)

        # Call _str_ncmp: stack is ptr1(IX+10), len1(IX+8), ptr2(IX+6), len2(IX+4)
        # Push in reverse order: ptr1 first (highest), then len1, ptr2, len2 last
        self.builder.push(left_ptr)
        self.builder.push(left_len)
        self.builder.push(right_ptr)
        self.builder.push(right_len)
        self.builder.call(Label("_str_ncmp"), comment="string ordering")

        cmp_result = self.builder.new_vreg(IRType.WORD, "_scmp")
        self.builder.emit(IRInstr(
            OpCode.MOV, cmp_result,
            MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
            comment="capture string ordering result"
        ))

        # Clean up stack (4 arguments)
        temp = self.builder.new_vreg(IRType.WORD, "_discard")
        self.builder.pop(temp)
        self.builder.pop(temp)
        self.builder.pop(temp)
        self.builder.pop(temp)

        # Convert strcmp-style result to boolean
        if op == BinaryOp.LT:
            self.builder.cmp_lt(result, cmp_result, Immediate(0, IRType.WORD))
        elif op == BinaryOp.LE:
            self.builder.cmp_le(result, cmp_result, Immediate(0, IRType.WORD))
        elif op == BinaryOp.GT:
            self.builder.cmp_gt(result, cmp_result, Immediate(0, IRType.WORD))
        elif op == BinaryOp.GE:
            self.builder.cmp_ge(result, cmp_result, Immediate(0, IRType.WORD))

        return result

    def _get_string_length(self, expr, arr_type):
        """Get the length of a string expression as a VReg.

        For constrained arrays with known size, returns a constant.
        For unconstrained arrays (parameters), computes from dope vector.
        """
        # Try constrained type size first
        if arr_type and isinstance(arr_type, ArrayType) and arr_type.size_bits:
            length = arr_type.size_bits // 8
            len_reg = self.builder.new_vreg(IRType.WORD, "_slen")
            self.builder.mov(len_reg, Immediate(length, IRType.WORD))
            return len_reg

        # Try dope vector (unconstrained array parameter)
        try:
            first, last, _ = self._get_array_dope_vector(expr)
            len_reg = self.builder.new_vreg(IRType.WORD, "_slen")
            self.builder.sub(len_reg, last, first)
            self.builder.add(len_reg, len_reg, Immediate(1, IRType.WORD))
            # Clamp negative to 0 (null array)
            null_check = self.builder.new_vreg(IRType.WORD, "_snc")
            self.builder.cmp_lt(null_check, last, first)
            ok_label = self.builder.new_label("slen_ok")
            self.builder.jz(null_check, ok_label)
            self.builder.mov(len_reg, Immediate(0, IRType.WORD))
            self.builder.label(ok_label)
            return len_reg
        except Exception:
            pass

        # Fallback: assume reasonable default (shouldn't happen)
        len_reg = self.builder.new_vreg(IRType.WORD, "_slen")
        self.builder.mov(len_reg, Immediate(0, IRType.WORD))
        return len_reg

    def _get_composite_ptr(self, expr, expected_type=None) -> 'VReg':
        """Get a pointer to the data of a composite (array/record) expression.

        For local variables with size > 2, the vreg holds the value (first word)
        not an address. This method computes the proper stack address via LEA.
        For parameters, globals, and expressions that already yield pointers,
        it returns the lowered expression directly.
        """
        if isinstance(expr, Identifier):
            name = expr.name.lower()
            if self.ctx:
                # Check prefixed locals first
                local = None
                if hasattr(self, '_nested_body_prefix_stack') and self._nested_body_prefix_stack:
                    for prefix in reversed(self._nested_body_prefix_stack):
                        if prefix:
                            prefixed = f"{prefix}{name}".lower()
                            if prefixed in self.ctx.locals:
                                local = self.ctx.locals[prefixed]
                                break
                if local is None and name in self.ctx.locals:
                    local = self.ctx.locals[name]
                # Check if this is an array type - arrays always need LEA
                # even for small arrays (size <= 2) since array comparison
                # code expects pointers, not inline values.
                is_array_type = False
                if local and local.ada_type:
                    from uada80.type_system import ArrayType as _ATComp
                    if isinstance(local.ada_type, _ATComp):
                        is_array_type = True
                    elif isinstance(local.ada_type, SubtypeIndication):
                        # Check if the SubtypeIndication wraps a Slice (constrained array)
                        inner_tm = getattr(local.ada_type, 'type_mark', None)
                        if isinstance(inner_tm, Slice):
                            is_array_type = True
                if local and (local.size > 2 or is_array_type):
                    # Composite type on stack — compute address via LEA
                    frame_offset = -(local.stack_offset + local.size)
                    addr = self.builder.new_vreg(IRType.PTR, f"_{name}_ptr")
                    self.builder.emit(IRInstr(
                        OpCode.LEA, dst=addr,
                        src1=MemoryLocation(offset=frame_offset, ir_type=IRType.PTR, is_frame_offset=True),
                        comment=f"composite address of {name}"
                    ))
                    return addr
                # For params (unconstrained arrays), the param vreg IS a pointer
                if name in self.ctx.params:
                    return self.ctx.params[name]

        # For QualifiedExpr T'(X) or TypeConversion/IndexedComponent T(X),
        # unwrap to get the composite pointer of the inner expression.
        if isinstance(expr, QualifiedExpr):
            return self._get_composite_ptr(expr.expr)
        if isinstance(expr, TypeConversion):
            return self._get_composite_ptr(expr.expr)
        if isinstance(expr, IndexedComponent) and isinstance(expr.prefix, (Identifier, SelectedName)):
            # Check if this is a type conversion (prefix is a type name)
            sym = None
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
            elif isinstance(expr.prefix, SelectedName):
                resolved = self._resolve_local_type(expr.prefix)
                if resolved:
                    # It's a type conversion - get pointer to the inner expression
                    if expr.indices:
                        return self._get_composite_ptr(expr.indices[0])
            if sym and sym.kind in (SymbolKind.TYPE, SymbolKind.SUBTYPE):
                # Type conversion — unwrap to inner expression
                if expr.indices:
                    return self._get_composite_ptr(expr.indices[0])

        # For aggregate expressions with a known array type, allocate a flat
        # contiguous buffer and fill it using _lower_aggregate_to_target.
        # This ensures multi-dimensional aggregates are laid out flat (matching
        # how array variables are stored) so memcmp comparison works correctly.
        if isinstance(expr, Aggregate):
            expr_type = self._get_expr_type(expr)
            if not expr_type and expected_type and isinstance(expected_type, (ArrayType, RecordType)):
                expr_type = expected_type
            if expr_type and isinstance(expr_type, (ArrayType, RecordType)):
                size = expr_type.size_bytes() if hasattr(expr_type, 'size_bytes') else 0
                if size > 0:
                    # Allocate stack space for the flat aggregate
                    sp_adj = self.builder.new_vreg(IRType.WORD, "_agg_sp")
                    self.builder.emit(IRInstr(
                        OpCode.SUB, sp_adj,
                        MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
                        Immediate(size, IRType.WORD),
                        comment=f"allocate flat aggregate ({size} bytes)"
                    ))
                    self.builder.emit(IRInstr(
                        OpCode.MOV,
                        MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
                        sp_adj,
                    ))
                    agg_addr = self.builder.new_vreg(IRType.PTR, "_flat_agg")
                    self.builder.mov(agg_addr, sp_adj, comment="flat aggregate base address")
                    # Zero-init
                    for i in range(0, size, 2):
                        self._store_at_offset(agg_addr, i, Immediate(0, IRType.WORD))
                    # Fill using aggregate-to-target (handles multi-dim correctly)
                    self._lower_aggregate_to_target(expr, agg_addr, expr_type)
                    return agg_addr

        # For function calls or other expressions that produce composite results,
        # lower the expression, store in a temp, and return the temp address.
        expr_type = self._get_expr_type(expr)
        if expr_type and isinstance(expr_type, (RecordType, ArrayType)):
            # The lowered result is a value (first word), but we need a pointer.
            # Store the full composite in a frame temp and return its address.
            result = self._lower_expr(expr)
            size = (expr_type.size_bits + 7) // 8 if expr_type.size_bits else 2
            if size > 2:
                # For composite results from function calls, the result vreg
                # holds the address of the return value buffer — use it directly
                return result

        # Default: use the normal lowered expression (works for globals, pointers, etc.)
        return self._lower_expr(expr)

    def _lower_record_comparison(self, op: BinaryOp, left, right, rec_type: RecordType):
        """Lower record equality/inequality comparison.

        Compares records component-by-component using byte-by-byte memcmp.
        For tagged types, skips the vtable pointer at offset 0.
        """
        result = self.builder.new_vreg(IRType.WORD, "_rec_cmp_result")

        # Get the size to compare and the starting offset
        total_size = rec_type.size_bytes()
        start_offset = 2 if rec_type.is_tagged else 0
        cmp_size = total_size - start_offset

        if cmp_size <= 0:
            # Empty record — always equal
            self.builder.mov(result, Immediate(1 if op == BinaryOp.EQ else 0, IRType.WORD))
            return result

        # Adjust pointers to skip vtable if tagged
        if start_offset > 0:
            left_adj = self.builder.new_vreg(IRType.PTR, "_rec_l")
            right_adj = self.builder.new_vreg(IRType.PTR, "_rec_r")
            self.builder.add(left_adj, left, Immediate(start_offset, IRType.WORD))
            self.builder.add(right_adj, right, Immediate(start_offset, IRType.WORD))
        else:
            left_adj = left
            right_adj = right

        # Call _memcmp: stack layout is IX+4=size, IX+6=ptr2, IX+8=ptr1
        # Push in reverse order: ptr1 first (goes to IX+8), ptr2, size last (IX+4)
        self.builder.push(left_adj)
        self.builder.push(right_adj)
        self.builder.push(Immediate(cmp_size, IRType.WORD))
        self.builder.call(Label("_memcmp"), comment="record comparison")

        cmp_result = self.builder.new_vreg(IRType.WORD, "_mcmp")
        self.builder.emit(IRInstr(
            OpCode.MOV, cmp_result,
            MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
            comment="capture memcmp result"
        ))

        # Clean up stack (3 arguments)
        temp = self.builder.new_vreg(IRType.WORD, "_discard")
        self.builder.pop(temp)
        self.builder.pop(temp)
        self.builder.pop(temp)

        # Convert to boolean: memcmp returns 0 if equal
        if op == BinaryOp.EQ:
            self.builder.cmp_eq(result, cmp_result, Immediate(0, IRType.WORD))
        elif op == BinaryOp.NE:
            self.builder.cmp_ne(result, cmp_result, Immediate(0, IRType.WORD))
        else:
            # Records only support = and /=, but handle gracefully
            self.builder.cmp_eq(result, cmp_result, Immediate(0, IRType.WORD))

        return result

    def _lower_array_comparison(self, op: BinaryOp, left, right, arr_type: ArrayType,
                                expr=None):
        """Lower array equality/inequality comparison using memcmp.

        For constrained arrays, compares the full array data byte-by-byte.
        For unconstrained arrays (e.g. parameters), computes size at runtime
        from the dope vector bounds.
        """
        result = self.builder.new_vreg(IRType.WORD, "_arr_cmp_result")

        # Get element size for the array's component type
        elem_size = 2  # default for Z80 16-bit words
        if arr_type.component_type:
            if hasattr(arr_type.component_type, 'size_bytes'):
                es = arr_type.component_type.size_bytes()
                if es and es > 0:
                    elem_size = es
            # For nested arrays (multi-dim stored as array-of-arrays), use element_size_bytes
            if isinstance(arr_type.component_type, ArrayType):
                elem_size = arr_type.element_size_bytes()

        # Get the total size of the array in bytes
        cmp_size = arr_type.size_bytes() if hasattr(arr_type, 'size_bytes') else 0

        # For unconstrained arrays or zero-size, try computing from bounds and component size
        if cmp_size <= 0 and arr_type.index_types and arr_type.component_type:
            for idx_type in arr_type.index_types:
                if hasattr(idx_type, 'range_constraint') and idx_type.range_constraint:
                    rc = idx_type.range_constraint
                    if hasattr(rc, 'first') and hasattr(rc, 'last'):
                        try:
                            n = int(rc.last) - int(rc.first) + 1
                            cmp_size = max(0, n * elem_size)
                        except (ValueError, TypeError):
                            pass

        if cmp_size <= 0 and expr is not None:
            # Unconstrained array — compute size at runtime from dope vector bounds.
            # Get bounds for the left operand (the array variable, not the aggregate).
            # For multi-dimensional arrays, total elements = product of all dimension lengths.
            ndims = len(arr_type.index_types) if arr_type.index_types else 1
            all_bounds = self._get_array_dope_vector_multidim(expr.left, ndims)

            # Compute total element count: product of (last - first + 1) for each dimension
            total_elems = None
            for dim_first, dim_last in all_bounds:
                dim_len = self.builder.new_vreg(IRType.WORD, "_dim_len")
                self.builder.sub(dim_len, dim_last, dim_first)
                self.builder.add(dim_len, dim_len, Immediate(1, IRType.WORD))
                if total_elems is None:
                    total_elems = dim_len
                else:
                    new_total = self.builder.new_vreg(IRType.WORD, "_total_elems")
                    self.builder.mul(new_total, total_elems, dim_len)
                    total_elems = new_total

            # Multiply by element size to get byte count
            if total_elems is not None:
                if elem_size != 1:
                    cmp_size_reg = self.builder.new_vreg(IRType.WORD, "_cmp_size")
                    self.builder.mul(cmp_size_reg, total_elems, Immediate(elem_size, IRType.WORD))
                else:
                    cmp_size_reg = total_elems

                # Call _memcmp with runtime-computed size
                self.builder.push(left)
                self.builder.push(right)
                self.builder.push(cmp_size_reg)
                self.builder.call(Label("_memcmp"), comment="array comparison (unconstrained)")

                cmp_result = self.builder.new_vreg(IRType.WORD, "_mcmp")
                self.builder.emit(IRInstr(
                    OpCode.MOV, cmp_result,
                    MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                    comment="capture memcmp result"
                ))

                # Clean up stack (3 arguments)
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                self.builder.pop(temp)
                self.builder.pop(temp)

                # Convert to boolean: memcmp returns 0 if equal
                if op == BinaryOp.EQ:
                    self.builder.cmp_eq(result, cmp_result, Immediate(0, IRType.WORD))
                elif op == BinaryOp.NE:
                    self.builder.cmp_ne(result, cmp_result, Immediate(0, IRType.WORD))
                else:
                    self.builder.cmp_eq(result, cmp_result, Immediate(0, IRType.WORD))

                return result

        if cmp_size <= 0:
            # Can't determine size - fall back to scalar comparison
            if op == BinaryOp.EQ:
                self.builder.cmp_eq(result, left, right)
            else:
                self.builder.cmp_ne(result, left, right)
            return result

        # Call _memcmp: stack layout is IX+4=size, IX+6=ptr2, IX+8=ptr1
        # Push in reverse order: ptr1 first (goes to IX+8), ptr2, size last (IX+4)
        self.builder.push(left)
        self.builder.push(right)
        self.builder.push(Immediate(cmp_size, IRType.WORD))
        self.builder.call(Label("_memcmp"), comment="array comparison")

        cmp_result = self.builder.new_vreg(IRType.WORD, "_mcmp")
        self.builder.emit(IRInstr(
            OpCode.MOV, cmp_result,
            MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
            comment="capture memcmp result"
        ))

        # Clean up stack (3 arguments)
        temp = self.builder.new_vreg(IRType.WORD, "_discard")
        self.builder.pop(temp)
        self.builder.pop(temp)
        self.builder.pop(temp)

        # Convert to boolean: memcmp returns 0 if equal
        if op == BinaryOp.EQ:
            self.builder.cmp_eq(result, cmp_result, Immediate(0, IRType.WORD))
        elif op == BinaryOp.NE:
            self.builder.cmp_ne(result, cmp_result, Immediate(0, IRType.WORD))
        else:
            self.builder.cmp_eq(result, cmp_result, Immediate(0, IRType.WORD))

        return result

    def _lower_array_ordering(self, op: BinaryOp, left_ptr, right_ptr, arr_type: ArrayType, expr):
        """Lower lexicographic ordering comparison for 1D arrays.

        Compares arrays element-by-element. If all compared elements are equal,
        the shorter array is less than the longer one. Null arrays equal each other.
        """
        result = self.builder.new_vreg(IRType.WORD, "_arr_ord")

        # Get bounds for both arrays (may re-lower expr but that's OK for identifiers)
        left_first, left_last, _ = self._get_array_dope_vector(expr.left)
        right_first, right_last, _ = self._get_array_dope_vector(expr.right)

        # Compute lengths: max(0, last - first + 1)
        # For left array
        left_len = self.builder.new_vreg(IRType.WORD, "_left_len")
        self.builder.sub(left_len, left_last, left_first)
        self.builder.add(left_len, left_len, Immediate(1, IRType.WORD))
        # Clamp: if last < first, length = 0
        left_null = self.builder.new_vreg(IRType.WORD, "_lnull")
        self.builder.cmp_lt(left_null, left_last, left_first)
        lnn_label = self.builder.new_label("acmp_lnn")
        lnl_label = self.builder.new_label("acmp_lnl")
        self.builder.jz(left_null, lnn_label)
        self.builder.mov(left_len, Immediate(0, IRType.WORD))
        self.builder.label(lnn_label)

        # For right array
        right_len = self.builder.new_vreg(IRType.WORD, "_right_len")
        self.builder.sub(right_len, right_last, right_first)
        self.builder.add(right_len, right_len, Immediate(1, IRType.WORD))
        right_null = self.builder.new_vreg(IRType.WORD, "_rnull")
        self.builder.cmp_lt(right_null, right_last, right_first)
        rnn_label = self.builder.new_label("acmp_rnn")
        self.builder.jz(right_null, rnn_label)
        self.builder.mov(right_len, Immediate(0, IRType.WORD))
        self.builder.label(rnn_label)

        # min_len = min(left_len, right_len)
        min_len = self.builder.new_vreg(IRType.WORD, "_min_len")
        self.builder.mov(min_len, left_len)
        r_smaller = self.builder.new_vreg(IRType.WORD, "_rs")
        self.builder.cmp_lt(r_smaller, right_len, left_len)
        min_skip = self.builder.new_label("acmp_msk")
        self.builder.jz(r_smaller, min_skip)
        self.builder.mov(min_len, right_len)
        self.builder.label(min_skip)

        # Element size (2 bytes for word-sized elements)
        comp_size = 2
        if hasattr(arr_type, 'component_type') and arr_type.component_type:
            if hasattr(arr_type.component_type, 'size_bytes'):
                cs = arr_type.component_type.size_bytes()
                if cs > 0:
                    comp_size = cs

        # Labels for the comparison loop
        loop_label = self.builder.new_label("acmp_loop")
        cmp_len_label = self.builder.new_label("acmp_clen")
        lt_label = self.builder.new_label("acmp_lt")
        gt_label = self.builder.new_label("acmp_gt")
        eq_label = self.builder.new_label("acmp_eq")
        done_label = self.builder.new_label("acmp_done")

        # i = 0 (element counter)
        i_reg = self.builder.new_vreg(IRType.WORD, "_i")
        self.builder.mov(i_reg, Immediate(0, IRType.WORD))

        # loop:
        self.builder.label(loop_label)

        # if i >= min_len: goto cmp_len
        done_cmp = self.builder.new_vreg(IRType.WORD, "_dcmp")
        self.builder.cmp_ge(done_cmp, i_reg, min_len)
        self.builder.jnz(done_cmp, cmp_len_label)

        # offset = i * comp_size
        offset = self.builder.new_vreg(IRType.WORD, "_off")
        if comp_size == 2:
            self.builder.add(offset, i_reg, i_reg)  # i * 2
        elif comp_size == 1:
            self.builder.mov(offset, i_reg)
        else:
            self.builder.mul(offset, i_reg, Immediate(comp_size, IRType.WORD))

        # left_elem = load(left_ptr + offset)
        left_addr = self.builder.new_vreg(IRType.PTR, "_la")
        self.builder.add(left_addr, left_ptr, offset)
        left_elem = self.builder.new_vreg(IRType.WORD, "_le")
        self.builder.emit(IRInstr(
            OpCode.LOAD, left_elem,
            MemoryLocation(base=left_addr, offset=0, ir_type=IRType.WORD),
            comment="load left array element"
        ))

        # right_elem = load(right_ptr + offset)
        right_addr = self.builder.new_vreg(IRType.PTR, "_ra")
        self.builder.add(right_addr, right_ptr, offset)
        right_elem = self.builder.new_vreg(IRType.WORD, "_re")
        self.builder.emit(IRInstr(
            OpCode.LOAD, right_elem,
            MemoryLocation(base=right_addr, offset=0, ir_type=IRType.WORD),
            comment="load right array element"
        ))

        # For byte-sized elements, mask off the high byte (LOAD always reads 2 bytes)
        if comp_size == 1:
            self.builder.and_(left_elem, left_elem, Immediate(0xFF, IRType.WORD))
            self.builder.and_(right_elem, right_elem, Immediate(0xFF, IRType.WORD))

        # if left_elem < right_elem: goto lt
        lt_cmp = self.builder.new_vreg(IRType.WORD, "_ltc")
        self.builder.cmp_lt(lt_cmp, left_elem, right_elem)
        self.builder.jnz(lt_cmp, lt_label)

        # if left_elem > right_elem: goto gt
        gt_cmp = self.builder.new_vreg(IRType.WORD, "_gtc")
        self.builder.cmp_gt(gt_cmp, left_elem, right_elem)
        self.builder.jnz(gt_cmp, gt_label)

        # i += 1
        self.builder.add(i_reg, i_reg, Immediate(1, IRType.WORD))
        self.builder.jmp(loop_label)

        # cmp_len: all compared elements are equal, compare lengths
        self.builder.label(cmp_len_label)
        len_lt = self.builder.new_vreg(IRType.WORD, "_llt")
        self.builder.cmp_lt(len_lt, left_len, right_len)
        self.builder.jnz(len_lt, lt_label)
        len_gt = self.builder.new_vreg(IRType.WORD, "_lgt")
        self.builder.cmp_gt(len_gt, left_len, right_len)
        self.builder.jnz(len_gt, gt_label)
        self.builder.jmp(eq_label)

        # lt: left < right
        self.builder.label(lt_label)
        if op in (BinaryOp.LT, BinaryOp.LE):
            self.builder.mov(result, Immediate(1, IRType.WORD))
        else:
            self.builder.mov(result, Immediate(0, IRType.WORD))
        self.builder.jmp(done_label)

        # gt: left > right
        self.builder.label(gt_label)
        if op in (BinaryOp.GT, BinaryOp.GE):
            self.builder.mov(result, Immediate(1, IRType.WORD))
        else:
            self.builder.mov(result, Immediate(0, IRType.WORD))
        self.builder.jmp(done_label)

        # eq: arrays are equal
        self.builder.label(eq_label)
        if op in (BinaryOp.LE, BinaryOp.GE):
            self.builder.mov(result, Immediate(1, IRType.WORD))
        else:
            self.builder.mov(result, Immediate(0, IRType.WORD))
        self.builder.jmp(done_label)

        self.builder.label(done_label)
        return result

    def _is_boolean_array_type(self, arr_type) -> bool:
        """Check if an array type has Boolean (or derived-from-Boolean) component."""
        if not isinstance(arr_type, ArrayType) or not arr_type.component_type:
            return False
        comp = arr_type.component_type
        # Direct Boolean check
        if getattr(comp, 'name', '').lower() == 'boolean':
            return True
        # Walk base_type chain for derived-from-Boolean
        current = comp
        while hasattr(current, 'base_type') and current.base_type:
            current = current.base_type
            if getattr(current, 'name', '').lower() == 'boolean':
                return True
        return False

    def _lower_bool_array_binary(self, op: BinaryOp, left_ptr, right_ptr,
                                  arr_type: ArrayType, expr):
        """Lower element-wise AND/OR/XOR on boolean arrays (Ada RM 4.5.6).

        The result inherits the left operand's bounds.
        Raises CONSTRAINT_ERROR if operand lengths differ.
        """
        # Get bounds info for both arrays
        left_first, left_last, _ = self._get_array_dope_vector(expr.left)
        right_first, right_last, _ = self._get_array_dope_vector(expr.right)

        # Compute left length
        left_len = self.builder.new_vreg(IRType.WORD, "_bll")
        self.builder.sub(left_len, left_last, left_first)
        self.builder.add(left_len, left_len, Immediate(1, IRType.WORD))

        # Compute right length
        right_len = self.builder.new_vreg(IRType.WORD, "_brl")
        self.builder.sub(right_len, right_last, right_first)
        self.builder.add(right_len, right_len, Immediate(1, IRType.WORD))

        # Check lengths match (CONSTRAINT_ERROR if different)
        len_ne = self.builder.new_vreg(IRType.WORD, "_bne")
        self.builder.cmp_ne(len_ne, left_len, right_len)
        self.builder.jnz(len_ne, Label("_raise_constraint_error"))

        # Element size: 2 bytes for non-packed Boolean arrays
        elem_size = arr_type.element_size_bytes() if hasattr(arr_type, 'element_size_bytes') else 2

        # Allocate result array on stack: length * elem_size bytes
        total_size = self.builder.new_vreg(IRType.WORD, "_bsz")
        if elem_size == 2:
            self.builder.add(total_size, left_len, left_len)  # length * 2
        else:
            self.builder.mul(total_size, left_len, Immediate(elem_size, IRType.WORD))

        result_ptr = self.builder.new_vreg(IRType.PTR, "_bres")
        self.builder.emit(IRInstr(
            OpCode.SUB,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            total_size,
            comment="allocate bool array result"
        ))
        self.builder.emit(IRInstr(
            OpCode.MOV, result_ptr,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.PTR),
            comment="bool array result = SP"
        ))

        # Loop counter
        i_reg = self.builder.new_vreg(IRType.WORD, "_bi")
        self.builder.mov(i_reg, Immediate(0, IRType.WORD))

        loop_label = self.builder.new_label("ba_loop")
        done_label = self.builder.new_label("ba_done")

        self.builder.label(loop_label)

        # if i >= length: goto done
        done_cmp = self.builder.new_vreg(IRType.WORD, "_bdc")
        self.builder.cmp_ge(done_cmp, i_reg, left_len)
        self.builder.jnz(done_cmp, done_label)

        # offset = i * elem_size
        offset_reg = self.builder.new_vreg(IRType.WORD, "_boff")
        if elem_size == 2:
            self.builder.add(offset_reg, i_reg, i_reg)
        else:
            self.builder.mul(offset_reg, i_reg, Immediate(elem_size, IRType.WORD))

        # Load left element
        left_addr = self.builder.new_vreg(IRType.PTR, "_bla")
        self.builder.add(left_addr, left_ptr, offset_reg)
        left_elem = self.builder.new_vreg(IRType.WORD, "_ble")
        self.builder.emit(IRInstr(
            OpCode.LOAD, left_elem,
            MemoryLocation(base=left_addr, offset=0, ir_type=IRType.WORD),
            comment="load bool array left element"
        ))

        # Load right element
        right_addr = self.builder.new_vreg(IRType.PTR, "_bra")
        self.builder.add(right_addr, right_ptr, offset_reg)
        right_elem = self.builder.new_vreg(IRType.WORD, "_bre")
        self.builder.emit(IRInstr(
            OpCode.LOAD, right_elem,
            MemoryLocation(base=right_addr, offset=0, ir_type=IRType.WORD),
            comment="load bool array right element"
        ))

        # Perform operation
        res_elem = self.builder.new_vreg(IRType.WORD, "_bop")
        if op == BinaryOp.AND:
            self.builder.and_(res_elem, left_elem, right_elem)
        elif op == BinaryOp.OR:
            self.builder.or_(res_elem, left_elem, right_elem)
        elif op == BinaryOp.XOR:
            self.builder.xor(res_elem, left_elem, right_elem)

        # Store result element
        res_addr = self.builder.new_vreg(IRType.PTR, "_bra")
        self.builder.add(res_addr, result_ptr, offset_reg)
        self.builder.emit(IRInstr(
            OpCode.STORE,
            dst=MemoryLocation(base=res_addr, offset=0, ir_type=IRType.WORD),
            src1=res_elem,
            comment="store bool array result element"
        ))

        # i++
        self.builder.add(i_reg, i_reg, Immediate(1, IRType.WORD))
        self.builder.jmp(loop_label)

        self.builder.label(done_label)

        return result_ptr

    def _lower_bool_array_not(self, operand_ptr, arr_type: ArrayType, expr):
        """Lower element-wise NOT on a boolean array (Ada RM 4.5.6).

        Result inherits the operand's bounds.
        """
        # Get bounds
        first_val, last_val, _ = self._get_array_dope_vector(expr.operand)

        # Compute length
        arr_len = self.builder.new_vreg(IRType.WORD, "_bnl")
        self.builder.sub(arr_len, last_val, first_val)
        self.builder.add(arr_len, arr_len, Immediate(1, IRType.WORD))

        # Element size
        elem_size = arr_type.element_size_bytes() if hasattr(arr_type, 'element_size_bytes') else 2

        # Allocate result on stack
        total_size = self.builder.new_vreg(IRType.WORD, "_bnsz")
        if elem_size == 2:
            self.builder.add(total_size, arr_len, arr_len)
        else:
            self.builder.mul(total_size, arr_len, Immediate(elem_size, IRType.WORD))

        result_ptr = self.builder.new_vreg(IRType.PTR, "_bnres")
        self.builder.emit(IRInstr(
            OpCode.SUB,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.WORD),
            total_size,
            comment="allocate bool array NOT result"
        ))
        self.builder.emit(IRInstr(
            OpCode.MOV, result_ptr,
            MemoryLocation(is_global=False, symbol_name="_SP", ir_type=IRType.PTR),
            comment="bool NOT result = SP"
        ))

        # Loop
        i_reg = self.builder.new_vreg(IRType.WORD, "_bni")
        self.builder.mov(i_reg, Immediate(0, IRType.WORD))

        loop_label = self.builder.new_label("bn_loop")
        done_label = self.builder.new_label("bn_done")

        self.builder.label(loop_label)

        done_cmp = self.builder.new_vreg(IRType.WORD, "_bndc")
        self.builder.cmp_ge(done_cmp, i_reg, arr_len)
        self.builder.jnz(done_cmp, done_label)

        offset_reg = self.builder.new_vreg(IRType.WORD, "_bnoff")
        if elem_size == 2:
            self.builder.add(offset_reg, i_reg, i_reg)
        else:
            self.builder.mul(offset_reg, i_reg, Immediate(elem_size, IRType.WORD))

        # Load element
        src_addr = self.builder.new_vreg(IRType.PTR, "_bnsa")
        self.builder.add(src_addr, operand_ptr, offset_reg)
        src_elem = self.builder.new_vreg(IRType.WORD, "_bnse")
        self.builder.emit(IRInstr(
            OpCode.LOAD, src_elem,
            MemoryLocation(base=src_addr, offset=0, ir_type=IRType.WORD),
            comment="load bool array element for NOT"
        ))

        # NOT: XOR with 1 (logical negation: 0↔1)
        res_elem = self.builder.new_vreg(IRType.WORD, "_bnop")
        self.builder.xor(res_elem, src_elem, Immediate(1, IRType.WORD))

        # Store result
        dst_addr = self.builder.new_vreg(IRType.PTR, "_bnda")
        self.builder.add(dst_addr, result_ptr, offset_reg)
        self.builder.emit(IRInstr(
            OpCode.STORE,
            dst=MemoryLocation(base=dst_addr, offset=0, ir_type=IRType.WORD),
            src1=res_elem,
            comment="store bool array NOT result"
        ))

        self.builder.add(i_reg, i_reg, Immediate(1, IRType.WORD))
        self.builder.jmp(loop_label)

        self.builder.label(done_label)

        return result_ptr

    def _unary_operator_to_name(self, op: UnaryOp) -> Optional[str]:
        """Convert a unary operator to its Ada operator function name."""
        op_names = {
            UnaryOp.MINUS: '"-"',
            UnaryOp.PLUS: '"+"',
            UnaryOp.NOT: '"not"',
            UnaryOp.ABS: '"abs"',
        }
        return op_names.get(op)

    def _lookup_user_unary_operator(self, op: UnaryOp, operand: Expr) -> Optional[Symbol]:
        """Look up a user-defined unary operator for the given operand.

        Returns the Symbol for the user-defined operator function if one exists,
        otherwise returns None to use the built-in operator.
        """
        # Get the operator function name
        op_name = self._unary_operator_to_name(op)
        if op_name is None:
            return None

        # Get operand type
        operand_type = self._get_expr_type(operand)
        if operand_type is None:
            return None

        # Don't look up operators for predefined types - use built-ins
        predefined_type_names = {'integer', 'boolean', 'character', 'natural', 'positive'}
        if hasattr(operand_type, 'name') and operand_type.name.lower() in predefined_type_names:
            return None

        # Look up operator overloads
        overloads = self.symbols.all_overloads(op_name)
        if not overloads:
            # Also try without quotes
            alt_name = op_name.strip('"')
            overloads = self.symbols.all_overloads(alt_name)
            if not overloads:
                return None

        # Find matching overload based on operand type
        from uada80.type_system import types_compatible

        for sym in overloads:
            if sym.kind != SymbolKind.FUNCTION:
                continue
            if len(sym.parameters) != 1:
                continue

            # Check if parameter type matches operand type
            param_type = sym.parameters[0].ada_type if sym.parameters[0].ada_type else None
            if param_type is None:
                continue

            if (param_type.name == operand_type.name or
                types_compatible(param_type, operand_type)):
                return sym

        return None

    def _call_user_unary_operator(self, sym: Symbol, operand: Expr):
        """Generate a call to a user-defined unary operator function."""
        result = self.builder.new_vreg(IRType.WORD, "_unary_result")

        # Evaluate operand
        operand_val = self._lower_expr(operand)

        # Push argument
        self.builder.push(operand_val)

        # Call the operator function - mangle operator name for assembly
        op_func_name = self._mangle_operator_name(sym.name.lower())

        # Check for nested subprogram label (includes scope prefix)
        if op_func_name in self._nested_subprogram_labels:
            op_func_name = self._nested_subprogram_labels[op_func_name]

        self.builder.call(Label(op_func_name), comment=f"user-defined unary {sym.name}")

        # Clean up stack (1 argument)
        temp = self.builder.new_vreg(IRType.WORD, "_discard")
        self.builder.pop(temp)

        # Capture result from HL register
        self.builder.emit(IRInstr(
            OpCode.MOV, result,
            MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
            comment=f"capture {sym.name} result from HL"
        ))

        return result

    def _lower_unary(self, expr: UnaryExpr):
        """Lower a unary expression."""
        op = expr.op

        # Check for user-defined operator overloading
        user_op = self._lookup_user_unary_operator(op, expr.operand)
        if user_op is not None:
            return self._call_user_unary_operator(user_op, expr.operand)

        # Boolean array NOT: element-wise negation (Ada RM 4.5.6)
        operand_type = self._get_expr_type(expr.operand)
        if op == UnaryOp.NOT and operand_type and isinstance(operand_type, ArrayType):
            if self._is_boolean_array_type(operand_type):
                operand_ptr = self._get_composite_ptr(expr.operand)
                return self._lower_bool_array_not(operand_ptr, operand_type, expr)

        # Check if this is a Float64 operation.
        # Don't enter Float64 path for RealLiteral (universal_real — context-dependent).
        if self._is_float64_type(operand_type) and not isinstance(expr.operand, RealLiteral):
            if op in (UnaryOp.MINUS, UnaryOp.ABS, UnaryOp.PLUS):
                operand_ptr = self._lower_float64_operand(expr.operand)
                return self._lower_float64_unary(op, operand_ptr, operand_type)

        operand = self._lower_expr(expr.operand)
        result = self.builder.new_vreg(IRType.WORD, "_tmp")

        if op == UnaryOp.MINUS:
            self.builder.neg(result, operand)
        elif op == UnaryOp.NOT:
            # For boolean-like types (2-value enumerations including derived Boolean),
            # use XOR 1 for logical NOT (0↔1). Bitwise NOT gives 0xFFFE/0xFFFF.
            operand_type = self._get_expr_type(expr.operand)
            is_boolean_like = False
            is_modular = False
            if operand_type:
                from uada80.type_system import EnumerationType, is_derived_from, ModularType
                if isinstance(operand_type, EnumerationType):
                    if operand_type.name == "Boolean" or is_derived_from(operand_type, "Boolean"):
                        is_boolean_like = True
                    elif len(operand_type.literals) == 2:
                        is_boolean_like = True
                elif isinstance(operand_type, ModularType):
                    is_modular = True
            if is_modular:
                # Modular types: use true bitwise NOT
                self.builder.not_(result, operand)
            elif is_boolean_like or operand_type is None:
                # Boolean or unknown type: use logical NOT (XOR 1).
                # Default to logical NOT for unknown types since boolean NOT
                # is far more common than bitwise NOT, and bitwise NOT on
                # an unknown type would produce 0xFFFE instead of 0.
                self.builder.xor(result, operand, Immediate(1, IRType.WORD))
            else:
                self.builder.not_(result, operand)
        elif op == UnaryOp.ABS:
            # ABS: if negative, negate; otherwise keep same
            # Check for overflow: ABS(INTEGER'FIRST) must raise Constraint_Error
            # because -(-32768) = 32768 which doesn't fit in 16-bit signed
            operand_type = self._get_expr_type(expr.operand)
            if operand_type and hasattr(operand_type, 'high') and hasattr(operand_type, 'low'):
                # If -low > high, then ABS(low) overflows
                if operand_type.low is not None and operand_type.high is not None:
                    if -operand_type.low > operand_type.high:
                        min_check = self.builder.new_vreg(IRType.BOOL, "_abs_min")
                        self.builder.cmp_eq(min_check, operand, Immediate(operand_type.low, IRType.WORD))
                        self.builder.jnz(min_check, Label("_raise_constraint_error"))

            cond = self.builder.new_vreg(IRType.BOOL, "_abs_cond")
            self.builder.cmp_lt(cond, operand, Immediate(0, IRType.WORD))
            # If positive (not negative), skip negation
            pos_label = self._new_label("abs_pos")
            end_label = self._new_label("abs_end")
            self.builder.jz(cond, Label(pos_label))
            # Negative path: negate
            self.builder.neg(result, operand)
            self.builder.jmp(Label(end_label))
            # Positive path: copy as-is
            pos_block = self.builder.new_block(pos_label)
            self.builder.set_block(pos_block)
            self.builder.mov(result, operand)
            # End
            end_block = self.builder.new_block(end_label)
            self.builder.set_block(end_block)
        elif op == UnaryOp.PLUS:
            self.builder.mov(result, operand)
        else:
            self.builder.mov(result, operand)

        return result

    def _lookup_type_symbol(self, type_name: str) -> Optional[Symbol]:
        """Look up a type symbol by name, searching scopes and package public_symbols."""
        # Direct lookup first (works when 'use' clause is active)
        sym = self.symbols.lookup(type_name)
        if sym and sym.kind == SymbolKind.TYPE:
            return sym
        # Search all scopes for packages, then check their public_symbols
        type_name_lower = type_name.lower()
        scope = self.symbols.current_scope
        while scope is not None:
            for sym_name, sym_entry in scope.symbols.items():
                if sym_entry.kind == SymbolKind.PACKAGE and sym_entry.public_symbols:
                    child = sym_entry.public_symbols.get(type_name_lower)
                    if child and child.kind == SymbolKind.TYPE:
                        return child
            scope = scope.parent
        return None

    def _resolve_overload(self, name: str, args: list) -> Optional[Symbol]:
        """Resolve an overloaded function/procedure call.

        Returns the best matching symbol based on argument types.
        """
        from uada80.type_system import types_compatible

        overloads = self.symbols.all_overloads(name)
        if not overloads:
            return None

        if len(overloads) == 1:
            return overloads[0]

        # Get actual argument types
        arg_types = []
        for arg in args:
            if arg.value:
                arg_type = self._get_expr_type(arg.value)
                arg_types.append(arg_type)

        # Find best match
        best_match = None
        best_score = -1

        for sym in overloads:
            if len(sym.parameters) != len(arg_types):
                continue  # Wrong number of arguments

            # Check if all arguments are compatible
            score = 0
            all_match = True
            for i, (param, arg_type) in enumerate(zip(sym.parameters, arg_types)):
                if param.ada_type and arg_type:
                    if param.ada_type.name == arg_type.name:
                        score += 2  # Exact match
                    elif types_compatible(param.ada_type, arg_type):
                        score += 1  # Compatible
                    else:
                        all_match = False
                        break
                else:
                    score += 1  # Assume compatible if types unknown

            if all_match and score > best_score:
                best_score = score
                best_match = sym

        return best_match if best_match else overloads[0]

    def _mangle_operator_name(self, name: str) -> str:
        """Mangle Ada operator names to valid assembly symbol names.

        Ada operator function names like "-", "+", "*" need to be converted
        to valid Z80 assembly symbols.
        """
        # Map of Ada operator symbols to assembly-safe names
        operator_map = {
            '"++"': 'op_pos',    # Unary plus (same name in Ada)
            '"+"': 'op_add',
            '"-"': 'op_sub',
            '"*"': 'op_mul',
            '"/"': 'op_div',
            '"**"': 'op_exp',
            '"mod"': 'op_mod',
            '"rem"': 'op_rem',
            '"abs"': 'op_abs',
            '"and"': 'op_and',
            '"or"': 'op_or',
            '"xor"': 'op_xor',
            '"not"': 'op_not',
            '"="': 'op_eq',
            '"/="': 'op_ne',
            '"<"': 'op_lt',
            '"<="': 'op_le',
            '">"': 'op_gt',
            '">="': 'op_ge',
            '"&"': 'op_concat',
            # Handle without quotes as well
            '+': 'op_add',
            '-': 'op_sub',
            '*': 'op_mul',
            '/': 'op_div',
            '**': 'op_exp',
            'mod': 'op_mod',
            'rem': 'op_rem',
            'abs': 'op_abs',
            'and': 'op_and',
            'or': 'op_or',
            'xor': 'op_xor',
            'not': 'op_not',
            '=': 'op_eq',
            '/=': 'op_ne',
            '<': 'op_lt',
            '<=': 'op_le',
            '>': 'op_gt',
            '>=': 'op_ge',
            '&': 'op_concat',
        }
        # Strip quotes if present
        clean_name = name.strip('"')
        if clean_name in operator_map:
            return operator_map[clean_name]
        if name in operator_map:
            return operator_map[name]
        return name

    def _get_type_name_from_expr(self, expr: Expr) -> Optional[str]:
        """Get the type name from an expression (for type references)."""
        if isinstance(expr, Identifier):
            return expr.name
        elif isinstance(expr, SelectedName):
            # Package.Type -> Type
            return expr.selector
        elif isinstance(expr, AttributeReference):
            # T'Base, T'Class etc. -> T
            return self._get_type_name_from_expr(expr.prefix)
        return None

    def _get_param_type_sig_from_spec(self, parameters: list, return_type_expr: Optional[Expr] = None) -> str:
        """Build a type signature string from ParameterSpec list (at definition time).

        Returns a string combining parameter types and return type, used to uniquely
        identify overloaded functions with the same name.
        Format: "param1,param2->return" or "param1,param2" for procedures.
        """
        types = []
        for param_spec in parameters:
            type_name = self._get_type_name_from_expr(param_spec.type_mark)
            if type_name:
                type_name = type_name.lower()
                # For generic instantiations, substitute actual types for formal types
                if hasattr(self, '_generic_type_map') and self._generic_type_map:
                    mapped = self._generic_type_map.get(type_name, type_name)
                    if isinstance(mapped, str):
                        type_name = mapped.lower()
            else:
                type_name = "_unknown"
            # Each param_spec can have multiple names (e.g., X, Y: Integer)
            for _ in param_spec.names:
                types.append(type_name)
        sig = ",".join(types)
        # Add return type for functions (distinguishes overloads by return type)
        if return_type_expr:
            ret_type = self._get_type_name_from_expr(return_type_expr)
            if ret_type:
                ret_type_lower = ret_type.lower()
                # For generic instantiations, substitute actual types for formal types
                if hasattr(self, '_generic_type_map') and self._generic_type_map:
                    mapped = self._generic_type_map.get(ret_type_lower, ret_type_lower)
                    if isinstance(mapped, str):
                        ret_type_lower = mapped.lower()
                sig = f"{sig}->{ret_type_lower}"
        return sig

    def _get_param_type_sig_from_symbol(self, sym: Optional[Symbol]) -> str:
        """Build a type signature string from a Symbol's parameters (at call time).

        Returns a string matching what was created at definition time.
        Format: "param1,param2->return" or "param1,param2" for procedures.
        """
        if not sym:
            return ""
        types = []
        for param in sym.parameters if sym.parameters else []:
            if param.ada_type:
                type_name = getattr(param.ada_type, 'name', '_unknown').lower()
            else:
                type_name = "_unknown"
            types.append(type_name)
        sig = ",".join(types)
        # Add return type for functions
        if sym.return_type:
            ret_type = getattr(sym.return_type, 'name', '_unknown').lower()
            sig = f"{sig}->{ret_type}"
        return sig

    def _expr_to_name(self, expr) -> str:
        """Convert an expression to a string name (for generating unique identifiers)."""
        if isinstance(expr, Identifier):
            return expr.name
        elif isinstance(expr, SelectedName):
            return f"{self._expr_to_name(expr.prefix)}_{expr.selector}"
        elif isinstance(expr, IndexedComponent):
            return f"{self._expr_to_name(expr.prefix)}_idx"
        elif isinstance(expr, IntegerLiteral):
            return f"lit_{expr.value}"
        else:
            # Fallback - use hash to generate unique name
            return f"expr_{hash(str(expr)) & 0xFFFF:04x}"

    def _get_expr_type(self, expr: Expr) -> Optional[AdaType]:
        """Get the Ada type of an expression."""
        if isinstance(expr, IntegerLiteral):
            return PREDEFINED_TYPES.get("Integer")
        elif isinstance(expr, RealLiteral):
            # Real literals are Long_Float (Float64) by default
            return PREDEFINED_TYPES.get("Long_Float")
        elif isinstance(expr, StringLiteral):
            return PREDEFINED_TYPES.get("String")
        elif isinstance(expr, CharacterLiteral):
            return PREDEFINED_TYPES.get("Character")
        elif isinstance(expr, Identifier):
            # First check local variables
            if self.ctx:
                name = expr.name.lower()
                # Check prefixed locals FIRST (innermost scope wins).
                # When inside P's body (inside C83F01D1), X1 -> C83F01D1.P.X1
                if hasattr(self, '_nested_body_prefix_stack') and self._nested_body_prefix_stack:
                    for prefix in reversed(self._nested_body_prefix_stack):
                        if prefix:
                            prefixed = f"{prefix}{name}".lower()
                            if prefixed in self.ctx.locals:
                                local = self.ctx.locals[prefixed]
                                if local.ada_type:
                                    return self._resolve_local_type(local.ada_type)
                if name in self.ctx.locals:
                    local = self.ctx.locals[name]
                    if local.ada_type:
                        # ada_type might be AST node or AdaType - resolve it
                        return self._resolve_local_type(local.ada_type)
                # Check parameters
                if name in self.ctx.params:
                    param_type_name = self.ctx.param_types.get(name)
                    if param_type_name:
                        type_sym = self.symbols.lookup(param_type_name)
                        if type_sym and type_sym.ada_type:
                            return type_sym.ada_type
                    # Fallback: use stored AdaType when symbol table lookup fails
                    # (e.g. types from imported packages not in lowering scope)
                    if name in self.ctx.param_ada_types:
                        return self.ctx.param_ada_types[name]
                # Also check enclosing contexts (for nested subprograms)
                enc = getattr(self.ctx, 'enclosing_ctx', None)
                while enc:
                    ename = expr.name.lower()
                    if ename in enc.locals:
                        local = enc.locals[ename]
                        if local.ada_type:
                            return self._resolve_local_type(local.ada_type)
                    if ename in getattr(enc, 'params', {}):
                        pt = getattr(enc, 'param_types', {}).get(ename)
                        if pt:
                            ts = self.symbols.lookup(pt)
                            if ts and ts.ada_type:
                                return ts.ada_type
                        pat = getattr(enc, 'param_ada_types', {}).get(ename)
                        if pat:
                            return pat
                    enc = getattr(enc, 'enclosing_ctx', None)
                # Fallback: check for outer-scope variable via _outer_ params
                outer_param_name = f"_outer_{expr.name.lower()}"
                if outer_param_name in self.ctx.params:
                    # Look up type from param_ada_types (set during outer var setup)
                    if outer_param_name in self.ctx.param_ada_types:
                        return self.ctx.param_ada_types[outer_param_name]
            # Then check symbol table
            sym = self.symbols.lookup(expr.name)
            if sym and sym.ada_type:
                return sym.ada_type
        elif isinstance(expr, Parenthesized):
            return self._get_expr_type(expr.expr)
        elif isinstance(expr, UnaryExpr):
            # Unary +/- don't change type; NOT returns Boolean
            return self._get_expr_type(expr.operand)
        elif isinstance(expr, QualifiedExpr):
            # Qualified expression Type'(expr) has the qualified type
            return self._resolve_local_type(expr.type_mark)
        elif isinstance(expr, BinaryExpr):
            # Comparison operators always return Boolean
            if expr.op in (BinaryOp.EQ, BinaryOp.NE, BinaryOp.LT, BinaryOp.LE,
                           BinaryOp.GT, BinaryOp.GE):
                return PREDEFINED_TYPES.get("Boolean")
            # Short-circuit boolean operators return Boolean
            if expr.op in (BinaryOp.AND_THEN, BinaryOp.OR_ELSE):
                return PREDEFINED_TYPES.get("Boolean")
            # AND/OR/XOR on Boolean return Boolean; on other types return operand type
            if expr.op in (BinaryOp.AND, BinaryOp.OR, BinaryOp.XOR):
                left_type = self._get_expr_type(expr.left)
                if left_type and hasattr(left_type, 'name') and left_type.name == "Boolean":
                    return PREDEFINED_TYPES.get("Boolean")
                return left_type
            # Arithmetic/concatenation: result is same type as left operand
            left_type = self._get_expr_type(expr.left)
            return left_type
        elif isinstance(expr, TypeConversion):
            # Type conversion result is the target type
            return self._resolve_local_type(expr.type_mark)
        elif isinstance(expr, IndexedComponent):
            # Check if this is a type conversion: Package.Type(Expr)
            # The parser can't distinguish Type(X) from Array(X), so we check
            # if the prefix resolves to a type name.
            if isinstance(expr.prefix, SelectedName):
                target_type = self._resolve_local_type(expr.prefix)
                if target_type:
                    return target_type
            elif isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.kind in (SymbolKind.TYPE, SymbolKind.SUBTYPE):
                    if sym.ada_type:
                        return sym.ada_type
            # Check if prefix is a function — return its return type
            if isinstance(expr.prefix, Identifier):
                func_sym = self.symbols.lookup(expr.prefix.name)
                if func_sym and func_sym.kind == SymbolKind.FUNCTION and func_sym.return_type:
                    return func_sym.return_type
            # If prefix is an array variable, return the component (element) type.
            # This handles e.g. AT(1) where AT is ARRAY OF T => returns T.
            prefix_type = self._get_expr_type(expr.prefix)
            if isinstance(prefix_type, ArrayType) and prefix_type.component_type:
                return prefix_type.component_type
        elif isinstance(expr, FunctionCall):
            if isinstance(expr.name, Identifier):
                sym = self.symbols.lookup(expr.name.name)
                if sym and sym.return_type:
                    return sym.return_type
        elif isinstance(expr, Dereference):
            prefix_type = self._get_expr_type(expr.prefix)
            if isinstance(prefix_type, AccessType) and prefix_type.designated_type:
                return prefix_type.designated_type
            return prefix_type
        elif isinstance(expr, SelectedName):
            # Handle PKG.T -> resolve to type of T in package PKG
            # First try full hierarchical lookup
            hier_name = self._get_hierarchical_name(expr).lower()
            sym = self.symbols.lookup(hier_name)
            if sym and sym.ada_type:
                return sym.ada_type
            # Try just the selector in symbol table
            sel = expr.selector.lower() if isinstance(expr.selector, str) else str(expr.selector).lower()
            sym = self.symbols.lookup(sel)
            if sym and sym.ada_type:
                return sym.ada_type
            # Try resolving prefix as package and looking up selector in its public_symbols
            if isinstance(expr.prefix, Identifier):
                pkg_name = expr.prefix.name.lower()
                pkg_sym = self.symbols.lookup(pkg_name)
                if pkg_sym and hasattr(pkg_sym, 'public_symbols') and pkg_sym.public_symbols:
                    member = pkg_sym.public_symbols.get(sel)
                    if member and hasattr(member, 'ada_type') and member.ada_type:
                        return member.ada_type
            # Try navigating through nested packages (e.g. C83F01D1.P.X1)
            # Walk the SelectedName chain to resolve the prefix package, then
            # look up the selector in its public_symbols.
            pkg_sym = self._resolve_selected_package(expr.prefix)
            if pkg_sym and hasattr(pkg_sym, 'public_symbols') and pkg_sym.public_symbols:
                member = pkg_sym.public_symbols.get(sel)
                if member and hasattr(member, 'ada_type') and member.ada_type:
                    return member.ada_type
            # Check if the full dotted name matches a local variable
            if self.ctx:
                full_dotted = self._get_selected_name_str(expr).lower()
                if full_dotted in self.ctx.locals:
                    local = self.ctx.locals[full_dotted]
                    if local.ada_type:
                        return self._resolve_local_type(local.ada_type)
            # Check locals for the prefix to handle record field access
            resolved = self._resolve_local_type(expr)
            if resolved:
                return resolved
        elif isinstance(expr, AttributeReference):
            attr_name = expr.attribute.lower() if isinstance(expr.attribute, str) else str(expr.attribute).lower()
            if attr_name in ("image", "img", "wide_image"):
                # IMAGE always returns String
                return PREDEFINED_TYPES.get("String")
            elif attr_name in ("pos", "width"):
                return PREDEFINED_TYPES.get("Integer")
            elif attr_name in ("val", "succ", "pred", "min", "max"):
                # Returns the prefix type (scalar type)
                return self._get_expr_type(expr.prefix) if hasattr(expr, 'prefix') else None
            elif attr_name in ("first", "last"):
                # For arrays, 'First/'Last returns the index type (Integer), not array type
                # For scalar types, returns the prefix type
                prefix_type = self._get_expr_type(expr.prefix) if hasattr(expr, 'prefix') else None
                if prefix_type and isinstance(prefix_type, ArrayType):
                    return PREDEFINED_TYPES.get("Integer")
                return prefix_type
        return None

    def _resolve_selected_package(self, expr) -> Optional[Symbol]:
        """Resolve a SelectedName or Identifier to its package symbol.

        For Identifier("C83F01D1") -> returns the C83F01D1 package symbol.
        For SelectedName(Identifier("C83F01D1"), "P") -> returns P's symbol
        inside C83F01D1's public_symbols.
        """
        if isinstance(expr, Identifier):
            sym = self.symbols.lookup(expr.name)
            if sym and sym.kind == SymbolKind.PACKAGE:
                return sym
            return None
        elif isinstance(expr, SelectedName):
            parent_sym = self._resolve_selected_package(expr.prefix)
            if parent_sym and hasattr(parent_sym, 'public_symbols'):
                sel = expr.selector.lower() if isinstance(expr.selector, str) else str(expr.selector).lower()
                child = parent_sym.public_symbols.get(sel)
                if child and child.kind == SymbolKind.PACKAGE:
                    return child
            return None
        return None

    def _resolve_local_type(self, type_node) -> Optional[AdaType]:
        """Resolve a local variable's type (may be AST node or AdaType)."""
        if type_node is None:
            return None
        # If it's already an AdaType, return it
        from uada80.type_system import AdaType, ModularType, ArrayType, IntegerType, EnumerationType
        if isinstance(type_node, AdaType):
            return type_node
        # Handle anonymous ArrayTypeDef directly
        if isinstance(type_node, ArrayTypeDef):
            bounds = []
            has_dynamic_bounds = False
            if type_node.index_subtypes:
                for idx_range in type_node.index_subtypes:
                    low, high = self._extract_index_bounds(idx_range)
                    if low is None or high is None:
                        has_dynamic_bounds = True
                    else:
                        bounds.append((low, high))
            # Only create ArrayType if all bounds are static
            if not has_dynamic_bounds and bounds:
                comp_type = IntegerType(name="Integer", size_bits=16)
                return ArrayType(
                    name="<anonymous>",
                    component_type=comp_type,
                    bounds=bounds,
                    is_constrained=True,
                )
            # For dynamic bounds, return None (caller must handle)
        # Handle SubtypeIndication wrapper: unwrap to get inner type_mark
        if isinstance(type_node, SubtypeIndication):
            if type_node.type_mark:
                inner = self._resolve_local_type(type_node.type_mark)
                if inner and hasattr(type_node, 'constraint') and type_node.constraint:
                    constraint = type_node.constraint
                    # Handle range constraint for scalar types (e.g., INTEGER RANGE 0..10)
                    if isinstance(constraint, RangeConstraint):
                        range_expr = constraint.range_expr
                        if isinstance(range_expr, RangeExpr):
                            low = self._eval_static_bound(range_expr.low)
                            high = self._eval_static_bound(range_expr.high)
                            if isinstance(low, int) and isinstance(high, int):
                                if isinstance(inner, IntegerType):
                                    return IntegerType(
                                        name=inner.name,
                                        size_bits=inner.size_bits,
                                        low=low,
                                        high=high,
                                        base_type=inner,
                                    )
                                elif isinstance(inner, EnumerationType):
                                    return EnumerationType(
                                        name=inner.name,
                                        size_bits=inner.size_bits,
                                        literals=inner.literals.copy(),
                                        positions=inner.positions.copy() if inner.positions else {},
                                        base_type=inner,
                                        first=low,
                                        last=high,
                                    )
                            # Handle FixedType with float bounds
                            from uada80.type_system import FixedType as _FxTypeR
                            if isinstance(inner, _FxTypeR):
                                try:
                                    flow = float(self._evaluate_static_expr(range_expr.low))
                                    fhigh = float(self._evaluate_static_expr(range_expr.high))
                                    return _FxTypeR(
                                        name=inner.name,
                                        size_bits=inner.size_bits,
                                        delta=inner.delta,
                                        range_first=flow,
                                        range_last=fhigh,
                                        small=inner.small,
                                        base_type=inner,
                                    )
                                except (TypeError, ValueError):
                                    pass
                    # Handle index constraint for unconstrained arrays
                    elif isinstance(inner, ArrayType) and not inner.is_constrained:
                        if hasattr(constraint, 'ranges') and constraint.ranges:
                            bounds = []
                            for rng in constraint.ranges:
                                low, high = self._extract_index_bounds(rng)
                                if low is not None and high is not None:
                                    bounds.append((low, high))
                            if bounds:
                                return ArrayType(
                                    name=inner.name,
                                    component_type=inner.component_type,
                                    bounds=bounds,
                                    is_constrained=True,
                                    index_types=inner.index_types,
                                )
                return inner
            return None
        # Handle Slice as constrained array subtype: I_A(1..10) parsed as Slice
        if isinstance(type_node, Slice):
            base_type = self._resolve_local_type(type_node.prefix)
            if base_type and isinstance(base_type, ArrayType):
                # Apply the slice range as a constraint
                if hasattr(type_node, 'range_expr') and type_node.range_expr:
                    low, high = self._extract_index_bounds(type_node.range_expr)
                    if low is not None and high is not None:
                        return ArrayType(
                            name=base_type.name,
                            component_type=base_type.component_type,
                            bounds=[(low, high)],
                            is_constrained=True,
                            index_types=base_type.index_types,
                        )
            return base_type
        # Handle IndexedComponent as constrained array: I_A_2(1..10, 13..20)
        if isinstance(type_node, IndexedComponent):
            base_type = self._resolve_local_type(type_node.prefix)
            if base_type and isinstance(base_type, ArrayType) and not base_type.is_constrained:
                all_bounds = []
                for idx in type_node.indices:
                    if isinstance(idx, RangeExpr):
                        low, high = self._extract_index_bounds(idx)
                        if low is not None and high is not None:
                            all_bounds.append((low, high))
                        else:
                            all_bounds = []
                            break
                    else:
                        all_bounds = []
                        break
                if all_bounds:
                    return ArrayType(
                        name=base_type.name,
                        component_type=base_type.component_type,
                        bounds=all_bounds,
                        is_constrained=True,
                        index_types=base_type.index_types,
                    )
            return base_type
        # Handle SelectedName (e.g., C3A1003E.Dept_Ptr) — look up by selector or full name
        if isinstance(type_node, SelectedName):
            # Try full hierarchical name first
            full_name = self._get_hierarchical_name(type_node).lower()
            sym = self.symbols.lookup(full_name)
            if sym and sym.ada_type:
                return sym.ada_type
            # Try just the selector
            selector = type_node.selector.lower() if isinstance(type_node.selector, str) else str(type_node.selector).lower()
            sym = self.symbols.lookup(selector)
            if sym and sym.ada_type:
                return sym.ada_type
            # Fallback: look up the prefix as a package and search its public_symbols.
            # During lowering, the scope stack may not include USE'd package scopes,
            # so types like C3900010.Alert_Type can't be found by regular lookup.
            prefix_name = None
            if isinstance(type_node.prefix, Identifier):
                prefix_name = type_node.prefix.name.lower()
            elif isinstance(type_node.prefix, SelectedName):
                prefix_name = self._get_hierarchical_name(type_node.prefix).lower()
            if prefix_name:
                scope = self.symbols.current_scope
                while scope is not None:
                    pkg_sym = scope.lookup_local(prefix_name)
                    if pkg_sym and hasattr(pkg_sym, 'public_symbols') and pkg_sym.public_symbols:
                        type_sym = pkg_sym.public_symbols.get(selector)
                        if type_sym and type_sym.ada_type:
                            return type_sym.ada_type
                    scope = scope.parent
                # Fallback: search AST declarations for the package type
                decl_lists = []
                if hasattr(self, '_current_body_declarations') and self._current_body_declarations:
                    decl_lists.append(self._current_body_declarations)
                if hasattr(self, '_body_declarations_stack'):
                    for dl in reversed(self._body_declarations_stack):
                        if dl not in decl_lists:
                            decl_lists.append(dl)
                from uada80.ast_nodes import EnumerationTypeDef as _EnumTD
                for dl in decl_lists:
                    for d in dl:
                        if isinstance(d, PackageDecl) and d.name and d.name.lower() == prefix_name:
                            all_pkg_decls = list(d.declarations) + list(getattr(d, 'private_declarations', []) or [])
                            for pkg_decl in all_pkg_decls:
                                if isinstance(pkg_decl, TypeDecl) and pkg_decl.name.lower() == selector:
                                    if isinstance(pkg_decl.type_def, _EnumTD) and pkg_decl.type_def.literals:
                                        return EnumerationType(
                                            name=pkg_decl.name,
                                            size_bits=16,
                                            literals=pkg_decl.type_def.literals,
                                        )
                                    # For non-enum types, just return None (no need to create type obj)
                                    return None
                            break
            return None
        # If it's an Identifier, look up the type name
        if isinstance(type_node, Identifier):
            type_name = type_node.name.lower()
            # First check symbol table
            sym = self.symbols.lookup(type_node.name)
            if sym and sym.ada_type:
                return sym.ada_type
            # Check local type/subtype declarations from current body and stack
            all_decl_lists = []
            if hasattr(self, '_current_body_declarations') and self._current_body_declarations:
                all_decl_lists.append(self._current_body_declarations)
            if hasattr(self, '_body_declarations_stack'):
                for decl_list in self._body_declarations_stack:
                    if decl_list not in all_decl_lists:
                        all_decl_lists.append(decl_list)
            for decl_list in all_decl_lists:
                from uada80.ast_nodes import ModularTypeDef, RecordTypeDef
                from uada80.type_system import RecordType, RecordComponent, IntegerType
                for d in decl_list:
                    # Handle subtype declarations (e.g., subtype Short is Integer range ...)
                    if isinstance(d, SubtypeDecl) and d.name.lower() == type_name:
                        if d.ada_type:
                            return d.ada_type
                        continue
                    if isinstance(d, TypeDecl) and d.name.lower() == type_name:
                        # Prefer ada_type set by semantic analysis (has correct bounds, etc.)
                        if d.ada_type:
                            return d.ada_type
                        type_def = d.type_def
                        # Handle modular type definition
                        if isinstance(type_def, ModularTypeDef):
                            modulus = self._eval_static_expr(type_def.modulus)
                            return ModularType(name=d.name, modulus=modulus)
                        # Handle record type definition
                        elif isinstance(type_def, RecordTypeDef):
                            components = []
                            offset = 0
                            for comp_decl in type_def.components:
                                # Resolve the actual component type
                                comp_type = self._resolve_local_type(comp_decl.type_mark)
                                if comp_type is None:
                                    comp_type = IntegerType(name="Integer", size_bits=16)
                                comp_size = (comp_type.size_bits + 7) // 8 if comp_type.size_bits else 2
                                for comp_name in comp_decl.names:
                                    components.append(RecordComponent(
                                        name=comp_name,
                                        component_type=comp_type,
                                        offset_bits=offset * 8,
                                        size_bits=comp_type.size_bits if comp_type.size_bits else 16,
                                    ))
                                    offset += comp_size
                            return RecordType(
                                name=type_name,
                                components=components,
                                size_bits=offset * 8,
                            )
                        # Handle array type definition
                        elif isinstance(type_def, ArrayTypeDef):
                            from uada80.type_system import ArrayType, IntegerType
                            bounds = []
                            is_unconstrained = False
                            has_dynamic_bounds = False
                            if type_def.index_subtypes:
                                idx_range = type_def.index_subtypes[0]
                                low, high = self._extract_index_bounds(idx_range)
                                if low is not None and high is not None:
                                    bounds.append((low, high))
                                elif low is None and high is None:
                                    if isinstance(idx_range, SubtypeIndication):
                                        # Check if it's an unconstrained array (has BoxConstraint)
                                        from uada80.ast_nodes import BoxConstraint
                                        if isinstance(idx_range.constraint, BoxConstraint):
                                            is_unconstrained = True
                                        elif idx_range.constraint is None:
                                            # SubtypeIndication with no constraint = unconstrained
                                            has_dynamic_bounds = True
                                    else:
                                        has_dynamic_bounds = True
                            # Resolve component type
                            comp_type = IntegerType(name="Integer", size_bits=16)
                            if type_def.component_type:
                                if isinstance(type_def.component_type, Identifier):
                                    comp_name = type_def.component_type.name.lower()
                                    if comp_name == "integer":
                                        comp_type = IntegerType(name="Integer", size_bits=16)
                            return ArrayType(
                                name=type_name,
                                component_type=comp_type,
                                bounds=bounds if bounds and not has_dynamic_bounds else None,
                                is_constrained=not is_unconstrained and bool(bounds) and not has_dynamic_bounds,
                            )
            # Search inside PackageDecl declarations for types made visible via use clauses.
            # When a type like LPRIV0 is declared inside PACKAGE P and "use P" is active,
            # the type may not be in the symbol table during lowering. Search the package
            # spec's public and private declarations in the declaration stack.
            # Prefer private (full) type definitions over public (incomplete) stubs.
            for decl_list in all_decl_lists:
                for d in decl_list:
                    if isinstance(d, PackageDecl):
                        found_type = None
                        # Search public declarations first
                        for pkg_decl in (d.declarations or []):
                            if isinstance(pkg_decl, TypeDecl) and pkg_decl.name.lower() == type_name:
                                if pkg_decl.ada_type:
                                    found_type = pkg_decl.ada_type
                            if isinstance(pkg_decl, SubtypeDecl) and pkg_decl.name.lower() == type_name:
                                if hasattr(pkg_decl, 'ada_type') and pkg_decl.ada_type:
                                    found_type = pkg_decl.ada_type
                        # Search private declarations (prefer full type over incomplete)
                        for pkg_decl in (d.private_declarations or []):
                            if isinstance(pkg_decl, TypeDecl) and pkg_decl.name.lower() == type_name:
                                if pkg_decl.ada_type and pkg_decl.ada_type.size_bits > 0:
                                    found_type = pkg_decl.ada_type
                            if isinstance(pkg_decl, SubtypeDecl) and pkg_decl.name.lower() == type_name:
                                if hasattr(pkg_decl, 'ada_type') and pkg_decl.ada_type and pkg_decl.ada_type.size_bits > 0:
                                    found_type = pkg_decl.ada_type
                        if found_type is not None:
                            return found_type

            # Fallback: search enclosing package's public_symbols via _package_prefix_stack.
            # When lowering a package body, types declared in the package spec aren't in
            # _body_declarations_stack or the lowering-time scope. Look them up via the
            # package symbol's public_symbols.
            if hasattr(self, '_package_prefix_stack'):
                for pkg_name in reversed(self._package_prefix_stack):
                    pkg_sym = self.symbols.lookup(pkg_name)
                    if pkg_sym and hasattr(pkg_sym, 'public_symbols') and pkg_sym.public_symbols:
                        type_sym = pkg_sym.public_symbols.get(type_name)
                        if type_sym and type_sym.ada_type:
                            return type_sym.ada_type
        # If it's a SubtypeIndication, get the type_mark and apply constraints
        if isinstance(type_node, SubtypeIndication):
            base_type = None
            if type_node.type_mark:
                base_type = self._resolve_local_type(type_node.type_mark)
            # Apply index constraint if present (for arrays like Arr(1..2))
            if type_node.constraint and isinstance(type_node.constraint, IndexConstraint):
                if base_type and isinstance(base_type, ArrayType):
                    # Extract bounds from constraint
                    bounds = []
                    for rng in type_node.constraint.ranges:
                        if isinstance(rng, RangeExpr):
                            low = self._eval_static_expr(rng.low)
                            high = self._eval_static_expr(rng.high)
                            if low is not None and high is not None:
                                bounds.append((low, high))
                    if bounds:
                        # Create constrained array type
                        return ArrayType(
                            name=base_type.name,
                            kind=base_type.kind,
                            size_bits=sum((h - l + 1) for l, h in bounds) * (base_type.component_type.size_bits if base_type.component_type else 16),
                            component_type=base_type.component_type,
                            bounds=bounds,
                            is_constrained=True,
                        )
            return base_type
        # Handle Slice (constrained subtype like String(1..5))
        if isinstance(type_node, Slice):
            base_type = self._resolve_local_type(type_node.prefix)
            if isinstance(base_type, ArrayType) and not base_type.is_constrained:
                # Extract bounds from the range expression
                if isinstance(type_node.range_expr, RangeExpr):
                    low = self._eval_static_expr(type_node.range_expr.low)
                    high = self._eval_static_expr(type_node.range_expr.high)
                    if low is not None and high is not None:
                        return ArrayType(
                            name=f"{base_type.name}({low}..{high})",
                            kind=base_type.kind,
                            size_bits=(high - low + 1) * (base_type.component_type.size_bits if base_type.component_type else 8),
                            component_type=base_type.component_type,
                            index_types=base_type.index_types if hasattr(base_type, 'index_types') else None,
                            bounds=[(low, high)],
                            is_constrained=True,
                            base_type=base_type,
                        )
            return base_type
        # Handle IndexedComponent as discriminant-constrained type, e.g. R(4)
        # The parser treats "R(4)" as IndexedComponent(prefix=Identifier('R'), indices=[4])
        # but in type context this is a discriminant constraint, not array indexing.
        if isinstance(type_node, IndexedComponent):
            return self._resolve_local_type(type_node.prefix)
        return None

    def _get_array_bounds_from_expr(self, expr) -> Optional[list[tuple[int, int]]]:
        """Get array bounds from an expression (variable name).

        Returns a list of (low, high) tuples for each dimension, or None if not found.
        """
        from uada80.type_system import ArrayType

        if not isinstance(expr, Identifier):
            return None

        var_name = expr.name.lower()

        # Check local variables
        if self.ctx and var_name in self.ctx.locals:
            local = self.ctx.locals[var_name]
            ada_type = self._resolve_local_type(local.ada_type)
            if isinstance(ada_type, ArrayType) and ada_type.bounds:
                return ada_type.bounds

        # Check global symbol table
        sym = self.symbols.lookup(expr.name)
        if sym and sym.ada_type:
            if isinstance(sym.ada_type, ArrayType) and sym.ada_type.bounds:
                return sym.ada_type.bounds

        return None

    def _lower_function_call(self, expr: FunctionCall):
        """Lower a function call expression."""
        result = self.builder.new_vreg(IRType.WORD, "_result")

        # Check for intrinsic functions
        func_name = ""
        if isinstance(expr.name, Identifier):
            func_name = expr.name.name.lower()
        elif isinstance(expr.name, SelectedName):
            func_name = expr.name.selector.lower()

        # Check for generic formal subprogram substitution
        # If we're inside a generic instantiation and the called name is a formal function,
        # replace it with the actual function
        if self._generic_type_map:
            subp_key = f"_subp_{func_name}"
            if subp_key in self._generic_type_map:
                # This is a call to a generic formal function - substitute the actual
                actual_name = self._generic_type_map[subp_key]
                func_name = actual_name.lower()
                # Update expr.name to point to actual function
                expr = FunctionCall(
                    name=Identifier(actual_name),
                    args=expr.args
                )
            elif func_name in self._generic_type_map:
                # Generic formal type/object used in an expression.
                # If the "call" has arguments (e.g., T(IDENT_INT(2))), this
                # is a type conversion to the formal type — lower the
                # argument and apply the conversion.  If no arguments, it's
                # a reference to a generic formal object — just return its
                # value.
                actual = self._generic_type_map[func_name]
                if expr.args:
                    # Type conversion: T(expr) -> QT(expr) — lower the argument
                    arg_expr = expr.args[0].value if hasattr(expr.args[0], 'value') else expr.args[0]
                    return self._lower_expr(arg_expr)
                else:
                    if isinstance(actual, str):
                        return self._lower_identifier(Identifier(name=actual))
                    else:
                        return self._lower_expr(actual)

        # Check if this is an internal function call within a protected body
        prot_body_name = getattr(self, '_current_protected_body_name', None)
        prot_body_ops = getattr(self, '_current_protected_body_ops', set())
        if prot_body_name and isinstance(expr.name, Identifier) and func_name in prot_body_ops:
            qualified_name = f"{prot_body_name.lower()}_{func_name}"
            # Push arguments
            if expr.args:
                for arg in reversed(expr.args):
                    arg_expr = arg.value if hasattr(arg, 'value') else arg
                    val = self._lower_expr(arg_expr)
                    self.builder.push(val)
            # Push protected object pointer
            prot_obj = getattr(self.ctx, 'protected_obj_ptr', None)
            if prot_obj:
                self.builder.push(prot_obj)
            else:
                zero = self.builder.new_vreg(IRType.WORD, "_zero")
                self.builder.mov(zero, Immediate(0, IRType.WORD))
                self.builder.push(zero)
            self.builder.call(Label(qualified_name), comment=f"internal protected call {func_name}")
            # Get return value from HL
            self.builder.emit(IRInstr(
                OpCode.MOV, result,
                MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
            ))
            num_args = (len(expr.args) if expr.args else 0) + 1
            for _ in range(num_args):
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
            return result

        # Check for Unchecked_Conversion instantiation call
        sym = self.symbols.lookup(func_name)
        if sym and sym.is_unchecked_conversion and len(expr.args) >= 1:
            # Unchecked_Conversion just returns the bit pattern unchanged
            return self._lower_expr(expr.args[0].value)

        # Handle Shift_Left intrinsic
        if func_name == "shift_left" and len(expr.args) >= 2:
            value = self._lower_expr(expr.args[0].value)
            amount = self._lower_expr(expr.args[1].value)
            self.builder.emit(IRInstr(OpCode.SHL, result, value, amount,
                                      comment="Shift_Left"))
            return result

        # Handle Shift_Right intrinsic
        if func_name == "shift_right" and len(expr.args) >= 2:
            value = self._lower_expr(expr.args[0].value)
            amount = self._lower_expr(expr.args[1].value)
            self.builder.emit(IRInstr(OpCode.SHR, result, value, amount,
                                      comment="Shift_Right"))
            return result

        # Handle Rotate_Left intrinsic
        if func_name == "rotate_left" and len(expr.args) >= 2:
            # For 16-bit: rotate left by N = (value << N) | (value >> (16 - N))
            value = self._lower_expr(expr.args[0].value)
            amount = self._lower_expr(expr.args[1].value)

            # Shift left part: value << amount
            left_part = self.builder.new_vreg(IRType.WORD, "_rol_left")
            self.builder.emit(IRInstr(OpCode.SHL, left_part, value, amount,
                                      comment="Rotate_Left: value << N"))

            # Calculate (16 - amount) for right shift
            complement = self.builder.new_vreg(IRType.WORD, "_rol_comp")
            self.builder.emit(IRInstr(OpCode.SUB, complement,
                                      Immediate(16, IRType.WORD), amount,
                                      comment="16 - N for wrap-around"))

            # Shift right part: value >> (16 - amount)
            right_part = self.builder.new_vreg(IRType.WORD, "_rol_right")
            self.builder.emit(IRInstr(OpCode.SHR, right_part, value, complement,
                                      comment="Rotate_Left: value >> (16-N)"))

            # Combine: result = left_part | right_part
            self.builder.emit(IRInstr(OpCode.OR, result, left_part, right_part,
                                      comment="Rotate_Left: combine parts"))
            return result

        # Handle Rotate_Right intrinsic
        if func_name == "rotate_right" and len(expr.args) >= 2:
            # For 16-bit: rotate right by N = (value >> N) | (value << (16 - N))
            value = self._lower_expr(expr.args[0].value)
            amount = self._lower_expr(expr.args[1].value)

            # Shift right part: value >> amount
            right_part = self.builder.new_vreg(IRType.WORD, "_ror_right")
            self.builder.emit(IRInstr(OpCode.SHR, right_part, value, amount,
                                      comment="Rotate_Right: value >> N"))

            # Calculate (16 - amount) for left shift
            complement = self.builder.new_vreg(IRType.WORD, "_ror_comp")
            self.builder.emit(IRInstr(OpCode.SUB, complement,
                                      Immediate(16, IRType.WORD), amount,
                                      comment="16 - N for wrap-around"))

            # Shift left part: value << (16 - amount)
            left_part = self.builder.new_vreg(IRType.WORD, "_ror_left")
            self.builder.emit(IRInstr(OpCode.SHL, left_part, value, complement,
                                      comment="Rotate_Right: value << (16-N)"))

            # Combine: result = right_part | left_part
            self.builder.emit(IRInstr(OpCode.OR, result, right_part, left_part,
                                      comment="Rotate_Right: combine parts"))
            return result

        # Handle Ada.Numerics.Elementary_Functions.Sqrt for Float64
        if func_name == "sqrt" and len(expr.args) >= 1:
            arg_type = self._get_expr_type(expr.args[0].value)
            if self._is_float64_type(arg_type):
                # Float64 sqrt - call _f64_sqrt
                return self._lower_float64_sqrt(expr.args[0].value)
            # If arg type unknown but function is from Elementary_Functions, assume Float64
            if arg_type is None or (hasattr(arg_type, '__class__') and arg_type.__class__.__name__ == 'FloatType'):
                # Check if called from Elementary_Functions package
                is_elem_func = False
                if isinstance(expr.name, SelectedName):
                    # Package-qualified: Ada.Numerics.Elementary_Functions.Sqrt
                    is_elem_func = True
                elif sym and hasattr(sym, 'package_name') and sym.package_name and 'elementary' in sym.package_name.lower():
                    is_elem_func = True
                else:
                    # Could be via use clause — check if there's a sqrt in scope from Elementary_Functions
                    sqrt_sym = self.symbols.lookup("sqrt")
                    if sqrt_sym and hasattr(sqrt_sym, 'package_name') and sqrt_sym.package_name and 'elementary' in sqrt_sym.package_name.lower():
                        is_elem_func = True
                    elif sqrt_sym is None:
                        # No user-defined sqrt — assume it's Elementary_Functions
                        is_elem_func = True
                if is_elem_func:
                    return self._lower_float64_sqrt(expr.args[0].value)

        # Check if this is a protected type function call (Counter.Value)
        if isinstance(expr.name, SelectedName):
            prefix = expr.name.prefix
            selector = expr.name.selector

            prot_type, prefix_name = self._resolve_protected_prefix(prefix, selector)

            if prot_type:
                    prot_type_name = (prot_type.name if hasattr(prot_type, 'name') else prefix_name).lower()
                    func_label = f"{prot_type_name}_{selector.lower()}"

                    self._push_protected_obj_addr(prefix, prefix_name)

                    # Push any additional arguments
                    if expr.args:
                        for arg in reversed(expr.args):
                            val = self._lower_expr(arg.value if hasattr(arg, 'value') else arg)
                            self.builder.push(val)

                    # Call the protected function
                    self.builder.call(Label(func_label), comment=f"call protected function {selector}")

                    # Capture result from HL
                    self.builder.emit(IRInstr(
                        OpCode.MOV, result,
                        MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                        comment="capture protected function return from HL"
                    ))

                    # Clean up stack
                    num_args = (len(expr.args) if expr.args else 0) + 1  # +1 for protected object
                    for _ in range(num_args):
                        temp = self.builder.new_vreg(IRType.WORD, "_discard")
                        self.builder.pop(temp)

                    return result
            if not prot_type and isinstance(prefix, Identifier):
                prefix_name = prefix.name.lower()
                # Check if this is actually a record array field access (not a function call)
                # e.g., Old.List(I) where Old is access-to-record and List is an array field
                from uada80.type_system import RecordType as _RecordType, ArrayType as _ArrayType, AccessType as _AccessType
                _rec_type = None
                _local = self._find_local(prefix_name)
                if _local and _local.ada_type:
                    _rec_type = self._resolve_local_type(_local.ada_type)
                if _rec_type is None and self.ctx and prefix_name in self.ctx.param_ada_types:
                    _rec_type = self.ctx.param_ada_types[prefix_name]
                if _rec_type is None:
                    _sym = self.symbols.lookup(prefix_name) if self.symbols else None
                    if _sym and _sym.ada_type:
                        _rec_type = _sym.ada_type
                # Fallback: use _get_prefix_type which handles package-prefixed locals
                if _rec_type is None:
                    _rec_type = self._get_prefix_type(prefix)
                # Fallback: if local found but type unresolved, search AST declarations
                # for the type name (handles nested package body types)
                if _rec_type is None and _local and _local.ada_type:
                    _sti = _local.ada_type
                    if isinstance(_sti, SubtypeIndication) and _sti.type_mark:
                        _type_name = None
                        if isinstance(_sti.type_mark, Identifier):
                            _type_name = _sti.type_mark.name.lower()
                        if _type_name:
                            from uada80.ast_nodes import TypeDecl as _TD, PackageDecl as _PD, PackageBody as _PB
                            _all_decls = list(getattr(self, '_current_body_declarations', None) or [])
                            for _dl in getattr(self, '_body_declarations_stack', []):
                                _all_decls.extend(_dl)
                            for _d in _all_decls:
                                if isinstance(_d, _TD) and _d.name.lower() == _type_name and _d.ada_type:
                                    _rec_type = _d.ada_type
                                    break
                                if isinstance(_d, (_PD, _PB)):
                                    for _sd in list(getattr(_d, 'declarations', [])) + list(getattr(_d, 'private_declarations', None) or []):
                                        if isinstance(_sd, _TD) and _sd.name.lower() == _type_name and _sd.ada_type:
                                            _rec_type = _sd.ada_type
                                            break
                                    if _rec_type is not None:
                                        break
                # Follow implicit dereference for access types
                if isinstance(_rec_type, _AccessType) and _rec_type.designated_type:
                    _rec_type = _rec_type.designated_type
                if isinstance(_rec_type, _RecordType):
                    for _comp in _rec_type.components:
                        _ctype = _comp.component_type
                        # Follow access type to designated type for access-to-array fields
                        if isinstance(_ctype, _AccessType) and _ctype.designated_type:
                            _ctype = _ctype.designated_type
                        if _comp.name.lower() == selector.lower() and isinstance(_ctype, _ArrayType):
                            # This is record.array_field(index) — redirect to _lower_indexed
                            from uada80.ast_nodes import IndexedComponent as _IC
                            indexed_expr = _IC(prefix=expr.name, indices=list(
                                a.value if hasattr(a, 'value') else a for a in expr.args
                            ))
                            return self._lower_indexed(indexed_expr)

                # Check if this is a call through an access-to-subprogram record field
                # e.g., RO_4.C(4.5) where C is a record component of access-to-function type
                if isinstance(_rec_type, _RecordType):
                    from uada80.type_system import AccessSubprogramType as _AST_func
                    _as_comp = _rec_type.get_component(selector)
                    if _as_comp and isinstance(_as_comp.component_type, _AST_func):
                        # Load the access-to-subprogram value from the record field
                        func_ptr = self._lower_expr(expr.name)
                        # Indirect call through the function pointer
                        # Push arguments (right to left)
                        stack_slots = 0
                        if expr.args:
                            for arg in reversed(expr.args):
                                val = self._lower_expr(arg.value if hasattr(arg, 'value') else arg)
                                self.builder.push(val)
                                stack_slots += 1
                        self.builder.emit(IRInstr(
                            OpCode.CALL_INDIRECT,
                            src1=func_ptr,
                            comment=f"indirect func call via {prefix_name}.{selector}"
                        ))
                        for _ in range(stack_slots):
                            temp = self.builder.new_vreg(IRType.WORD, "_discard")
                            self.builder.pop(temp)
                        # Capture result from HL
                        self.builder.emit(IRInstr(
                            OpCode.MOV, result,
                            MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                            comment=f"capture indirect call return from {prefix_name}.{selector}"
                        ))
                        return result

                # Not a protected type - this is a package-qualified function call
                    # Check if this is a predefined operator that should use inline code
                    # (e.g., P."="(X, Y) for scalar types)
                    # Map of predefined binary operators
                    _predefined_binary_map = {
                        '"="': BinaryOp.EQ, '=': BinaryOp.EQ,
                        '"/="': BinaryOp.NE, '/=': BinaryOp.NE,
                        '"<"': BinaryOp.LT, '<': BinaryOp.LT,
                        '"<="': BinaryOp.LE, '<=': BinaryOp.LE,
                        '">"': BinaryOp.GT, '>': BinaryOp.GT,
                        '">="': BinaryOp.GE, '>=': BinaryOp.GE,
                        '"+"': BinaryOp.ADD, '+': BinaryOp.ADD,
                        '"-"': BinaryOp.SUB, '-': BinaryOp.SUB,
                        '"*"': BinaryOp.MUL, '*': BinaryOp.MUL,
                        '"/"': BinaryOp.DIV, '/': BinaryOp.DIV,
                        '"mod"': BinaryOp.MOD, 'mod': BinaryOp.MOD,
                        '"rem"': BinaryOp.REM, 'rem': BinaryOp.REM,
                        '"**"': BinaryOp.EXP, '**': BinaryOp.EXP,
                        '"and"': BinaryOp.AND, 'and': BinaryOp.AND,
                        '"or"': BinaryOp.OR, 'or': BinaryOp.OR,
                        '"xor"': BinaryOp.XOR, 'xor': BinaryOp.XOR,
                        '"&"': BinaryOp.CONCAT, '&': BinaryOp.CONCAT,
                    }
                    # Map of predefined unary operators
                    _predefined_unary_map = {
                        '"not"': UnaryOp.NOT, 'not': UnaryOp.NOT,
                        '"abs"': UnaryOp.ABS, 'abs': UnaryOp.ABS,
                        '"+"': UnaryOp.PLUS, '+': UnaryOp.PLUS,
                        '"-"': UnaryOp.MINUS, '-': UnaryOp.MINUS,
                    }
                    sel_lower = selector.lower()

                    def _has_operator_body(sel, args):
                        """Check if there's a real user-defined body for this operator."""
                        sym = self._resolve_overload(sel, args)
                        if sym:
                            sym_def = getattr(sym, 'definition', None)
                            if isinstance(sym_def, SubprogramBody):
                                return True
                            mangled = self._mangle_operator_name(sym.name.lower())
                            if mangled in self._nested_subprogram_labels:
                                return True
                        return False

                    # Handle binary operators (2 args)
                    binary_op = _predefined_binary_map.get(sel_lower)
                    if binary_op is not None and expr.args and len(expr.args) == 2:
                        if not _has_operator_body(selector, expr.args):
                            left_arg = expr.args[0].value if hasattr(expr.args[0], 'value') else expr.args[0]
                            right_arg = expr.args[1].value if hasattr(expr.args[1], 'value') else expr.args[1]
                            synth_expr = BinaryExpr(op=binary_op, left=left_arg, right=right_arg,
                                                     span=getattr(expr, 'span', None))
                            return self._lower_binary(synth_expr)

                    # Handle unary operators (1 arg)
                    unary_op = _predefined_unary_map.get(sel_lower)
                    if unary_op is not None and expr.args and len(expr.args) == 1:
                        if not _has_operator_body(selector, expr.args):
                            operand = expr.args[0].value if hasattr(expr.args[0], 'value') else expr.args[0]
                            synth_expr = UnaryExpr(op=unary_op, operand=operand,
                                                    span=getattr(expr, 'span', None))
                            return self._lower_unary(synth_expr)

                    # Use the selector as the function name and generate a regular call
                    # Ada is case-insensitive, so normalize to lowercase
                    call_target = self._mangle_operator_name(selector.lower())
                    sym = self._resolve_overload(selector, expr.args)
                    if sym:
                        if sym.runtime_name:
                            call_target = sym.runtime_name.lower()
                        elif sym.is_imported and sym.external_name:
                            call_target = sym.external_name.lower()
                        else:
                            call_target = self._mangle_operator_name(sym.name.lower())

                    # Resolve nested subprogram labels.
                    # Try the full hierarchical name first (e.g., date_stack_number_of_elements)
                    # to handle package-qualified function calls from generic instances.
                    _fh_parts = self._get_hierarchical_name(expr.name).lower().split('.')
                    _fh_mangled = '_'.join(self._mangle_operator_name(p) for p in _fh_parts)
                    if _fh_mangled in self._nested_subprogram_labels:
                        call_target = self._nested_subprogram_labels[_fh_mangled]
                    elif call_target in self._nested_subprogram_labels:
                        call_target = self._nested_subprogram_labels[call_target]
                    else:
                        type_sig = self._get_param_type_sig_from_symbol(sym) if sym else ""
                        scope_prefix = ""
                        if self.ctx and self.ctx.subprogram_name:
                            scope_prefix = self.ctx.subprogram_name + "_"
                        label_key = (scope_prefix, call_target, type_sig)
                        if label_key in self._function_label_map:
                            call_target = self._function_label_map[label_key]
                        else:
                            label_key = ("", call_target, type_sig)
                            if label_key in self._function_label_map:
                                call_target = self._function_label_map[label_key]

                    # Push arguments in reverse order
                    stack_slots = 0
                    if expr.args:
                        for arg in reversed(expr.args):
                            val = self._lower_expr(arg.value if hasattr(arg, 'value') else arg)
                            self.builder.push(val)
                            stack_slots += 1

                    # Make the call
                    self.builder.call(Label(call_target), comment=f"call {selector}")

                    # Capture result from HL
                    self.builder.emit(IRInstr(
                        OpCode.MOV, result,
                        MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                        comment=f"capture return from {selector}"
                    ))

                    # Clean up stack
                    for _ in range(stack_slots):
                        temp = self.builder.new_vreg(IRType.WORD, "_discard")
                        self.builder.pop(temp)

                    return result
            else:
                # Multi-level SelectedName prefix (e.g., A.B.C where prefix is A.B)
                # Treat as package-qualified function call using the selector
                call_target = self._mangle_operator_name(selector.lower())
                sym = self._resolve_overload(selector, expr.args)

                # If not found in current scope, look up via package hierarchy
                if sym is None:
                    # Navigate the prefix to find the package symbol
                    pkg_name = self._get_hierarchical_name(prefix).lower()
                    pkg_sym = self.symbols.lookup(pkg_name) if self.symbols else None
                    if pkg_sym is None:
                        # Try dotted name lookup
                        parts = pkg_name.split('.')
                        pkg_sym = self.symbols.lookup(parts[0]) if self.symbols else None
                        for part in parts[1:]:
                            if pkg_sym and pkg_sym.public_symbols:
                                pkg_sym = pkg_sym.public_symbols.get(part)
                            else:
                                pkg_sym = None
                                break
                    if pkg_sym and pkg_sym.public_symbols:
                        sym = pkg_sym.public_symbols.get(selector.lower())

                if sym:
                    if sym.runtime_name:
                        call_target = sym.runtime_name.lower()
                    elif sym.is_imported and sym.external_name:
                        call_target = sym.external_name.lower()
                    else:
                        call_target = self._mangle_operator_name(sym.name.lower())

                # For imported functions, the external_name is the final target
                # (skip label resolution which would override with local labels)
                if not (sym and sym.is_imported and sym.external_name):
                    # Resolve nested subprogram labels using full hierarchical name
                    _fh_parts = self._get_hierarchical_name(expr.name).lower().split('.')
                    _fh_mangled = '_'.join(self._mangle_operator_name(p) for p in _fh_parts)
                    if _fh_mangled in self._nested_subprogram_labels:
                        call_target = self._nested_subprogram_labels[_fh_mangled]
                    elif call_target in self._nested_subprogram_labels:
                        call_target = self._nested_subprogram_labels[call_target]
                    else:
                        type_sig = self._get_param_type_sig_from_symbol(sym) if sym else ""
                        scope_prefix = ""
                        if self.ctx and self.ctx.subprogram_name:
                            scope_prefix = self.ctx.subprogram_name + "_"
                        label_key = (scope_prefix, call_target, type_sig)
                        if label_key in self._function_label_map:
                            call_target = self._function_label_map[label_key]
                        else:
                            label_key = ("", call_target, type_sig)
                            if label_key in self._function_label_map:
                                call_target = self._function_label_map[label_key]

                # Push arguments in reverse order
                stack_slots = 0
                if expr.args:
                    for arg in reversed(expr.args):
                        val = self._lower_expr(arg.value if hasattr(arg, 'value') else arg)
                        self.builder.push(val)
                        stack_slots += 1

                # Make the call
                self.builder.call(Label(call_target), comment=f"call {selector}")

                # Capture result from HL
                self.builder.emit(IRInstr(
                    OpCode.MOV, result,
                    MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                    comment=f"capture return from {selector}"
                ))

                # Clean up stack
                for _ in range(stack_slots):
                    temp = self.builder.new_vreg(IRType.WORD, "_discard")
                    self.builder.pop(temp)

                return result

        if isinstance(expr.name, Identifier):
            # Check for access-to-subprogram variable BEFORE overload resolution
            # (parameters/variables won't be found by _resolve_overload)
            func_name_lower = expr.name.name.lower()
            is_access_func = False

            # Check local parameters first
            if self.ctx and func_name_lower in self.ctx.param_types:
                type_name = self.ctx.param_types[func_name_lower]
                type_sym = self.symbols.lookup(type_name)
                if type_sym and type_sym.ada_type:
                    from uada80.type_system import AccessSubprogramType
                    if isinstance(type_sym.ada_type, AccessSubprogramType):
                        is_access_func = True
                # Fallback: check param_ada_types directly (handles generic instantiation types)
                if not is_access_func and self.ctx and func_name_lower in self.ctx.param_ada_types:
                    from uada80.type_system import AccessSubprogramType
                    param_ada_type = self.ctx.param_ada_types[func_name_lower]
                    if isinstance(param_ada_type, AccessSubprogramType):
                        is_access_func = True
            # Check locals
            if not is_access_func and self.ctx and func_name_lower in self.ctx.locals:
                local_info = self.ctx.locals[func_name_lower]
                if local_info.ada_type:
                    from uada80.type_system import AccessSubprogramType, AccessType
                    if isinstance(local_info.ada_type, AccessSubprogramType):
                        is_access_func = True
                    elif isinstance(local_info.ada_type, AccessType) and getattr(local_info.ada_type, 'is_access_subprogram', False):
                        is_access_func = True
            # Check symbol table
            if not is_access_func:
                direct_sym = self.symbols.lookup(expr.name.name)
                if direct_sym and direct_sym.ada_type:
                    from uada80.type_system import AccessSubprogramType, AccessType
                    if isinstance(direct_sym.ada_type, AccessSubprogramType):
                        is_access_func = True
                    elif isinstance(direct_sym.ada_type, AccessType) and getattr(direct_sym.ada_type, 'is_access_subprogram', False):
                        is_access_func = True

            if is_access_func:
                return self._lower_indirect_call(expr, None)

            # Check if this is a predefined operator call like "**"(X, Y)
            # (same operator dispatch as SelectedName branch)
            _predefined_binary_map_id = {
                '"="': BinaryOp.EQ, '"/="': BinaryOp.NE,
                '"<"': BinaryOp.LT, '"<="': BinaryOp.LE,
                '">"': BinaryOp.GT, '">="': BinaryOp.GE,
                '"+"': BinaryOp.ADD, '"-"': BinaryOp.SUB,
                '"*"': BinaryOp.MUL, '"/"': BinaryOp.DIV,
                '"mod"': BinaryOp.MOD, '"rem"': BinaryOp.REM,
                '"**"': BinaryOp.EXP,
                '"and"': BinaryOp.AND, '"or"': BinaryOp.OR,
                '"xor"': BinaryOp.XOR, '"&"': BinaryOp.CONCAT,
            }
            _predefined_unary_map_id = {
                '"not"': UnaryOp.NOT, '"abs"': UnaryOp.ABS,
                '"+"': UnaryOp.PLUS, '"-"': UnaryOp.MINUS,
            }
            op_key = func_name_lower
            # Check binary operators (2 args)
            binary_op = _predefined_binary_map_id.get(op_key)
            if binary_op is not None and expr.args and len(expr.args) == 2:
                # Check if there's a user-defined body for this operator
                op_sym = self._resolve_overload(expr.name.name, expr.args)
                has_body = False
                if op_sym:
                    op_def = getattr(op_sym, 'definition', None)
                    if isinstance(op_def, SubprogramBody):
                        has_body = True
                    op_mangled = self._mangle_operator_name(op_sym.name.lower())
                    if op_mangled in self._nested_subprogram_labels:
                        has_body = True
                if not has_body:
                    left_arg = expr.args[0].value if hasattr(expr.args[0], 'value') else expr.args[0]
                    right_arg = expr.args[1].value if hasattr(expr.args[1], 'value') else expr.args[1]
                    synth_expr = BinaryExpr(op=binary_op, left=left_arg, right=right_arg,
                                             span=getattr(expr, 'span', None))
                    return self._lower_binary(synth_expr)
            # Check unary operators (1 arg)
            unary_op = _predefined_unary_map_id.get(op_key)
            if unary_op is not None and expr.args and len(expr.args) == 1:
                op_sym = self._resolve_overload(expr.name.name, expr.args)
                has_body = False
                if op_sym:
                    op_def = getattr(op_sym, 'definition', None)
                    if isinstance(op_def, SubprogramBody):
                        has_body = True
                    op_mangled = self._mangle_operator_name(op_sym.name.lower())
                    if op_mangled in self._nested_subprogram_labels:
                        has_body = True
                if not has_body:
                    operand = expr.args[0].value if hasattr(expr.args[0], 'value') else expr.args[0]
                    synth_expr = UnaryExpr(op=unary_op, operand=operand,
                                            span=getattr(expr, 'span', None))
                    return self._lower_unary(synth_expr)

            # Resolve overloaded function
            # Use resolved_symbol from semantic analysis if available (overload resolution)
            sym = getattr(expr.name, 'resolved_symbol', None)
            if sym is None:
                sym = self._resolve_overload(expr.name.name, expr.args)
            # Fallback: search package public_symbols for child subprograms
            # Only match symbols that are child subprogram units (name contains '.')
            if sym is None:
                sym = self.symbols.lookup(expr.name.name)
            if sym is None:
                func_name_search = expr.name.name.lower()
                scope = self.symbols.current_scope
                while scope is not None and sym is None:
                    for sym_entry in scope.symbols.values():
                        if sym_entry.kind == SymbolKind.PACKAGE and sym_entry.public_symbols:
                            child = sym_entry.public_symbols.get(func_name_search)
                            if (child and child.kind in (SymbolKind.PROCEDURE, SymbolKind.FUNCTION)
                                    and '.' in child.name):
                                sym = child
                                break
                    scope = scope.parent

            # Determine the call target - use external name if imported
            # or runtime_name for built-in container operations
            # Ada is case-insensitive, so normalize to lowercase for consistent linking
            call_target = self._mangle_operator_name(expr.name.name.lower()).replace('.', '_')
            if sym:
                if sym.runtime_name:
                    # Built-in container/library operation
                    call_target = sym.runtime_name.lower()
                elif sym.is_imported and sym.external_name:
                    call_target = sym.external_name.lower()
                elif '.' in sym.name:
                    # Try full hierarchical name first (for child units),
                    # fall back to last component (for USE'd symbols)
                    full_name = self._mangle_operator_name(sym.name.lower()).replace('.', '_')
                    simple_name = sym.name.split('.')[-1].lower()
                    full_is_known = (
                        full_name in self._nested_subprogram_labels or
                        any(k[1] == full_name for k in self._function_label_map) or
                        (self.builder.module and any(
                            f.name.lower() == full_name for f in self.builder.module.functions
                        ))
                    )
                    if full_is_known:
                        call_target = full_name
                    else:
                        call_target = self._mangle_operator_name(simple_name)
                else:
                    call_target = self._mangle_operator_name(sym.name.lower()).replace('.', '_')

            # For inherited primitives (derived type operations), resolve
            # the call to the *original* parent function's label.  The
            # name-based lookup in _nested_subprogram_labels can return
            # the wrong label when a homographic explicit declaration in a
            # sibling scope overwrote the mapping.  Using the original
            # symbol's type signature in _function_label_map gives us the
            # correct label regardless of what was registered later.
            _inherited_resolved = False
            if sym and getattr(sym, 'inherited_from', None):
                orig_sym = sym.inherited_from
                orig_target = self._mangle_operator_name(orig_sym.name.lower()).replace('.', '_')
                orig_type_sig = self._get_param_type_sig_from_symbol(orig_sym)
                if orig_type_sig:
                    # Search _function_label_map for the original function
                    scope_prefix = ""
                    if self.ctx and self.ctx.subprogram_name:
                        scope_prefix = self.ctx.subprogram_name + "_"
                    for _prefix in [scope_prefix, ""]:
                        label_key = (_prefix, orig_target, orig_type_sig)
                        resolved_label = self._function_label_map.get(label_key)
                        if resolved_label:
                            call_target = resolved_label
                            _inherited_resolved = True
                            break
                    # Also try enclosing scope prefixes
                    if not _inherited_resolved and self.ctx:
                        enc = getattr(self.ctx, 'enclosing_ctx', None)
                        while enc and not _inherited_resolved:
                            enc_prefix = (enc.subprogram_name + "_") if enc.subprogram_name else ""
                            if enc_prefix:
                                label_key = (enc_prefix, orig_target, orig_type_sig)
                                resolved_label = self._function_label_map.get(label_key)
                                if resolved_label:
                                    call_target = resolved_label
                                    _inherited_resolved = True
                            enc = getattr(enc, 'enclosing_ctx', None)

            # Normal overload/label resolution — skip if already resolved
            # via inherited_from above.
            if not _inherited_resolved:
                # Check for overloaded function - use unique label if available
                # Use type signature from resolved symbol to match definition
                type_sig = self._get_param_type_sig_from_symbol(sym)
                # If sym is None but we can determine argument types, build a type sig
                # from the actual argument types. This handles the case where symbol lookup
                # fails during lowering (e.g., use-visible overloaded functions from nested
                # packages) but we can still determine which overload to call.
                if not type_sig and expr.args:
                    arg_type_names = []
                    for arg in expr.args:
                        arg_expr = arg.value if hasattr(arg, 'value') else arg
                        arg_type = self._get_expr_type(arg_expr)
                        if arg_type:
                            arg_type_names.append(arg_type.name.lower())
                    if arg_type_names:
                        arg_sig = ",".join(arg_type_names)
                        # Search the function label map for entries matching this function
                        # name and argument signature. We don't know the return type, so
                        # look for any entry where the function name and param part match.
                        for key in self._function_label_map:
                            key_name = key[1]  # function name
                            key_sig = key[2]   # type signature string
                            if key_name == call_target and (key_sig.startswith(arg_sig + "->") or key_sig == arg_sig):
                                type_sig = key_sig
                                break
                generic_orig = getattr(self, '_generic_original_name', None)
                current_func_label = None
                if self.ctx and self.ctx.subprogram_name and self.builder.function:
                    current_func_label = self.builder.function.name
                # When we have a type signature, try the function label map first
                # (it handles overloaded functions correctly, unlike _nested_subprogram_labels
                # which only stores the last registered overload for each name).
                _resolved_via_label_map = False
                if type_sig and call_target in self._nested_subprogram_labels:
                    scope_prefix = ""
                    if self.ctx and self.ctx.subprogram_name:
                        scope_prefix = self.ctx.subprogram_name + "_"
                    # Try label map with scope prefix first
                    for _prefix in [scope_prefix, ""]:
                        label_key = (_prefix, call_target, type_sig)
                        resolved_label = self._function_label_map.get(label_key)
                        if resolved_label and not (generic_orig and current_func_label and resolved_label == current_func_label):
                            call_target = resolved_label
                            _resolved_via_label_map = True
                            break
                    # Also try with enclosing context scope prefixes
                    if not _resolved_via_label_map and self.ctx:
                        enc = getattr(self.ctx, 'enclosing_ctx', None)
                        while enc and not _resolved_via_label_map:
                            enc_prefix = (enc.subprogram_name + "_") if enc.subprogram_name else ""
                            if enc_prefix:
                                label_key = (enc_prefix, call_target, type_sig)
                                resolved_label = self._function_label_map.get(label_key)
                                if resolved_label and not (generic_orig and current_func_label and resolved_label == current_func_label):
                                    call_target = resolved_label
                                    _resolved_via_label_map = True
                            enc = getattr(enc, 'enclosing_ctx', None)
                    if not _resolved_via_label_map:
                        # Type sig didn't match any label map entry — fall back to nested labels
                        resolved = self._nested_subprogram_labels[call_target]
                        if not (generic_orig and current_func_label and resolved == current_func_label):
                            call_target = resolved
                elif call_target in self._nested_subprogram_labels:
                    resolved = self._nested_subprogram_labels[call_target]
                    if generic_orig and current_func_label and resolved == current_func_label:
                        pass  # Skip: would create self-recursion in generic body
                    else:
                        call_target = resolved
                else:
                    # For overloaded functions, use the full label map with type signature
                    # Try with scope prefix first (for nested calls), then without (for top-level)
                    scope_prefix = ""
                    if self.ctx and self.ctx.subprogram_name:
                        scope_prefix = self.ctx.subprogram_name + "_"
                    label_key = (scope_prefix, call_target, type_sig)
                    resolved_label = self._function_label_map.get(label_key)
                    if resolved_label and not (generic_orig and current_func_label and resolved_label == current_func_label):
                        call_target = resolved_label
                    else:
                        # Try without scope prefix (top-level or different scope)
                        label_key = ("", call_target, type_sig)
                        resolved_label = self._function_label_map.get(label_key)
                        if resolved_label and not (generic_orig and current_func_label and resolved_label == current_func_label):
                            call_target = resolved_label
                        elif self.ctx and getattr(self.ctx, 'enclosing_ctx', None):
                            # Forward reference in nested function
                            found = False
                            ctx = self.ctx
                            while ctx:
                                prefix = (ctx.subprogram_name + "_") if ctx.subprogram_name else ""
                                if prefix:
                                    candidate = f"{prefix}{call_target}"
                                    if generic_orig and current_func_label and candidate == current_func_label:
                                        ctx = getattr(ctx, 'enclosing_ctx', None)
                                        continue
                                    if any(v == candidate for v in self._nested_subprogram_labels.values()):
                                        call_target = candidate
                                        found = True
                                        break
                                    if any(v == candidate for v in self._function_label_map.values()):
                                        call_target = candidate
                                        found = True
                                        break
                                ctx = getattr(ctx, 'enclosing_ctx', None)
                            if not found:
                                enc = getattr(self.ctx, 'enclosing_ctx', None)
                                if enc and enc.subprogram_name:
                                    is_known_external = False
                                    # External package functions have no definition AST node
                                    if sym and sym.definition is None and sym.kind in (
                                        SymbolKind.FUNCTION, SymbolKind.PROCEDURE):
                                        is_known_external = True
                                    if not is_known_external and self.builder.module:
                                        for func in self.builder.module.functions:
                                            if func.name.lower() == call_target.lower():
                                                is_known_external = True
                                                break
                                    if not is_known_external:
                                        call_target = f"{enc.subprogram_name}_{call_target}"

            # Check if this is a dispatching call
            is_dispatching = self._is_dispatching_call(sym, expr.args)

            # Get parameter modes for out/in out handling
            # First try locally-tracked modes (for nested subprograms), then symbol table
            param_modes = []
            func_name_lower = func_name.lower() if func_name else call_target.lower()
            if func_name_lower in self._subprogram_param_modes:
                param_modes = self._subprogram_param_modes[func_name_lower]
            elif sym and sym.parameters:
                param_modes = [p.mode for p in sym.parameters]

            # For nested subprograms, push outer variable addresses (in reverse order)
            outer_var_slots = 0
            if func_name_lower in self._nested_outer_vars:
                outer_vars = self._nested_outer_vars[func_name_lower]
                for var_name in reversed(list(outer_vars)):
                    pushed = False
                    # If the variable is promoted to DSEG (task-shared),
                    # always pass the DSEG shadow address.
                    dseg_label = self._task_promoted_vars.get(var_name)
                    if dseg_label and self.ctx and var_name in self.ctx.locals:
                        addr = self.builder.new_vreg(IRType.PTR, f"_{var_name}_addr")
                        self.builder.lea(addr,
                            MemoryLocation(is_global=True, symbol_name=dseg_label, ir_type=IRType.PTR),
                            comment=f"addr of DSEG shadow for outer {var_name}")
                        self.builder.push(addr)
                        pushed = True
                    # If we already have this outer var as a param (forwarding in recursive calls),
                    # just push the received pointer
                    if not pushed and self.ctx:
                        outer_param_name = f"_outer_{var_name}"
                        if outer_param_name in self.ctx.params:
                            self.builder.push(self.ctx.params[outer_param_name],
                                            comment=f"forward outer {var_name}")
                            pushed = True
                    # Otherwise, get address of the outer variable from locals
                    if not pushed and self.ctx and var_name in self.ctx.locals:
                        local = self.ctx.locals[var_name]
                        addr = self.builder.new_vreg(IRType.PTR, f"_{var_name}_addr")
                        if local.size > 2:
                            # Large locals (arrays/records) use explicit frame offset
                            frame_offset = -(local.stack_offset + local.size)
                            self.builder.emit(IRInstr(
                                OpCode.LEA, addr,
                                MemoryLocation(offset=frame_offset, ir_type=IRType.PTR, is_frame_offset=True),
                                comment=f"addr of outer {var_name}"
                            ))
                        else:
                            self.builder.emit(IRInstr(
                                OpCode.LEA, addr,
                                MemoryLocation(ir_type=IRType.PTR, addr_vreg=local.vreg),
                                comment=f"addr of outer {var_name}"
                            ))
                        self.builder.push(addr)
                    if pushed or (self.ctx and var_name in self.ctx.locals):
                        outer_var_slots += 1

            # Build effective args in formal parameter order (handles named parameters)
            effective_exprs = self._build_effective_args(expr.args, sym, func_name_lower)

            # Get byref info for this function (includes record types)
            byref_params = []
            if func_name_lower in self._subprogram_byref_params:
                byref_params = self._subprogram_byref_params[func_name_lower]

            # Pre-lower aggregate arguments that allocate stack space
            # before the push sequence begins. This prevents stack corruption
            # when aggregate allocation (sub SP) inserts bytes between pushes.
            pre_lowered = {}
            for fwd_idx, arg_value in enumerate(effective_exprs):
                if arg_value and isinstance(arg_value, Aggregate):
                    # Lower now to allocate stack space before push sequence
                    # Set resolved_type first if needed
                    if not getattr(arg_value, 'resolved_type', None):
                        param_type = self._get_param_type(sym, fwd_idx, func_name_lower)
                        if param_type:
                            arg_value.resolved_type = param_type
                    pre_lowered[fwd_idx] = self._lower_expr(arg_value)

            # Push arguments (right to left for cdecl-style calling convention)
            # Track number of stack slots used (for cleanup)
            stack_slots = 0
            for arg_idx, arg_value in enumerate(reversed(effective_exprs)):
                if arg_value:
                    # Check if this argument is an unconstrained array
                    forward_idx = len(effective_exprs) - 1 - arg_idx
                    arg_is_unconstrained = self._is_unconstrained_array_arg(sym, forward_idx, func_name_lower)

                    # Check parameter mode for out/in out handling
                    param_mode = param_modes[forward_idx] if forward_idx < len(param_modes) else "in"

                    # Check if parameter is byref (mode or record type)
                    is_byref = byref_params[forward_idx] if forward_idx < len(byref_params) else False

                    if arg_is_unconstrained:
                        ndims = self._get_param_ndims(sym, forward_idx, func_name_lower)
                        # Use pre-lowered ptr to avoid double-lowering aggregates
                        pre_ptr = pre_lowered.get(forward_idx)
                        all_bounds = self._get_array_dope_vector_multidim(arg_value, ndims, pre_lowered_ptr=pre_ptr)
                        for dim_first, dim_last in reversed(all_bounds):
                            self.builder.push(dim_last)
                            self.builder.push(dim_first)
                        ptr_val = pre_ptr or self._lower_expr(arg_value)
                        self.builder.push(ptr_val)
                        stack_slots += 1 + 2 * len(all_bounds)
                    elif param_mode in ("out", "in out") or is_byref:
                        # For IN OUT params, check actual value against formal type BEFORE call
                        if param_mode == "in out":
                            formal_type = self._get_formal_param_type(sym, forward_idx, func_name_lower)
                            if formal_type and self._type_needs_range_check(formal_type):
                                try:
                                    check_val = self._lower_expr(arg_value)
                                    self._emit_range_check(check_val, formal_type,
                                                           f"in out param {forward_idx} before-call check")
                                except Exception:
                                    pass
                        # Pass address of the argument
                        addr = self._get_arg_address(arg_value)
                        self.builder.push(addr)
                        stack_slots += 1
                    else:
                        # Set resolved_type on aggregate args for constrained params too
                        if isinstance(arg_value, Aggregate) and not getattr(arg_value, 'resolved_type', None):
                            param_type = self._get_param_type(sym, forward_idx, func_name_lower)
                            if param_type:
                                arg_value.resolved_type = param_type
                        # Regular argument - pass by value with constraint check
                        # Use pre-lowered value for aggregates to avoid stack corruption
                        value = pre_lowered.get(forward_idx) or self._lower_expr(arg_value)
                        formal_type = self._get_formal_param_type(sym, forward_idx, func_name_lower)
                        self._emit_param_in_check(value, formal_type,
                                                  f"in param {forward_idx} constraint check")
                        self.builder.push(value)
                        stack_slots += 1

            if is_dispatching and sym and sym.vtable_slot >= 0:
                # Dispatching call - emit DISPATCH instruction
                # First argument is the controlling operand (object pointer)
                first_arg = expr.args[0].value if expr.args else None
                if first_arg:
                    obj_ptr = self._lower_expr(first_arg)
                    self.builder.emit(IRInstr(
                        OpCode.DISPATCH,
                        src1=obj_ptr,
                        src2=Immediate(sym.vtable_slot, IRType.WORD),
                        comment=f"dispatch {sym.name}"
                    ))
            elif sym and sym.is_inline and self._can_inline(sym, expr.args):
                # Inline expansion for pragma Inline functions
                self._inline_function_call(sym, expr.args, result)
                # For inline calls, result is already set - just skip normal call path
                # by returning early after cleanup
                if stack_slots > 0:
                    for _ in range(stack_slots):
                        temp = self.builder.new_vreg(IRType.WORD, "_discard")
                        self.builder.pop(temp)
                return result
            else:
                # Static call (using external name for imported functions)
                self.builder.call(Label(call_target))

            # Result is already in HL after call - capture it BEFORE cleanup
            # (cleanup uses POP HL which would destroy the return value)
            self.builder.emit(IRInstr(
                OpCode.MOV, result,
                MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                comment="capture function return from HL"
            ))

            # Clean up stack (callee may not clean up on Z80)
            total_slots = stack_slots + outer_var_slots
            if total_slots > 0:
                # Pop arguments off stack
                for _ in range(total_slots):
                    temp = self.builder.new_vreg(IRType.WORD, "_discard")
                    self.builder.pop(temp)

            # After-call constraint check for OUT/IN OUT parameters
            self._emit_param_out_checks(sym, effective_exprs, param_modes, func_name_lower)

            # Skip the duplicate MOV emission below since we already captured HL
            return result

        elif isinstance(expr.name, Dereference):
            # Explicit dereference call: Func_Ptr.all(args)
            return self._lower_indirect_call(expr, None)

        return result

    def _lower_indirect_call(self, expr: FunctionCall, sym: Optional[Symbol]):
        """Lower an indirect call through a function pointer.

        Used for access-to-subprogram types:
            type Func_Ptr is access function (X : Integer) return Integer;
            F : Func_Ptr := Some_Function'Access;
            Result := F(10);  -- indirect call
        """
        result = self.builder.new_vreg(IRType.WORD, "_indirect_result")

        # Get the function pointer value
        if isinstance(expr.name, Dereference):
            func_ptr = self._lower_expr(expr.name.prefix)
        elif isinstance(expr.name, Identifier):
            func_ptr = self._lower_expr(expr.name)
        else:
            func_ptr = self._lower_expr(expr.name)

        # Push arguments (right to left)
        for arg in reversed(expr.args):
            if arg.value:
                value = self._lower_expr(arg.value)
                self.builder.push(value)

        # Emit indirect call instruction
        self.builder.emit(IRInstr(
            OpCode.CALL_INDIRECT,
            src1=func_ptr,
            comment="indirect function call"
        ))

        # Clean up stack
        num_args = len(expr.args)
        for _ in range(num_args):
            temp = self.builder.new_vreg(IRType.WORD, "_discard")
            self.builder.pop(temp)

        # Capture result from HL
        self.builder.emit(IRInstr(
            OpCode.MOV, result,
            MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
            comment="capture indirect call return from HL"
        ))

        return result

    def _lower_indirect_proc_call_from_type(self, stmt: ProcedureCallStmt, access_type):
        """Lower an indirect procedure call through an access-to-subprogram value.

        Used for access-to-subprogram types:
            type Proc_Ptr is access procedure (X : in Float; Y : out Call_Kind);
            P : Proc_Ptr := Some_Proc'Access;
            P(Theta, Result);  -- indirect call
        """
        from uada80.type_system import AccessSubprogramType

        # Get the function pointer value
        if isinstance(stmt.name, Dereference):
            func_ptr = self._lower_expr(stmt.name.prefix)
        elif isinstance(stmt.name, Identifier):
            func_ptr = self._lower_expr(stmt.name)
        else:
            func_ptr = self._lower_expr(stmt.name)

        # Get parameter modes from the type definition AST
        # AccessSubprogramType has parameter_types (list of AdaType) but no modes.
        # Modes come from the type's definition (TypeDecl -> AccessSubprogramTypeDef)
        param_modes = []
        type_sym = self._lookup_type_symbol(access_type.name) if access_type else None
        if type_sym and type_sym.definition:
            from uada80.ast_nodes import TypeDecl, AccessSubprogramTypeDef
            typedef = type_sym.definition
            if isinstance(typedef, TypeDecl) and isinstance(typedef.type_def, AccessSubprogramTypeDef):
                for p in typedef.type_def.parameters:
                    mode = p.mode if p.mode else 'in'
                    # Each ParameterSpec may have multiple names
                    for _ in p.names:
                        param_modes.append(mode)

        # Push arguments (right to left)
        stack_slots = 0
        args = stmt.args if stmt.args else []
        for i, arg in enumerate(reversed(args)):
            forward_idx = len(args) - 1 - i
            mode = param_modes[forward_idx] if forward_idx < len(param_modes) else 'in'
            arg_expr = arg.value if hasattr(arg, 'value') and arg.value else arg

            if mode in ('out', 'in out'):
                # Pass by reference - push address
                addr = self._get_lvalue_address(arg_expr)
                self.builder.push(addr)
            else:
                value = self._lower_expr(arg_expr)
                self.builder.push(value)
            stack_slots += 1

        # Emit indirect call instruction
        self.builder.emit(IRInstr(
            OpCode.CALL_INDIRECT,
            src1=func_ptr,
            comment=f"indirect procedure call via {stmt.name.name if hasattr(stmt.name, 'name') else 'ptr'}"
        ))

        # Clean up stack
        for _ in range(stack_slots):
            temp = self.builder.new_vreg(IRType.WORD, "_discard")
            self.builder.pop(temp)

    def _lower_enum_width_dynamic(self, prefix_type):
        """Generate runtime Width computation for an enum type with dynamic range bounds.

        For each literal position i in 0..N-1, we know the Image length at compile time.
        At runtime we evaluate the dynamic first/last bounds and compute:
          if first > last then 0  (empty range)
          else max of Image_Length(i) for all i in first..last
        This is generated as inline comparisons without loops.
        """
        from uada80.ir import Immediate, IRType, Label

        cle = getattr(prefix_type, 'constraint_low_expr', None)
        che = getattr(prefix_type, 'constraint_high_expr', None)

        # Evaluate dynamic bounds (these are Pos values: 0-based enum positions)
        # The constraint expressions return Boolean values for Boolean subtypes,
        # which the IR represents as 0/1 integers (same as Pos values).
        dyn_first = self._lower_expr(cle) if cle else Immediate(0, IRType.WORD)
        dyn_last = self._lower_expr(che) if che else Immediate(len(prefix_type.literals) - 1, IRType.WORD)

        # Precompute Image lengths for each literal position
        char_lits = getattr(prefix_type, 'char_literals', set()) or set()
        image_lengths = []
        for lit in prefix_type.literals:
            if lit in char_lits:
                image_lengths.append(len(lit) + 2)  # "'X'" = 3 chars
            else:
                image_lengths.append(len(lit))

        # Result vreg
        result = self.builder.new_vreg(IRType.WORD, "_ewidth")
        self.builder.mov(result, Immediate(0, IRType.WORD))

        done_label = self._new_label("ewdn")

        # Check for empty range: if first > last, result stays 0
        empty_check = self.builder.new_vreg(IRType.BOOL, "_echk")
        self.builder.cmp_gt(empty_check, dyn_first, dyn_last)
        self.builder.jnz(empty_check, Label(done_label))

        # For each literal position, check if it's in range and update max
        # Generate: if pos >= first AND pos <= last then result = max(result, width)
        for i, img_len in enumerate(image_lengths):
            pos_imm = Immediate(i, IRType.WORD)

            # Check pos >= first
            in_lo = self.builder.new_vreg(IRType.BOOL, "_elo")
            self.builder.cmp_ge(in_lo, pos_imm, dyn_first)
            skip_label = self._new_label("ewsk")
            self.builder.jz(in_lo, Label(skip_label))

            # Check pos <= last
            in_hi = self.builder.new_vreg(IRType.BOOL, "_ehi")
            self.builder.cmp_le(in_hi, pos_imm, dyn_last)
            self.builder.jz(in_hi, Label(skip_label))

            # pos is in range: update result = max(result, img_len)
            wider = self.builder.new_vreg(IRType.BOOL, "_ewid")
            self.builder.cmp_gt(wider, Immediate(img_len, IRType.WORD), result)
            no_update_label = self._new_label("ewnu")
            self.builder.jz(wider, Label(no_update_label))
            self.builder.mov(result, Immediate(img_len, IRType.WORD))

            no_update_block = self.builder.new_block(no_update_label)
            self.builder.set_block(no_update_block)

            skip_block = self.builder.new_block(skip_label)
            self.builder.set_block(skip_block)

        done_block = self.builder.new_block(done_label)
        self.builder.set_block(done_block)

        return result

    def _lower_attribute(self, expr: AttributeReference):
        """Lower an attribute reference."""
        attr = expr.attribute.lower()

        # Handle T'BASE'attr - resolve base type first, then apply outer attribute
        if (isinstance(expr.prefix, AttributeReference) and
                expr.prefix.attribute.lower() == "base"):
            # Get the type from the inner prefix (e.g., T in T'BASE)
            inner_prefix = expr.prefix.prefix
            base_type = None
            orig_type = None  # Keep original (possibly constrained) type for Width
            if isinstance(inner_prefix, Identifier):
                sym = self.symbols.lookup(inner_prefix.name)
                if sym and sym.kind in (SymbolKind.TYPE, SymbolKind.SUBTYPE) and sym.ada_type:
                    orig_type = sym.ada_type
                    base_type = sym.ada_type
                    # Follow base_type chain to get the unconstrained base type
                    while hasattr(base_type, 'base_type') and base_type.base_type:
                        base_type = base_type.base_type
                elif sym and sym.ada_type:
                    orig_type = sym.ada_type
                    base_type = sym.ada_type
                    while hasattr(base_type, 'base_type') and base_type.base_type:
                        base_type = base_type.base_type
            if base_type is None:
                # Try resolving as a local type
                orig_type = self._resolve_local_type(inner_prefix)
                base_type = orig_type
                if base_type:
                    while hasattr(base_type, 'base_type') and base_type.base_type:
                        base_type = base_type.base_type
            if base_type is not None:
                from uada80.type_system import EnumerationType
                if attr == "size":
                    return Immediate(base_type.size_bits, IRType.WORD)
                elif attr == "first":
                    # For 'BASE, always use the base type (not the subtype)
                    attr_type = base_type
                    if isinstance(base_type, EnumerationType):
                        first_pos = getattr(attr_type, 'first', None)
                        return Immediate(first_pos if first_pos is not None else 0, IRType.WORD)
                    elif hasattr(attr_type, 'low') and attr_type.low is not None:
                        return Immediate(attr_type.low, IRType.WORD)
                    elif hasattr(base_type, 'low') and base_type.low is not None:
                        return Immediate(base_type.low, IRType.WORD)
                elif attr == "last":
                    # For 'BASE, always use the base type (not the subtype)
                    attr_type = base_type
                    if isinstance(base_type, EnumerationType) and base_type.literals:
                        last_pos = getattr(attr_type, 'last', None)
                        return Immediate(last_pos if last_pos is not None else len(base_type.literals) - 1, IRType.WORD)
                    elif hasattr(attr_type, 'high') and attr_type.high is not None:
                        return Immediate(attr_type.high, IRType.WORD)
                    elif hasattr(base_type, 'high') and base_type.high is not None:
                        return Immediate(base_type.high, IRType.WORD)
                elif attr == "width":
                    # T'Base'Width always uses the full base type range
                    width_type = base_type
                    if isinstance(base_type, EnumerationType) and base_type.literals:
                        # Check subtype range (first/last on the original type)
                        first_pos = getattr(width_type, 'first', None)
                        last_pos = getattr(width_type, 'last', None)
                        if first_pos is None:
                            first_pos = 0
                        if last_pos is None:
                            last_pos = len(base_type.literals) - 1
                        if first_pos > last_pos:
                            return Immediate(0, IRType.WORD)  # Empty range
                        max_width = 0
                        char_lits = getattr(base_type, 'char_literals', set()) or set()
                        for i in range(first_pos, min(last_pos + 1, len(base_type.literals))):
                            lit = base_type.literals[i]
                            lit_w = len(lit) + 2 if lit in char_lits else len(lit)
                            max_width = max(max_width, lit_w)
                        return Immediate(max_width, IRType.WORD)
                    elif hasattr(base_type, 'low') and hasattr(base_type, 'high'):
                        # Width = max over all V of Image(V)'Length
                        # Use the constrained type's range if available
                        low = getattr(width_type, 'low', None) or base_type.low
                        high = getattr(width_type, 'high', None) or base_type.high
                        if low is None:
                            low = 0
                        if high is None:
                            high = 0
                        if low > high:
                            return Immediate(0, IRType.WORD)  # Empty range
                        # Image of non-negative integer has leading space: " 10"
                        # Image of negative integer has leading '-': "-10"
                        # Positive side: leading space + digits
                        pos_width = len(str(max(abs(high), 0))) + 1 if high >= 0 else 0
                        # Negative side: '-' + digits
                        neg_width = len(str(abs(low))) + 1 if low < 0 else 0
                        width = max(pos_width, neg_width)
                        if width == 0:
                            width = 2  # At least " 0"
                        return Immediate(width, IRType.WORD)
                # Fallback: return 0
                return Immediate(0, IRType.WORD)

        # Handle chained attributes like T'Image(X)'Length
        # When prefix is an AttributeReference (not BASE, handled above), lower it
        # and apply the outer attribute
        if isinstance(expr.prefix, AttributeReference):
            inner_attr = expr.prefix.attribute.lower()
            if inner_attr != "base" and attr == "length":
                # T'Image(X)'Length — lower the inner attribute to get a string,
                # then get its length at runtime via _strlen
                inner_val = self._lower_attribute(expr.prefix)
                # inner_val should be a pointer to a string (from _c_img, _i2s, etc.)
                result = self.builder.new_vreg(IRType.WORD, "_attr_length")
                self.builder.push(inner_val)
                self.builder.call(Label("_str_len"), comment="string length of attribute")
                self.builder.pop(result)
                return result

        if isinstance(expr.prefix, Identifier):
            # First check local variables (higher priority)
            ada_type = None
            var_name = expr.prefix.name.lower()
            if self.ctx and var_name in self.ctx.locals:
                local_info = self.ctx.locals[var_name]
                ada_type = self._resolve_local_type(local_info.ada_type)

                # Check for dynamically-bounded local arrays (e.g., I_A_2(1..N, ...))
                if local_info.dynamic_bounds and attr in ("first", "last", "length", "range"):
                    dim = 0
                    if expr.args:
                        dim_arg = expr.args[0]
                        if isinstance(dim_arg, IntegerLiteral):
                            dim = dim_arg.value - 1
                        elif isinstance(dim_arg, Identifier):
                            dim_sym = self.symbols.lookup(dim_arg.name)
                            if dim_sym and dim_sym.value is not None:
                                dim = int(dim_sym.value) - 1
                    if dim < len(local_info.dynamic_bounds):
                        low_vreg, high_vreg = local_info.dynamic_bounds[dim]
                        if attr == "first":
                            return low_vreg
                        if attr == "last":
                            return high_vreg
                        if attr == "length":
                            result = self.builder.new_vreg(IRType.WORD, "_length")
                            temp = self.builder.new_vreg(IRType.WORD, "_temp")
                            self.builder.sub(temp, high_vreg, low_vreg)
                            self.builder.add(result, temp, Immediate(1, IRType.WORD))
                            return result

            # Check if it's a parameter with dope vector (unconstrained array)
            if ada_type is None and self.ctx and var_name in self.ctx.unconstrained_params:
                # Determine which dimension (default is 1)
                dim = 1  # 1-indexed (Ada convention)
                if expr.args:
                    dim_arg = expr.args[0]
                    if isinstance(dim_arg, IntegerLiteral):
                        dim = dim_arg.value
                    elif isinstance(dim_arg, Identifier):
                        dim_sym = self.symbols.lookup(dim_arg.name)
                        if dim_sym and dim_sym.value is not None:
                            dim = int(dim_sym.value)

                # Try dimension-specific key first, then plain key
                first_key = f"{var_name}'first_{dim}"
                last_key = f"{var_name}'last_{dim}"
                if first_key not in self.ctx.params:
                    first_key = f"{var_name}'first"
                    last_key = f"{var_name}'last"

                if first_key in self.ctx.params:
                    if attr == "first":
                        return self.ctx.params[first_key]
                    if attr == "last":
                        return self.ctx.params[last_key]
                    if attr == "length":
                        first = self.ctx.params[first_key]
                        last = self.ctx.params[last_key]
                        result = self.builder.new_vreg(IRType.WORD, "_length")
                        temp = self.builder.new_vreg(IRType.WORD, "_temp")
                        self.builder.sub(temp, last, first)
                        self.builder.add(result, temp, Immediate(1, IRType.WORD))
                        return result

            # Check generic actual types first for type resolution
            if ada_type is None and self._generic_actual_types:
                formal_key = expr.prefix.name.lower()
                if formal_key in self._generic_actual_types:
                    ada_type = self._generic_actual_types[formal_key]

            # Always look up in symbol table (needed for 'Access, 'Address, etc.)
            # Resolve generic formal type names first
            lookup_name = expr.prefix.name
            if self._generic_type_map and lookup_name.lower() in self._generic_type_map:
                mapped = self._generic_type_map[lookup_name.lower()]
                if isinstance(mapped, str):
                    lookup_name = mapped
            sym = self.symbols.lookup(lookup_name)
            if sym is None and lookup_name != expr.prefix.name:
                sym = self.symbols.lookup(expr.prefix.name)

            # Fall back to symbol table for type if not found from locals
            if ada_type is None and sym:
                # Get the type - either from a TYPE/SUBTYPE symbol or from a VARIABLE symbol
                if sym.kind in (SymbolKind.TYPE, SymbolKind.SUBTYPE):
                    ada_type = sym.ada_type
                elif sym.kind == SymbolKind.FUNCTION and sym.return_type:
                    # For functions, use the return type for attributes
                    ada_type = sym.return_type
                elif sym.ada_type:
                    ada_type = sym.ada_type

            # Fallback: check locally-tracked subprogram return types
            # (for local functions declared in DECLARE blocks not in symbol table)
            if ada_type is None and var_name in self._subprogram_return_types:
                ada_type = self._subprogram_return_types[var_name]

            # Fallback: resolve locally-declared types via _resolve_local_type
            # (for types/subtypes declared in procedure bodies or DECLARE blocks)
            if ada_type is None:
                local_type = self._resolve_local_type(expr.prefix)
                if local_type:
                    ada_type = local_type

            if ada_type:
                # Handle array attributes
                if isinstance(ada_type, ArrayType):
                    if ada_type.is_constrained and ada_type.bounds:
                        # Determine which dimension (default is 1)
                        dim = 0  # 0-indexed internally
                        if expr.args:
                            # A'Last(N) - get dimension N (1-indexed in Ada)
                            dim_arg = expr.args[0]
                            if isinstance(dim_arg, IntegerLiteral):
                                dim = dim_arg.value - 1  # Convert to 0-indexed
                            elif isinstance(dim_arg, Identifier):
                                # Static integer - try to evaluate
                                dim_sym = self.symbols.lookup(dim_arg.name)
                                if dim_sym and dim_sym.value is not None:
                                    dim = int(dim_sym.value) - 1

                        if dim < len(ada_type.bounds):
                            low, high = ada_type.bounds[dim]
                            if attr == "first":
                                return Immediate(low, IRType.WORD)
                            if attr == "last":
                                return Immediate(high, IRType.WORD)
                            if attr == "length":
                                length = high - low + 1
                                return Immediate(length, IRType.WORD)
                    elif not ada_type.is_constrained:
                        # Unconstrained array (like String) - need runtime calculation
                        # Check if this is a parameter with dope vector
                        param_name = expr.prefix.name.lower()
                        if self.ctx and f"{param_name}'first" in self.ctx.params:
                            # Parameter has dope vector - use bounds from dope
                            if attr == "first":
                                return self.ctx.params[f"{param_name}'first"]
                            if attr == "last":
                                return self.ctx.params[f"{param_name}'last"]
                            if attr == "length":
                                # length = last - first + 1
                                first = self.ctx.params[f"{param_name}'first"]
                                last = self.ctx.params[f"{param_name}'last"]
                                result = self.builder.new_vreg(IRType.WORD, "_length")
                                temp = self.builder.new_vreg(IRType.WORD, "_temp")
                                self.builder.sub(temp, last, first)
                                self.builder.add(result, temp, Immediate(1, IRType.WORD))
                                return result
                        else:
                            # Not a parameter - use index type bounds
                            # Get the index type's first bound (default 1 for String)
                            index_first = 1
                            if ada_type.index_types and hasattr(ada_type.index_types[0], 'low'):
                                index_first = ada_type.index_types[0].low
                            if attr == "first":
                                return Immediate(index_first, IRType.WORD)

                # Handle enumeration attributes (before generic low/high
                # since EnumerationType.low property falls back to 0 when
                # constraint is dynamic)
                from uada80.type_system import EnumerationType
                if isinstance(ada_type, EnumerationType):
                    if attr == "first" and ada_type.literals:
                        first_pos = getattr(ada_type, 'first', None)
                        if first_pos is not None:
                            return Immediate(first_pos, IRType.WORD)
                        # Try dynamic constraint expression
                        cle = getattr(ada_type, 'constraint_low_expr', None)
                        if cle is not None:
                            return self._lower_expr(cle)
                        return Immediate(0, IRType.WORD)
                    if attr == "last" and ada_type.literals:
                        last_pos = getattr(ada_type, 'last', None)
                        if last_pos is not None:
                            return Immediate(last_pos, IRType.WORD)
                        # Try dynamic constraint expression
                        che = getattr(ada_type, 'constraint_high_expr', None)
                        if che is not None:
                            return self._lower_expr(che)
                        return Immediate(len(ada_type.literals) - 1, IRType.WORD)

                # Handle scalar type attributes (Integer'First, etc.)
                if attr == "first" and hasattr(ada_type, "low"):
                    # Dynamic constraint expression takes priority (set when
                    # static eval failed in semantic analysis)
                    cle = getattr(ada_type, 'constraint_low_expr', None)
                    if cle is not None:
                        return self._lower_expr(cle)
                    return Immediate(ada_type.low, IRType.WORD)
                if attr == "last" and hasattr(ada_type, "high"):
                    che = getattr(ada_type, 'constraint_high_expr', None)
                    if che is not None:
                        return self._lower_expr(che)
                    return Immediate(ada_type.high, IRType.WORD)
                if attr == "size":
                    return Immediate(ada_type.size_bits, IRType.WORD)

                # Handle fixed-point 'Fore and 'Aft attributes
                if attr == "fore":
                    import math
                    # Use range_first/range_last (real values), not low/high (scaled ints)
                    lo = getattr(ada_type, 'range_first', None)
                    hi = getattr(ada_type, 'range_last', None)
                    if lo is None:
                        lo = -1.0
                    if hi is None:
                        hi = 1.0
                    max_abs = max(abs(lo), abs(hi))
                    int_part = int(max_abs)
                    digits_before = 1 if int_part == 0 else int(math.log10(int_part)) + 1
                    return Immediate(1 + digits_before, IRType.WORD)
                if attr == "aft":
                    import math
                    delta = getattr(ada_type, 'delta', None) or getattr(ada_type, 'delta_value', None)
                    if delta is not None and delta > 0:
                        aft_val = max(int(math.ceil(-math.log10(delta))), 1)
                    else:
                        aft_val = 1
                    return Immediate(aft_val, IRType.WORD)

                # Handle 'Modulus attribute for modular types
                if attr == "modulus":
                    from uada80.type_system import ModularType
                    if isinstance(ada_type, ModularType):
                        return Immediate(ada_type.modulus, IRType.WORD)

                # Handle 'Class attribute for tagged types
                if attr == "class":
                    from uada80.type_system import RecordType
                    if isinstance(ada_type, RecordType) and ada_type.is_tagged:
                        # For T'Class, the value representation is the same
                        # Just the type is different (class-wide vs specific)
                        return self._lower_expr(expr.prefix)

                # Handle 'Tag attribute for tagged types
                if attr == "tag":
                    from uada80.type_system import RecordType
                    if isinstance(ada_type, RecordType) and ada_type.is_tagged:
                        # Check if prefix is a type name (Type'Tag = vtable address)
                        # vs an object (obj'Tag = load vtable ptr from offset 0)
                        is_type_prefix = (
                            sym and sym.kind in (SymbolKind.TYPE, SymbolKind.SUBTYPE)
                        )
                        if is_type_prefix:
                            # Type'Tag returns the vtable address for that type
                            vtable_name = f"_vtable_{ada_type.name}"
                            return Label(vtable_name)
                        else:
                            # Object'Tag: load vtable pointer from offset 0
                            obj_val = self._lower_expr(expr.prefix)
                            result = self.builder.new_vreg(IRType.PTR, "_tag")
                            self.builder.emit(IRInstr(OpCode.LOAD, result, obj_val,
                                                      comment="get tag (vtable ptr)"))
                            return result

                # Handle 'Range attribute (returns low bound for use in for loops)
                if attr == "range":
                    if isinstance(ada_type, ArrayType) and ada_type.bounds:
                        # For arrays, 'Range means the index range
                        low, high = ada_type.bounds[0]
                        return Immediate(low, IRType.WORD)
                    elif hasattr(ada_type, "low"):
                        return Immediate(ada_type.low, IRType.WORD)

            # Handle 'Access attribute for subprograms (needs sym lookup)
            if attr == "access" and sym:
                if sym.kind in (SymbolKind.PROCEDURE, SymbolKind.FUNCTION):
                    # Return address of subprogram
                    result = self.builder.new_vreg(IRType.PTR, "_access")
                    proc_name = expr.prefix.name
                    # Use LEA to get address of the procedure label
                    self.builder.emit(IRInstr(
                        OpCode.LEA,
                        dst=result,
                        src1=Label(proc_name),
                        comment=f"{proc_name}'Access"
                    ))
                    return result
                elif sym.kind == SymbolKind.VARIABLE:
                    # 'Access on variable returns pointer to variable
                    result = self.builder.new_vreg(IRType.PTR, "_access")
                    var_name = expr.prefix.name
                    if self.ctx and var_name.lower() in self.ctx.locals:
                        local_info = self.ctx.locals[var_name.lower()]
                        offset = local_info.offset
                        self.builder.emit(IRInstr(
                            OpCode.LEA,
                            dst=result,
                            src1=MemoryLocation(base=None, offset=offset, ir_type=IRType.PTR),
                            comment=f"{var_name}'Access"
                        ))
                    else:
                        self.builder.emit(IRInstr(
                            OpCode.LEA,
                            dst=result,
                            src1=MemoryLocation(is_global=True, symbol_name=var_name, ir_type=IRType.PTR),
                            comment=f"{var_name}'Access"
                        ))
                    return result

            # Handle 'Address attribute for variables
            if attr == "address" and sym:
                if sym.kind == SymbolKind.VARIABLE:
                    # Get address of variable - use LEA instruction
                    result = self.builder.new_vreg(IRType.PTR, "_addr")
                    var_name = expr.prefix.name
                    # Check if it's a local or global
                    if self.ctx and var_name.lower() in self.ctx.locals:
                        # Local variable - compute address from frame pointer
                        local_info = self.ctx.locals[var_name.lower()]
                        offset = local_info.offset
                        self.builder.emit(IRInstr(
                            OpCode.LEA,
                            dst=result,
                            src1=MemoryLocation(base=None, offset=offset, ir_type=IRType.PTR),
                            comment=f"{var_name}'Address"
                        ))
                    else:
                        # Global variable - use label address
                        self.builder.emit(IRInstr(
                            OpCode.LEA,
                            dst=result,
                            src1=MemoryLocation(is_global=True, symbol_name=var_name, ir_type=IRType.PTR),
                            comment=f"{var_name}'Address"
                        ))
                    return result

        # Handle array/scalar attributes on non-Identifier prefixes (function calls, etc.)
        # e.g., Concat1(X)'First, Pkg.Func'Last
        if not isinstance(expr.prefix, Identifier) and attr in ("first", "last", "length"):
            ada_type = self._get_expr_type(expr.prefix)
            if ada_type and isinstance(ada_type, ArrayType):
                if ada_type.is_constrained and ada_type.bounds:
                    dim = 0
                    if expr.args:
                        dim_arg = expr.args[0]
                        if isinstance(dim_arg, IntegerLiteral):
                            dim = dim_arg.value - 1
                    if dim < len(ada_type.bounds):
                        low, high = ada_type.bounds[dim]
                        if attr == "first":
                            return Immediate(low, IRType.WORD)
                        if attr == "last":
                            return Immediate(high, IRType.WORD)
                        if attr == "length":
                            return Immediate(high - low + 1, IRType.WORD)
                elif not ada_type.is_constrained:
                    # Unconstrained - use index type bounds for 'First
                    index_first = 1
                    if ada_type.index_types and hasattr(ada_type.index_types[0], 'low'):
                        index_first = ada_type.index_types[0].low
                    if attr == "first":
                        return Immediate(index_first, IRType.WORD)

        # Handle 'Access on SelectedName (package-qualified subprograms/variables)
        # e.g., C3A0012_0.Log_Calc_Fast'Access
        if attr == "access" and isinstance(expr.prefix, SelectedName):
            selector = expr.prefix.selector.lower()
            # Look up the prefix package and then the selector
            prefix_parts = []
            node = expr.prefix.prefix
            while isinstance(node, SelectedName):
                prefix_parts.append(node.selector)
                node = node.prefix
            if isinstance(node, Identifier):
                prefix_parts.append(node.name)
            prefix_parts.reverse()

            # Navigate package hierarchy to find the symbol
            pkg_sym = self.symbols.lookup(prefix_parts[0]) if prefix_parts else None
            for part in prefix_parts[1:]:
                if pkg_sym and pkg_sym.public_symbols:
                    pkg_sym = pkg_sym.public_symbols.get(part.lower())
                else:
                    pkg_sym = None
                    break
            if pkg_sym and pkg_sym.public_symbols:
                target_sym = pkg_sym.public_symbols.get(selector)
                if target_sym and target_sym.kind in (SymbolKind.PROCEDURE, SymbolKind.FUNCTION):
                    result = self.builder.new_vreg(IRType.PTR, "_access")
                    # Get the mangled label name for the subprogram
                    if target_sym.external_name:
                        label_name = target_sym.external_name.lower()
                    else:
                        label_name = f"_{target_sym.name.lower()}"
                    self.builder.emit(IRInstr(
                        OpCode.LEA,
                        dst=result,
                        src1=Label(label_name),
                        comment=f"{expr.prefix.selector}'Access"
                    ))
                    return result

        # Handle 'Pos, 'Val, 'Succ, 'Pred with arguments
        # Format: Type'Pos(X), Type'Val(N), Type'Succ(X), Type'Pred(X)
        if attr == "pos" and expr.args:
            # Type'Pos(X) - returns the position number of X
            # For enumeration, position is the internal value
            arg_value = self._lower_expr(expr.args[0])
            return arg_value  # For enums, value IS the position

        if attr == "val" and expr.args:
            # Type'Val(N) - returns the enumeration value at position N
            # Raises Constraint_Error if N is out of range
            arg_value = self._lower_expr(expr.args[0])

            # Add range check for enumeration types only:
            # N must be in [0..Type'Last_Position]
            # For non-enum types (integer, fixed-point), 'Val is identity and
            # range is too complex to check statically here.
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    ada_type = sym.ada_type
                    # Val uses BASE type bounds, not subtype bounds
                    root_type = ada_type
                    while hasattr(root_type, 'base_type') and root_type.base_type is not None:
                        root_type = root_type.base_type
                    low_val = 0
                    high_val = None
                    if isinstance(root_type, EnumerationType):
                        low_val = 0  # Base type always starts at 0
                        if root_type.literals:
                            high_val = len(root_type.literals) - 1
                        elif hasattr(root_type, 'high') and root_type.high is not None:
                            high_val = root_type.high
                    if high_val is not None and self.ctx:
                        # Check arg >= low (always needed — even when low=0,
                        # negative values like -1 pass the signed <= high check)
                        ok_low = self._new_label("val_lo_ok")
                        cond_lo = self.builder.new_vreg(IRType.BOOL, "_val_lo")
                        self.builder.cmp_ge(cond_lo, arg_value, Immediate(low_val, IRType.WORD))
                        self.builder.jz(cond_lo, Label("_raise_constraint_error"))
                        lo_block = self.builder.new_block(ok_low)
                        self.builder.set_block(lo_block)
                        # Check arg <= high
                        ok_hi = self._new_label("val_hi_ok")
                        cond_hi = self.builder.new_vreg(IRType.BOOL, "_val_hi")
                        self.builder.cmp_le(cond_hi, arg_value, Immediate(high_val, IRType.WORD))
                        self.builder.jz(cond_hi, Label("_raise_constraint_error"))
                        hi_block = self.builder.new_block(ok_hi)
                        self.builder.set_block(hi_block)

            return arg_value  # For enums, position IS the value

        if attr == "succ" and expr.args:
            # Type'Succ(X) - returns the successor of X
            # Raises Constraint_Error if X is already at base type's 'Last
            arg_value = self._lower_expr(expr.args[0])

            # Get type information for bounds check
            # SUCC/PRED use the BASE type bounds, not subtype bounds
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    ada_type = sym.ada_type
                    # Follow base_type chain to get root type bounds
                    root_type = ada_type
                    while hasattr(root_type, 'base_type') and root_type.base_type is not None:
                        root_type = root_type.base_type
                    # Check that X < root_type'Last (can succeed)
                    if hasattr(root_type, "high"):
                        self._emit_succ_check(arg_value, root_type.high)
                    elif isinstance(root_type, EnumerationType) and root_type.literals:
                        self._emit_succ_check(arg_value, len(root_type.literals) - 1)

            result = self.builder.new_vreg(IRType.WORD, "_succ")
            self.builder.add(result, arg_value, Immediate(1, IRType.WORD))
            return result

        if attr == "pred" and expr.args:
            # Type'Pred(X) - returns the predecessor of X
            # Raises Constraint_Error if X is already at base type's 'First
            arg_value = self._lower_expr(expr.args[0])

            # Get type information for bounds check
            # SUCC/PRED use the BASE type bounds, not subtype bounds
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    ada_type = sym.ada_type
                    # Follow base_type chain to get root type bounds
                    root_type = ada_type
                    while hasattr(root_type, 'base_type') and root_type.base_type is not None:
                        root_type = root_type.base_type
                    # Check that X > root_type'First (can precede)
                    if hasattr(root_type, "low"):
                        self._emit_pred_check(arg_value, root_type.low)
                    elif isinstance(root_type, EnumerationType):
                        self._emit_pred_check(arg_value, 0)

            result = self.builder.new_vreg(IRType.WORD, "_pred")
            self.builder.sub(result, arg_value, Immediate(1, IRType.WORD))
            return result

        if attr == "image" and expr.args:
            # Type'Image(X) - returns string representation of X
            # Returns pointer to static buffer (not reentrant)

            # Determine the prefix type to call the right conversion function
            prefix_type = None
            enum_literals = None  # For locally declared enum types
            # Check generic actual types first
            if isinstance(expr.prefix, Identifier) and self._generic_actual_types:
                formal_key = expr.prefix.name.lower()
                if formal_key in self._generic_actual_types:
                    prefix_type = self._generic_actual_types[formal_key]
            if isinstance(expr.prefix, Identifier):
                type_name = expr.prefix.name.lower()
                orig_type_name = type_name
                # Resolve generic formal type names first
                if self._generic_type_map and type_name in self._generic_type_map:
                    mapped = self._generic_type_map[type_name]
                    if isinstance(mapped, str):
                        type_name = mapped.lower()
                sym = self.symbols.lookup(type_name)
                # If mapped name not found, try original name
                if sym is None and type_name != orig_type_name:
                    sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.kind in (SymbolKind.TYPE, SymbolKind.SUBTYPE):
                    prefix_type = sym.ada_type

                # Also check local type declarations (for locally declared enums)
                # Search the full body declarations stack (not just current block)
                if prefix_type is None and hasattr(self, '_body_declarations_stack'):
                    from uada80.ast_nodes import EnumerationTypeDef
                    for decl_list in reversed(self._body_declarations_stack):
                        for d in decl_list:
                            if isinstance(d, TypeDecl) and d.name.lower() == type_name:
                                if isinstance(d.type_def, EnumerationTypeDef) and d.type_def.literals:
                                    enum_literals = d.type_def.literals
                                if enum_literals:
                                    break
                        if enum_literals:
                            break

            # Check if it's an enumeration type (but not Boolean which has special handling)
            from uada80.type_system import EnumerationType
            # If prefix_type is a generic formal placeholder, resolve to actual type
            if (prefix_type and not isinstance(prefix_type, EnumerationType)
                    and prefix_type.kind == TypeKind.ENUMERATION and self._generic_actual_types):
                actual = self._generic_actual_types.get(prefix_type.name.lower())
                if actual and isinstance(actual, EnumerationType):
                    prefix_type = actual
            is_enum = ((prefix_type and isinstance(prefix_type, EnumerationType) and
                       not self._is_bool_derived(prefix_type) and
                       not self._is_char_derived(prefix_type) and
                       prefix_type.name not in ("Wide_Character", "Wide_Wide_Character"))
                      or enum_literals)

            if is_enum:
                # Enumeration'Image - lookup value in table to get string
                # Generate a unique label for this enum's lookup table
                table_label = self.builder.new_label("_enum_img")

                # Create the table entries: [(name, value), ...]
                # Character literals get wrapped in quotes for Image format
                entries = []
                char_lits = set()
                if prefix_type and isinstance(prefix_type, EnumerationType):
                    char_lits = getattr(prefix_type, 'char_literals', set()) or set()
                    for lit_name in prefix_type.literals:
                        value = prefix_type.positions.get(lit_name, 0)
                        # Character literals need 'X' format in Image output
                        if lit_name in char_lits:
                            display = f"'{lit_name}'"
                        else:
                            display = lit_name
                        entries.append((display, value))
                elif enum_literals:
                    # Local enum declaration - literals are in order
                    for i, lit_name in enumerate(enum_literals):
                        entries.append((lit_name, i))

                # Add the table to the module
                if self.builder.module:
                    self.builder.module.add_enum_table(table_label, entries)

                # Push table pointer, then enum value
                arg_value = self._lower_expr(expr.args[0])
                self.builder.push(arg_value)  # enum ordinal value
                table_ptr = self.builder.new_vreg(IRType.PTR, "_tbl_ptr")
                self.builder.mov(table_ptr, Label(table_label), comment="enum table pointer")
                self.builder.push(table_ptr)
                self.builder.call(Label("_e_img"), comment="Enumeration'Image")
                # Result is pointer to string in HL
                result = self.builder.new_vreg(IRType.PTR, "_image")
                self.builder.emit(IRInstr(
                    OpCode.MOV, result,
                    MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.PTR),
                    comment="capture Enumeration'Image result from HL"
                ))
                # Clean up the pushed arguments (2 words)
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                self.builder.pop(temp)
                return result

            # Check for Float64 (Long_Float) - requires special handling for 8-byte values
            if self._is_float64_type(prefix_type):
                # Get pointer to Float64 value
                float_ptr = self._lower_float64_operand(expr.args[0])
                self.builder.push(float_ptr)
                self.builder.call(Label("_f64_img"), comment="Long_Float'Image")
                # Result is pointer to string in HL
                result = self.builder.new_vreg(IRType.PTR, "_image")
                self.builder.emit(IRInstr(
                    OpCode.MOV, result,
                    MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.PTR),
                    comment="capture Long_Float'Image result from HL"
                ))
                # Clean up pushed pointer
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                return result

            arg_value = self._lower_expr(expr.args[0])
            self.builder.push(arg_value)

            # Choose the right runtime function based on type
            if prefix_type and self._is_bool_derived(prefix_type):
                self.builder.call(Label("_b_img"), comment="Boolean'Image")
            elif prefix_type and self._is_char_derived(prefix_type):
                self.builder.call(Label("_c_img"), comment="Character'Image")
            elif prefix_type and hasattr(prefix_type, 'name') and prefix_type.name == "Wide_Character":
                self.builder.call(Label("_wc_img"), comment="Wide_Character'Image")
            elif prefix_type and hasattr(prefix_type, 'name') and prefix_type.name == "Wide_Wide_Character":
                self.builder.call(Label("_wwc_img"), comment="Wide_Wide_Character'Image")
            elif prefix_type and hasattr(prefix_type, 'name') and prefix_type.name == "Float":
                # Float currently truncates to integer in the implementation
                # TODO: Full 16.16 fixed-point support would need _fix_img
                self.builder.call(Label("_int_to_str"), comment="Float'Image")
            else:
                # Default: Integer'Image
                self.builder.call(Label("_int_to_str"), comment="Integer'Image")

            # IMPORTANT: Capture result from HL BEFORE popping argument
            # The pop would otherwise destroy HL which contains the result
            result = self.builder.new_vreg(IRType.PTR, "_image")
            self.builder.emit(IRInstr(
                OpCode.MOV, result,
                MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.PTR),
                comment="capture 'Image result from HL"
            ))
            # Now clean up the pushed argument
            temp = self.builder.new_vreg(IRType.WORD, "_discard")
            self.builder.pop(temp)
            return result

        if attr == "img":
            # X'Img - Ada 2012 shorthand for Type_Of_X'Image(X)
            # The prefix is the object itself, not a type
            # Evaluate the prefix to get its value
            prefix_value = self._lower_expr(expr.prefix)
            self.builder.push(prefix_value)
            self.builder.call(Label("_int_to_str"), comment="X'Img")
            # IMPORTANT: Capture result from HL BEFORE popping argument
            result = self.builder.new_vreg(IRType.PTR, "_img")
            self.builder.emit(IRInstr(
                OpCode.MOV, result,
                MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.PTR),
                comment="capture X'Img result from HL"
            ))
            # Now clean up the pushed argument
            temp = self.builder.new_vreg(IRType.WORD, "_discard")
            self.builder.pop(temp)
            return result

        if attr == "value" and expr.args:
            # Type'Value(S) - converts string to value
            # Determine the prefix type to call the right conversion function
            prefix_type = None
            enum_literals = None  # For locally declared enum types
            # Check generic actual types first
            if isinstance(expr.prefix, Identifier) and self._generic_actual_types:
                formal_key = expr.prefix.name.lower()
                if formal_key in self._generic_actual_types:
                    prefix_type = self._generic_actual_types[formal_key]
            if isinstance(expr.prefix, Identifier):
                type_name = expr.prefix.name.lower()
                orig_type_name = type_name
                # Resolve generic formal type names first
                if self._generic_type_map and type_name in self._generic_type_map:
                    mapped = self._generic_type_map[type_name]
                    if isinstance(mapped, str):
                        type_name = mapped.lower()
                sym = self.symbols.lookup(type_name)
                # If mapped name not found, try original name
                if sym is None and type_name != orig_type_name:
                    sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.kind in (SymbolKind.TYPE, SymbolKind.SUBTYPE):
                    prefix_type = sym.ada_type

                # Also check local type declarations (for locally declared enums)
                # Search the full body declarations stack (not just current block)
                if prefix_type is None and hasattr(self, '_body_declarations_stack'):
                    from uada80.ast_nodes import EnumerationTypeDef
                    for decl_list in reversed(self._body_declarations_stack):
                        for d in decl_list:
                            if isinstance(d, TypeDecl) and d.name.lower() == type_name:
                                if isinstance(d.type_def, EnumerationTypeDef) and d.type_def.literals:
                                    enum_literals = d.type_def.literals
                                if enum_literals:
                                    break
                        if enum_literals:
                            break

            # Check if it's a Float64 type (Long_Float)
            if self._is_float64_type(prefix_type):
                # Float64'Value - parse string to Float64
                arg_value = self._lower_expr(expr.args[0])
                self.builder.push(arg_value)
                self.builder.call(Label("_str_f64"), comment="Long_Float'Value")
                # Result is pointer to Float64 in HL
                result = self.builder.new_vreg(IRType.PTR, "_value_ptr")
                self.builder.emit(IRInstr(
                    OpCode.MOV, result,
                    MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.PTR),
                    comment="capture Long_Float'Value result ptr from HL"
                ))
                # Clean up the pushed argument
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                return result
            elif prefix_type and self._is_bool_derived(prefix_type):
                # Boolean'Value - parse "TRUE" or "FALSE" string
                arg_value = self._lower_expr(expr.args[0])
                self.builder.push(arg_value)
                self.builder.call(Label("_s2b"), comment="Boolean'Value")
                # Result is in HL (0 or 1)
                result = self.builder.new_vreg(IRType.WORD, "_value")
                self.builder.emit(IRInstr(
                    OpCode.MOV, result,
                    MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                    comment="capture Boolean'Value result from HL"
                ))
                # Clean up the pushed argument
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                return result
            elif prefix_type and self._is_char_derived(prefix_type):
                # Character'Value - parse "'X'" or "X" to character code
                arg_value = self._lower_expr(expr.args[0])
                self.builder.push(arg_value)
                self.builder.call(Label("_c_val"), comment="Character'Value")
                # Result is in HL (character code 0-255)
                result = self.builder.new_vreg(IRType.WORD, "_value")
                self.builder.emit(IRInstr(
                    OpCode.MOV, result,
                    MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                    comment="capture Character'Value result from HL"
                ))
                # Clean up the pushed argument
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                return result
            elif prefix_type and hasattr(prefix_type, 'name') and prefix_type.name == "Wide_Character":
                # Wide_Character'Value - parse "'X'" or "X" to wide character code
                arg_value = self._lower_expr(expr.args[0])
                self.builder.push(arg_value)
                self.builder.call(Label("_wc_val"), comment="Wide_Character'Value")
                # Result is in HL (wide character code 0-65535)
                result = self.builder.new_vreg(IRType.WORD, "_value")
                self.builder.emit(IRInstr(
                    OpCode.MOV, result,
                    MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                    comment="capture Wide_Character'Value result from HL"
                ))
                # Clean up the pushed argument
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                return result
            elif prefix_type and hasattr(prefix_type, 'name') and prefix_type.name == "Wide_Wide_Character":
                # Wide_Wide_Character'Value - parse "'X'" or "X" to 32-bit character code
                # On Z80, returns low 16 bits in HL (sufficient for ASCII/BMP)
                arg_value = self._lower_expr(expr.args[0])
                self.builder.push(arg_value)
                self.builder.call(Label("_wwc_val"), comment="Wide_Wide_Character'Value")
                # Result is in HL (low 16 bits of 32-bit code point)
                result = self.builder.new_vreg(IRType.WORD, "_value")
                self.builder.emit(IRInstr(
                    OpCode.MOV, result,
                    MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                    comment="capture Wide_Wide_Character'Value result from HL"
                ))
                # Clean up the pushed argument
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                return result
            elif prefix_type and hasattr(prefix_type, 'name') and prefix_type.name == "Float":
                # Float'Value - parse string to integer (Float truncates to integer in current impl)
                arg_value = self._lower_expr(expr.args[0])
                self.builder.push(arg_value)
                self.builder.call(Label("_s2i"), comment="Float'Value")
                # Result is in HL (integer value)
                result = self.builder.new_vreg(IRType.WORD, "_value")
                self.builder.emit(IRInstr(
                    OpCode.MOV, result,
                    MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                    comment="capture Float'Value result from HL"
                ))
                # Clean up the pushed argument
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                return result
            else:
                # Check if it's an enumeration type (but not Boolean which is handled above)
                # Either from symbol table (prefix_type) or local declaration (enum_literals)
                from uada80.type_system import EnumerationType
                # If prefix_type is a generic formal placeholder, resolve to actual type
                if (prefix_type and not isinstance(prefix_type, EnumerationType)
                        and prefix_type.kind == TypeKind.ENUMERATION and self._generic_actual_types):
                    actual = self._generic_actual_types.get(prefix_type.name.lower())
                    if actual and isinstance(actual, EnumerationType):
                        prefix_type = actual
                is_enum = ((prefix_type and isinstance(prefix_type, EnumerationType) and
                           not self._is_bool_derived(prefix_type) and
                           not self._is_char_derived(prefix_type) and
                           prefix_type.name not in ("Wide_Character", "Wide_Wide_Character"))
                          or enum_literals)
                if is_enum:
                    # Enumeration'Value - lookup string in table
                    # Generate a unique label for this enum's lookup table
                    table_label = self.builder.new_label("_enum_tbl")

                    # Create the table entries: [(name, value), ...]
                    # Character literals get 'X' format for Value matching
                    entries = []
                    char_lits = set()
                    if prefix_type and isinstance(prefix_type, EnumerationType):
                        char_lits = getattr(prefix_type, 'char_literals', set()) or set()
                        for lit_name in prefix_type.literals:
                            value = prefix_type.positions.get(lit_name, 0)
                            if lit_name in char_lits:
                                display = f"'{lit_name}'"
                            else:
                                display = lit_name
                            entries.append((display, value))
                    elif enum_literals:
                        # Local enum declaration - literals are in order
                        for i, lit_name in enumerate(enum_literals):
                            entries.append((lit_name, i))

                    # Add the table to the module
                    if self.builder.module:
                        self.builder.module.add_enum_table(table_label, entries)

                    # Push table pointer, then string pointer
                    arg_value = self._lower_expr(expr.args[0])
                    self.builder.push(arg_value)  # string pointer
                    table_ptr = self.builder.new_vreg(IRType.PTR, "_tbl_ptr")
                    self.builder.mov(table_ptr, Label(table_label), comment="enum table pointer")
                    self.builder.push(table_ptr)
                    self.builder.call(Label("_e_val"), comment="Enumeration'Value")
                    # Result is in HL
                    result = self.builder.new_vreg(IRType.WORD, "_value")
                    self.builder.emit(IRInstr(
                        OpCode.MOV, result,
                        MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                        comment="capture Enumeration'Value result from HL"
                    ))
                    # Clean up the pushed arguments (2 words)
                    temp = self.builder.new_vreg(IRType.WORD, "_discard")
                    self.builder.pop(temp)
                    self.builder.pop(temp)
                    return result
                else:
                    # Integer'Value - fallback for integer types
                    arg_value = self._lower_expr(expr.args[0])
                    self.builder.push(arg_value)
                    self.builder.call(Label("_s2i"), comment="Integer'Value")
                    # IMPORTANT: Capture result from HL BEFORE popping argument
                    # The pop would otherwise destroy HL which contains the result
                    result = self.builder.new_vreg(IRType.WORD, "_value")
                    self.builder.emit(IRInstr(
                        OpCode.MOV, result,
                        MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                        comment="capture Integer'Value result from HL"
                    ))
                    # Now clean up the pushed argument
                    temp = self.builder.new_vreg(IRType.WORD, "_discard")
                    self.builder.pop(temp)
                    return result

        if attr == "min" and len(expr.args) >= 2:
            # Type'Min(X, Y) - returns minimum of X and Y
            x = self._lower_expr(expr.args[0])
            y = self._lower_expr(expr.args[1])
            result = self.builder.new_vreg(IRType.WORD, "_min")
            cond = self.builder.new_vreg(IRType.BOOL, "_cmp")
            self.builder.cmp_lt(cond, x, y)
            # Simple approach: always compute both, then select
            # More complex: use conditional jumps
            self.builder.mov(result, x)
            # If y < x, use y instead
            end_label = self._new_label("min_end")
            self.builder.jnz(cond, Label(end_label))
            self.builder.mov(result, y)
            min_end = self.builder.new_block(end_label)
            self.builder.set_block(min_end)
            return result

        if attr == "max" and len(expr.args) >= 2:
            # Type'Max(X, Y) - returns maximum of X and Y
            x = self._lower_expr(expr.args[0])
            y = self._lower_expr(expr.args[1])
            result = self.builder.new_vreg(IRType.WORD, "_max")
            cond = self.builder.new_vreg(IRType.BOOL, "_cmp")
            self.builder.cmp_gt(cond, x, y)
            self.builder.mov(result, x)
            end_label = self._new_label("max_end")
            self.builder.jnz(cond, Label(end_label))
            self.builder.mov(result, y)
            max_end = self.builder.new_block(end_label)
            self.builder.set_block(max_end)
            return result

        if attr == "update":
            # Record'Update(Component => Value, ...)
            # Array'Update(Index => Value, ...)
            # Returns a copy of the prefix with specified components/elements updated
            #
            # For Z80, we:
            # 1. Copy the original to a temporary
            # 2. Update the specified components
            # 3. Return the temporary
            prefix_value = self._lower_expr(expr.prefix)

            # Get type information
            ada_type = None
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    ada_type = sym.ada_type

            if ada_type and isinstance(ada_type, RecordType):
                # Record update
                # Allocate space for result (same size as original)
                size_bytes = (ada_type.size_bits + 7) // 8
                result = self.builder.new_vreg(IRType.PTR, "_update_rec")

                # Copy original record to result
                # Stack layout: IX+4=count, IX+6=src, IX+8=dest
                self.builder.push(result)
                self.builder.push(prefix_value)
                self.builder.push(Immediate(size_bytes, IRType.WORD))
                self.builder.call(Label("_memcpy"), comment="copy record for 'Update")
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                self.builder.pop(temp)
                self.builder.pop(temp)

                # Apply updates from arguments
                # Arguments are (field => value) pairs
                for arg in expr.args:
                    if isinstance(arg, Aggregate):
                        # Named aggregate with component associations
                        for assoc in getattr(arg, 'associations', []):
                            if hasattr(assoc, 'choices') and hasattr(assoc, 'value'):
                                for choice in assoc.choices:
                                    if isinstance(choice, Identifier):
                                        field_name = choice.name.lower()
                                        # Find field offset
                                        if field_name in ada_type.components:
                                            comp = ada_type.components[field_name]
                                            offset = (comp.offset_bits + 7) // 8
                                            # Update the field
                                            new_val = self._lower_expr(assoc.value)
                                            field_addr = self.builder.new_vreg(IRType.PTR, "_field")
                                            self.builder.add(field_addr, result, Immediate(offset, IRType.WORD))
                                            self.builder.store(field_addr, new_val)

                return result

            elif ada_type and isinstance(ada_type, ArrayType):
                # Array update
                element_size = 2  # Default word
                if ada_type.component_type:
                    element_size = (ada_type.component_type.size_bits + 7) // 8

                # Calculate array size
                num_elements = 1
                if ada_type.bounds:
                    for low, high in ada_type.bounds:
                        num_elements *= (high - low + 1)
                size_bytes = num_elements * element_size

                result = self.builder.new_vreg(IRType.PTR, "_update_arr")

                # Copy original array
                # Stack layout: IX+4=count, IX+6=src, IX+8=dest
                self.builder.push(result)
                self.builder.push(prefix_value)
                self.builder.push(Immediate(size_bytes, IRType.WORD))
                self.builder.call(Label("_memcpy"), comment="copy array for 'Update")
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                self.builder.pop(temp)
                self.builder.pop(temp)

                # Apply index updates
                for arg in expr.args:
                    if isinstance(arg, Aggregate):
                        for assoc in getattr(arg, 'associations', []):
                            if hasattr(assoc, 'choices') and hasattr(assoc, 'value'):
                                for choice in assoc.choices:
                                    idx = self._lower_expr(choice)
                                    new_val = self._lower_expr(assoc.value)
                                    # Calculate offset
                                    offset = self.builder.new_vreg(IRType.WORD, "_idx_off")
                                    self.builder.mul(offset, idx, Immediate(element_size, IRType.WORD))
                                    elem_addr = self.builder.new_vreg(IRType.PTR, "_elem")
                                    self.builder.add(elem_addr, result, offset)
                                    self.builder.store(elem_addr, new_val)

                return result

            # Fallback: just return the prefix
            return prefix_value

        if attr == "valid":
            # X'Valid - returns True if X has a valid representation
            # For scalar types, check if value is in range
            prefix_value = self._lower_expr(expr.prefix)
            result = self.builder.new_vreg(IRType.WORD, "_valid")

            # Get type information from prefix
            ada_type = None
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    ada_type = sym.ada_type

            if ada_type:
                # Check if value is within type's valid range
                low_bound = None
                high_bound = None

                if hasattr(ada_type, "low"):
                    low_bound = ada_type.low
                if hasattr(ada_type, "high"):
                    high_bound = ada_type.high
                if isinstance(ada_type, EnumerationType) and ada_type.literals:
                    low_bound = 0
                    high_bound = len(ada_type.literals) - 1

                if low_bound is not None and high_bound is not None:
                    # result := (value >= low) AND (value <= high)
                    # Use short-circuit evaluation
                    valid_label = self._new_label("valid_ok")
                    invalid_label = self._new_label("valid_fail")
                    end_label = self._new_label("valid_end")

                    # Check low bound
                    cmp_low = self.builder.new_vreg(IRType.BOOL, "_cmp_low")
                    self.builder.cmp_lt(cmp_low, prefix_value, Immediate(low_bound, IRType.WORD))
                    self.builder.jnz(cmp_low, Label(invalid_label))

                    # Check high bound
                    cmp_high = self.builder.new_vreg(IRType.BOOL, "_cmp_high")
                    self.builder.cmp_gt(cmp_high, prefix_value, Immediate(high_bound, IRType.WORD))
                    self.builder.jnz(cmp_high, Label(invalid_label))

                    # Valid
                    self.builder.label(valid_label)
                    self.builder.mov(result, Immediate(1, IRType.WORD))
                    self.builder.jmp(Label(end_label))

                    # Invalid
                    self.builder.label(invalid_label)
                    self.builder.mov(result, Immediate(0, IRType.WORD))

                    # End
                    self.builder.label(end_label)
                    return result

            # Default: always valid
            self.builder.mov(result, Immediate(1, IRType.WORD))
            return result

        if attr == "constrained":
            # X'Constrained - returns True if X is constrained (for discriminated records)
            # For most objects, this is a static True
            result = self.builder.new_vreg(IRType.WORD, "_constrained")
            self.builder.mov(result, Immediate(1, IRType.WORD))
            return result

        def _lower_task_attr_prefix(prefix):
            """Lower the prefix of T'Callable/T'Terminated.
            If prefix is the current task type name (self-reference), use _TSK_SELF."""
            if isinstance(prefix, Identifier):
                pname = prefix.name.lower()
                cur_task = getattr(self, '_current_task_type_name', None)
                if cur_task and pname == cur_task:
                    # Self-reference: get current task's ID via runtime
                    self_id = self.builder.new_vreg(IRType.WORD, "_self_tid")
                    self.builder.call(Label("_TSK_SELF"), comment="get current task ID")
                    self.builder.emit(IRInstr(
                        OpCode.MOV, self_id,
                        MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                    ))
                    return self_id
                # Check task_objects for single task / task type instances
                if self.ctx and pname in self.ctx.task_objects:
                    return self.ctx.task_objects[pname]
                # Check enclosing contexts
                ctx = self.ctx
                while ctx:
                    if pname in ctx.task_objects:
                        return ctx.task_objects[pname]
                    ctx = ctx.enclosing_ctx
            return self._lower_expr(prefix)

        if attr == "callable":
            # T'Callable - check if task T is callable via runtime
            # _TSK_CLBL takes task_id on stack, returns result in HL
            task_id = _lower_task_attr_prefix(expr.prefix)
            self.builder.push(task_id)
            self.builder.call(Label("_TSK_CLBL"), comment="T'Callable")
            result = self.builder.new_vreg(IRType.WORD, "_callable")
            self.builder.emit(IRInstr(
                OpCode.MOV, result,
                MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                comment="callable result from HL"
            ))
            temp = self.builder.new_vreg(IRType.WORD, "_discard")
            self.builder.pop(temp)
            return result

        if attr == "terminated":
            # T'Terminated - check if task T has terminated via runtime
            # _TSK_TERM takes task_id on stack, returns result in HL
            task_id = _lower_task_attr_prefix(expr.prefix)
            self.builder.push(task_id)
            self.builder.call(Label("_TSK_TERM"), comment="T'Terminated")
            result = self.builder.new_vreg(IRType.WORD, "_terminated")
            self.builder.emit(IRInstr(
                OpCode.MOV, result,
                MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                comment="terminated result from HL"
            ))
            temp = self.builder.new_vreg(IRType.WORD, "_discard")
            self.builder.pop(temp)
            return result

        if attr == "identity":
            # T'Identity - returns the unique identity of task T
            # For Z80 single-threaded, return a fixed value (main task = 0)
            result = self.builder.new_vreg(IRType.WORD, "_identity")
            self.builder.mov(result, Immediate(0, IRType.WORD))
            return result

        if attr == "count":
            # E'Count - returns number of calls queued on entry E
            # Look up the entry_id and call _ENTR_CNT
            entry_name = None
            if isinstance(expr.prefix, Identifier):
                entry_name = expr.prefix.name.lower()
            elif isinstance(expr.prefix, SelectedName):
                entry_name = expr.prefix.selector.lower()
            entry_id = 0
            if entry_name:
                for _tn, emap in self._task_entry_ids.items():
                    if entry_name in emap:
                        entry_id = emap[entry_name]
                        break
            eid_vreg = self.builder.new_vreg(IRType.WORD, "_eid_cnt")
            self.builder.mov(eid_vreg, Immediate(entry_id, IRType.WORD))
            self.builder.push(eid_vreg)
            self.builder.call(Label("_ENTR_CNT"), comment=f"E'Count for {entry_name}")
            result = self.builder.new_vreg(IRType.WORD, "_count")
            self.builder.emit(IRInstr(
                OpCode.MOV, result,
                MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                comment="entry count from HL"
            ))
            temp = self.builder.new_vreg(IRType.WORD, "_discard")
            self.builder.pop(temp)
            return result

        if attr == "storage_size":
            # T'Storage_Size - storage allocated for task type T
            # For Z80, return stack size (default 256 bytes)
            result = self.builder.new_vreg(IRType.WORD, "_storage_size")
            self.builder.mov(result, Immediate(256, IRType.WORD))
            return result

        if attr == "bit_order":
            # S'Bit_Order - returns the bit ordering of type S
            # For Z80 (little-endian), return Low_Order_First (0)
            result = self.builder.new_vreg(IRType.WORD, "_bit_order")
            self.builder.mov(result, Immediate(0, IRType.WORD))
            return result

        if attr == "machine_radix":
            # S'Machine_Radix - returns the radix of type S
            # For Z80 binary machine, return 2
            result = self.builder.new_vreg(IRType.WORD, "_machine_radix")
            self.builder.mov(result, Immediate(2, IRType.WORD))
            return result

        if attr == "machine_mantissa":
            # S'Machine_Mantissa - returns mantissa digits for floating type
            # Not applicable for Z80 without FPU, return 0
            result = self.builder.new_vreg(IRType.WORD, "_machine_mantissa")
            self.builder.mov(result, Immediate(0, IRType.WORD))
            return result

        if attr == "digits":
            # S'Digits - returns decimal digits for floating/fixed type
            # For fixed-point on Z80, return 4 (16-bit fractional)
            result = self.builder.new_vreg(IRType.WORD, "_digits")
            self.builder.mov(result, Immediate(4, IRType.WORD))
            return result

        if attr == "delta":
            # S'Delta - returns delta for fixed-point type
            # Not directly supported, return 1
            result = self.builder.new_vreg(IRType.WORD, "_delta")
            self.builder.mov(result, Immediate(1, IRType.WORD))
            return result

        if attr == "base":
            # T'Base - returns the base type
            # For code generation, just return the prefix value
            return self._lower_expr(expr.prefix)

        if attr == "component_size":
            # A'Component_Size - size in bits of array components
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type and isinstance(sym.ada_type, ArrayType):
                    if sym.ada_type.component_type:
                        return Immediate(sym.ada_type.component_type.size_bits, IRType.WORD)
            return Immediate(16, IRType.WORD)  # Default word size

        if attr == "alignment":
            # T'Alignment - alignment requirement
            # For Z80, alignment is typically 1 (byte-aligned)
            return Immediate(1, IRType.WORD)

        if attr == "object_size":
            # X'Object_Size - size in bits of object X
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    return Immediate(sym.ada_type.size_bits, IRType.WORD)
            return Immediate(16, IRType.WORD)

        if attr == "value_size":
            # T'Value_Size - minimum bits to represent values of type T
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    return Immediate(sym.ada_type.size_bits, IRType.WORD)
            return Immediate(16, IRType.WORD)

        if attr == "old":
            # X'Old - value of X at subprogram entry (for postconditions)
            # This requires saving values at entry; for now, we look up
            # the saved value from a special prefix
            #
            # The semantic analyzer should have created a copy at entry.
            # We look for it in the locals with the prefix "_old_"
            if isinstance(expr.prefix, Identifier):
                old_name = f"_old_{expr.prefix.name.lower()}"
                if self.ctx and old_name in self.ctx.locals:
                    return self.ctx.locals[old_name].vreg

            # Fallback: just evaluate the current value
            # (This is incorrect but prevents crashes for unhandled cases)
            return self._lower_expr(expr.prefix)

        if attr == "result":
            # F'Result - the result of function F (for postconditions)
            # This should be the return value being computed
            # In our calling convention, the result is in HL register
            result = self.builder.new_vreg(IRType.WORD, "_func_result")
            self.builder.emit(IRInstr(
                OpCode.MOV, result,
                MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                comment="F'Result - function return value"
            ))
            return result

        if attr == "loop_entry":
            # X'Loop_Entry - value of X at loop entry (for loop invariants)
            # Similar to 'Old but for loop iterations
            if isinstance(expr.prefix, Identifier):
                entry_name = f"_loop_entry_{expr.prefix.name.lower()}"
                if self.ctx and entry_name in self.ctx.locals:
                    return self.ctx.locals[entry_name].vreg

            # Fallback: just evaluate the current value
            return self._lower_expr(expr.prefix)

        if attr == "reduce":
            # Container'Reduce(Reducer, Initial) - Ada 2022 reduction expression
            # Applies Reducer to each element with accumulator starting at Initial
            #
            # For arrays: iterate and apply reducer
            # Result = Initial
            # for E in Container loop
            #     Result := Reducer(Result, E);
            # end loop;
            result = self.builder.new_vreg(IRType.WORD, "_reduce_result")

            if len(expr.args) >= 2:
                reducer = expr.args[0]  # The reducer function/operator
                initial = expr.args[1]  # Initial value

                # Initialize result with initial value
                init_val = self._lower_expr(initial)
                self.builder.mov(result, init_val)

                # Get array info from prefix using _get_expr_type
                ada_type = self._get_expr_type(expr.prefix)

                if ada_type and isinstance(ada_type, ArrayType) and ada_type.bounds:
                    low, high = ada_type.bounds[0]
                    element_size = 2
                    if ada_type.component_type:
                        element_size = (ada_type.component_type.size_bits + 7) // 8

                    # Get base address - use _get_lvalue_address to compute actual address
                    base_addr = self._get_lvalue_address(expr.prefix)

                    # Loop variable
                    loop_idx = self.builder.new_vreg(IRType.WORD, "_reduce_idx")
                    self.builder.mov(loop_idx, Immediate(low, IRType.WORD))

                    # Loop labels
                    loop_start = self._new_label("reduce_loop")
                    loop_end = self._new_label("reduce_end")

                    # Loop start
                    self.builder.label(loop_start)

                    # Check loop condition
                    cmp_result = self.builder.new_vreg(IRType.BOOL, "_reduce_cmp")
                    self.builder.cmp_gt(cmp_result, loop_idx, Immediate(high, IRType.WORD))
                    self.builder.jnz(cmp_result, Label(loop_end))

                    # Get current element
                    offset = self.builder.new_vreg(IRType.WORD, "_reduce_off")
                    temp = self.builder.new_vreg(IRType.WORD, "_reduce_temp")
                    self.builder.sub(temp, loop_idx, Immediate(low, IRType.WORD))
                    self.builder.mul(offset, temp, Immediate(element_size, IRType.WORD))

                    elem_addr = self.builder.new_vreg(IRType.PTR, "_reduce_elem_addr")
                    self.builder.add(elem_addr, base_addr, offset)

                    elem_val = self.builder.new_vreg(IRType.WORD, "_reduce_elem")
                    self.builder.load(elem_val, MemoryLocation(base=elem_addr, offset=0, ir_type=IRType.WORD))

                    # Apply reducer (if it's a binary operator like "+")
                    # Handle both Identifier and StringLiteral for operator names
                    op_name = None
                    if isinstance(reducer, Identifier):
                        op_name = reducer.name.lower()
                    elif isinstance(reducer, StringLiteral):
                        op_name = reducer.value.lower()

                    if op_name:
                        if op_name == '+':
                            self.builder.add(result, result, elem_val)
                        elif op_name == '-':
                            self.builder.sub(result, result, elem_val)
                        elif op_name == '*':
                            self.builder.mul(result, result, elem_val)
                        elif op_name == 'and':
                            self.builder.and_(result, result, elem_val)
                        elif op_name == 'or':
                            self.builder.or_(result, result, elem_val)
                        else:
                            # Call reducer as function
                            self.builder.push(elem_val)
                            self.builder.push(result)
                            self.builder.call(Label(op_name))
                            temp2 = self.builder.new_vreg(IRType.WORD, "_discard")
                            self.builder.pop(temp2)
                            self.builder.pop(temp2)
                            self.builder.emit(IRInstr(
                                OpCode.MOV, result,
                                MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                                comment="capture reducer result"
                            ))

                    # Increment loop index
                    inc_temp = self.builder.new_vreg(IRType.WORD, "_reduce_inc")
                    self.builder.add(inc_temp, loop_idx, Immediate(1, IRType.WORD))
                    self.builder.mov(loop_idx, inc_temp)
                    self.builder.jmp(Label(loop_start))

                    # Loop end
                    self.builder.label(loop_end)

            return result

        if attr == "initialized":
            # X'Initialized - True if X has been initialized
            # For Z80, we always return True (no runtime tracking)
            result = self.builder.new_vreg(IRType.WORD, "_initialized")
            self.builder.mov(result, Immediate(1, IRType.WORD))
            return result

        if attr == "copy_sign":
            # T'Copy_Sign(Value, Sign) - copy sign from Sign to Value
            # For integers: if Sign < 0 then -abs(Value) else abs(Value)
            if len(expr.args) >= 2:
                value = self._lower_expr(expr.args[0])
                sign = self._lower_expr(expr.args[1])
                result = self.builder.new_vreg(IRType.WORD, "_copy_sign")

                # Get abs(value)
                abs_val = self.builder.new_vreg(IRType.WORD, "_abs_val")
                cmp1 = self.builder.new_vreg(IRType.BOOL, "_sign_cmp1")
                self.builder.cmp_lt(cmp1, value, Immediate(0, IRType.WORD))
                pos_label = self._new_label("copysign_pos")
                end_label = self._new_label("copysign_end")
                self.builder.jz(cmp1, Label(pos_label))
                self.builder.neg(abs_val, value)
                self.builder.jmp(Label(end_label))
                self.builder.label(pos_label)
                self.builder.mov(abs_val, value)
                self.builder.label(end_label)

                # Apply sign
                cmp2 = self.builder.new_vreg(IRType.BOOL, "_sign_cmp2")
                self.builder.cmp_lt(cmp2, sign, Immediate(0, IRType.WORD))
                neg_label = self._new_label("copysign_neg")
                done_label = self._new_label("copysign_done")
                self.builder.jz(cmp2, Label(neg_label))
                self.builder.neg(result, abs_val)
                self.builder.jmp(Label(done_label))
                self.builder.label(neg_label)
                self.builder.mov(result, abs_val)
                self.builder.label(done_label)

                return result
            return Immediate(0, IRType.WORD)

        if attr == "adjacent":
            # T'Adjacent(X, Towards) - value adjacent to X in direction of Towards
            # For integers: if Towards > X then X + 1 else if Towards < X then X - 1 else X
            if len(expr.args) >= 2:
                x = self._lower_expr(expr.args[0])
                towards = self._lower_expr(expr.args[1])
                result = self.builder.new_vreg(IRType.WORD, "_adjacent")

                cmp_gt = self.builder.new_vreg(IRType.BOOL, "_adj_cmp_gt")
                self.builder.cmp_gt(cmp_gt, towards, x)
                inc_label = self._new_label("adj_inc")
                check_lt_label = self._new_label("adj_check_lt")
                end_label = self._new_label("adj_end")

                self.builder.jz(cmp_gt, Label(check_lt_label))
                # Towards > X: increment
                self.builder.add(result, x, Immediate(1, IRType.WORD))
                self.builder.jmp(Label(end_label))

                self.builder.label(check_lt_label)
                cmp_lt = self.builder.new_vreg(IRType.BOOL, "_adj_cmp_lt")
                self.builder.cmp_lt(cmp_lt, towards, x)
                equal_label = self._new_label("adj_equal")
                self.builder.jz(cmp_lt, Label(equal_label))
                # Towards < X: decrement
                self.builder.sub(result, x, Immediate(1, IRType.WORD))
                self.builder.jmp(Label(end_label))

                self.builder.label(equal_label)
                # Equal: no change
                self.builder.mov(result, x)

                self.builder.label(end_label)
                return result
            return Immediate(0, IRType.WORD)

        if attr == "unrestricted_access":
            # X'Unrestricted_Access - like 'Access but without accessibility checks
            # Same implementation as 'Access for Z80
            prefix_val = self._lower_expr(expr.prefix)
            result = self.builder.new_vreg(IRType.PTR, "_unrestricted_access")

            if isinstance(expr.prefix, Identifier):
                name = expr.prefix.name.lower()
                # Check if it's a variable (get address) or subprogram (get label)
                sym = self.symbols.lookup(name)
                if sym and sym.kind == "variable":
                    self.builder.lea(result, prefix_val)
                elif sym and sym.kind in ("function", "procedure"):
                    self.builder.emit(IRInstr(
                        OpCode.LEA, result, Label(name),
                        comment=f"subprogram address '{name}'"
                    ))
                else:
                    self.builder.lea(result, prefix_val)
            else:
                self.builder.lea(result, prefix_val)

            return result

        if attr == "ceiling":
            # T'Ceiling(X) - smallest integer >= X
            if expr.args:
                arg_type = self._get_expr_type(expr.args[0])
                if self._is_float64_type(arg_type):
                    # Float64: call _f64_ceil
                    arg_ptr = self._lower_float64_operand(expr.args[0])
                    return self._lower_float64_math_attr("_f64_ceil", arg_ptr, arg_type)
                x = self._lower_expr(expr.args[0])
                result = self.builder.new_vreg(IRType.WORD, "_ceiling")
                self.builder.mov(result, x)
                return result
            return self._lower_expr(expr.prefix)

        if attr == "floor":
            # T'Floor(X) - largest integer <= X
            if expr.args:
                arg_type = self._get_expr_type(expr.args[0])
                if self._is_float64_type(arg_type):
                    # Float64: call _f64_floor
                    arg_ptr = self._lower_float64_operand(expr.args[0])
                    return self._lower_float64_math_attr("_f64_floor", arg_ptr, arg_type)
                x = self._lower_expr(expr.args[0])
                result = self.builder.new_vreg(IRType.WORD, "_floor")
                self.builder.mov(result, x)
                return result
            return self._lower_expr(expr.prefix)

        if attr == "rounding":
            # T'Rounding(X) - round to nearest integer (half away from zero)
            if expr.args:
                arg_type = self._get_expr_type(expr.args[0])
                if self._is_float64_type(arg_type):
                    # Float64: call _f64_round
                    arg_ptr = self._lower_float64_operand(expr.args[0])
                    return self._lower_float64_math_attr("_f64_round", arg_ptr, arg_type)
                x = self._lower_expr(expr.args[0])
                result = self.builder.new_vreg(IRType.WORD, "_rounding")
                self.builder.mov(result, x)
                return result
            return self._lower_expr(expr.prefix)

        if attr == "truncation":
            # T'Truncation(X) - truncate toward zero
            if expr.args:
                arg_type = self._get_expr_type(expr.args[0])
                if self._is_float64_type(arg_type):
                    # Float64: call _f64_trunc
                    arg_ptr = self._lower_float64_operand(expr.args[0])
                    return self._lower_float64_math_attr("_f64_trunc", arg_ptr, arg_type)
                x = self._lower_expr(expr.args[0])
                result = self.builder.new_vreg(IRType.WORD, "_truncation")
                self.builder.mov(result, x)
                return result
            return self._lower_expr(expr.prefix)

        if attr == "remainder":
            # T'Remainder(X, Y) - IEEE remainder
            # For integers: X mod Y with sign of X
            if len(expr.args) >= 2:
                x = self._lower_expr(expr.args[0])
                y = self._lower_expr(expr.args[1])
                result = self.builder.new_vreg(IRType.WORD, "_remainder")
                self.builder.rem(result, x, y)
                return result
            return Immediate(0, IRType.WORD)

        if attr == "machine":
            # T'Machine(X) - machine representation of X
            # For integers on Z80, this is just the value
            if expr.args:
                return self._lower_expr(expr.args[0])
            return self._lower_expr(expr.prefix)

        if attr == "model":
            # T'Model(X) - model number closest to X
            # For integers on Z80, this is just the value
            if expr.args:
                return self._lower_expr(expr.args[0])
            return self._lower_expr(expr.prefix)

        if attr == "compose":
            # T'Compose(Fraction, Exponent) - compose floating-point value
            # Not fully applicable to integers, return a scaled value
            if len(expr.args) >= 2:
                fraction = self._lower_expr(expr.args[0])
                exponent = self._lower_expr(expr.args[1])
                result = self.builder.new_vreg(IRType.WORD, "_compose")
                # Simplified: result = fraction * 2^exponent (via shift)
                self.builder.shl(result, fraction, exponent)
                return result
            return Immediate(0, IRType.WORD)

        if attr == "scaling":
            # T'Scaling(X, Adjustment) - scale by power of radix
            # For integers: X * 2^Adjustment
            if len(expr.args) >= 2:
                x = self._lower_expr(expr.args[0])
                adj = self._lower_expr(expr.args[1])
                result = self.builder.new_vreg(IRType.WORD, "_scaling")
                self.builder.shl(result, x, adj)
                return result
            return Immediate(0, IRType.WORD)

        if attr == "exponent":
            # T'Exponent(X) - exponent of X in canonical form
            # For integers: find position of highest set bit
            # Simplified implementation - just return a fixed value
            result = self.builder.new_vreg(IRType.WORD, "_exponent")
            self.builder.mov(result, Immediate(16, IRType.WORD))  # Assume 16-bit
            return result

        if attr == "fraction":
            # T'Fraction(X) - fractional part of X
            # For integers: 0 (no fractional part)
            result = self.builder.new_vreg(IRType.WORD, "_fraction")
            self.builder.mov(result, Immediate(0, IRType.WORD))
            return result

        if attr == "leading_part":
            # T'Leading_Part(X, Radix_Digits) - leading digits of X
            # Simplified: return X itself for integers
            if expr.args:
                return self._lower_expr(expr.args[0])
            return self._lower_expr(expr.prefix)

        if attr == "machine_rounding":
            # T'Machine_Rounding(X) - round according to machine mode
            # For integers, same as value
            if expr.args:
                return self._lower_expr(expr.args[0])
            return self._lower_expr(expr.prefix)

        if attr == "unbiased_rounding":
            # T'Unbiased_Rounding(X) - round to even (banker's rounding)
            # For integers, same as value
            if expr.args:
                return self._lower_expr(expr.args[0])
            return self._lower_expr(expr.prefix)

        if attr == "enum_rep":
            # T'Enum_Rep(X) - internal representation of enumeration value
            # For our compiler, enum values are already represented as integers
            if expr.args:
                return self._lower_expr(expr.args[0])
            return self._lower_expr(expr.prefix)

        if attr == "enum_val":
            # T'Enum_Val(X) - enumeration value from representation
            # Inverse of Enum_Rep - for us, identity function
            if expr.args:
                return self._lower_expr(expr.args[0])
            return self._lower_expr(expr.prefix)

        if attr == "wide_image" or attr == "wide_value":
            # Wide string versions - for Z80, same as regular Image/Value
            # since we don't support Unicode
            if attr == "wide_image":
                if expr.args:
                    val = self._lower_expr(expr.args[0])
                else:
                    val = self._lower_expr(expr.prefix)
                self.builder.push(val)
                self.builder.call(Label("_int_to_str"), comment="Wide_Image")
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                result = self.builder.new_vreg(IRType.PTR, "_wide_image")
                self.builder.emit(IRInstr(
                    OpCode.MOV, result,
                    MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.PTR),
                    comment="capture Wide_Image result"
                ))
                return result
            else:  # wide_value
                if expr.args:
                    str_val = self._lower_expr(expr.args[0])
                else:
                    str_val = self._lower_expr(expr.prefix)
                self.builder.push(str_val)
                self.builder.call(Label("_str_to_int"), comment="Wide_Value")
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                result = self.builder.new_vreg(IRType.WORD, "_wide_value")
                self.builder.emit(IRInstr(
                    OpCode.MOV, result,
                    MemoryLocation(is_global=False, symbol_name="_HL", ir_type=IRType.WORD),
                    comment="capture Wide_Value result"
                ))
                return result

        if attr == "overlaps_storage":
            # X'Overlaps_Storage(Y) - True if X and Y share any storage
            # Compare address ranges for overlap
            if expr.args:
                x_addr = self._lower_expr(expr.prefix)
                y_addr = self._lower_expr(expr.args[0])

                # Get sizes (default to 2 bytes)
                x_size = 2
                y_size = 2
                if isinstance(expr.prefix, Identifier):
                    sym = self.symbols.lookup(expr.prefix.name)
                    if sym and sym.ada_type and hasattr(sym.ada_type, 'size_bits'):
                        x_size = (sym.ada_type.size_bits + 7) // 8
                if isinstance(expr.args[0], Identifier):
                    sym = self.symbols.lookup(expr.args[0].name)
                    if sym and sym.ada_type and hasattr(sym.ada_type, 'size_bits'):
                        y_size = (sym.ada_type.size_bits + 7) // 8

                result = self.builder.new_vreg(IRType.WORD, "_overlaps")

                # Overlaps if NOT (x_end <= y_start OR y_end <= x_start)
                # Simplified: compare addresses
                x_end = self.builder.new_vreg(IRType.PTR, "_x_end")
                y_end = self.builder.new_vreg(IRType.PTR, "_y_end")
                self.builder.add(x_end, x_addr, Immediate(x_size, IRType.WORD))
                self.builder.add(y_end, y_addr, Immediate(y_size, IRType.WORD))

                # Check x_end <= y_start
                cmp1 = self.builder.new_vreg(IRType.BOOL, "_cmp1")
                self.builder.cmp_le(cmp1, x_end, y_addr)

                # Check y_end <= x_start
                cmp2 = self.builder.new_vreg(IRType.BOOL, "_cmp2")
                self.builder.cmp_le(cmp2, y_end, x_addr)

                # No overlap if either is true
                no_overlap = self.builder.new_vreg(IRType.BOOL, "_no_overlap")
                self.builder.or_(no_overlap, cmp1, cmp2)

                # Result is NOT no_overlap
                self.builder.not_(result, no_overlap)
                return result

            return Immediate(0, IRType.WORD)

        if attr == "has_same_storage":
            # X'Has_Same_Storage(Y) - True if X and Y occupy exactly the same storage
            # Compare addresses and sizes
            if expr.args:
                x_addr = self._lower_expr(expr.prefix)
                y_addr = self._lower_expr(expr.args[0])

                # Get sizes
                x_size = 2
                y_size = 2
                if isinstance(expr.prefix, Identifier):
                    sym = self.symbols.lookup(expr.prefix.name)
                    if sym and sym.ada_type and hasattr(sym.ada_type, 'size_bits'):
                        x_size = (sym.ada_type.size_bits + 7) // 8
                if isinstance(expr.args[0], Identifier):
                    sym = self.symbols.lookup(expr.args[0].name)
                    if sym and sym.ada_type and hasattr(sym.ada_type, 'size_bits'):
                        y_size = (sym.ada_type.size_bits + 7) // 8

                result = self.builder.new_vreg(IRType.WORD, "_same_storage")

                # Same storage if addresses equal and sizes equal
                addr_eq = self.builder.new_vreg(IRType.BOOL, "_addr_eq")
                self.builder.cmp_eq(addr_eq, x_addr, y_addr)

                if x_size == y_size:
                    self.builder.mov(result, addr_eq)
                else:
                    # Different sizes, cannot be same storage
                    self.builder.mov(result, Immediate(0, IRType.WORD))

                return result

            return Immediate(0, IRType.WORD)

        if attr == "valid_scalars":
            # X'Valid_Scalars - True if all scalar components of X are valid
            # For simple scalars, same as 'Valid
            # For aggregates, would need to check each component
            result = self.builder.new_vreg(IRType.WORD, "_valid_scalars")
            self.builder.mov(result, Immediate(1, IRType.WORD))  # Assume valid
            return result

        if attr == "descriptor_size":
            # T'Descriptor_Size - size of fat pointer descriptor
            # For unconstrained arrays, this includes bounds info
            # Default: 2 bytes for pointer + 4 bytes for bounds (1D array)
            return Immediate(6, IRType.WORD)

        if attr == "default_bit_order":
            # System'Default_Bit_Order - default bit ordering
            # Z80 is little-endian: Low_Order_First = 0
            return Immediate(0, IRType.WORD)

        if attr == "storage_unit":
            # System'Storage_Unit - bits per storage unit
            # Z80: 8 bits per byte
            return Immediate(8, IRType.WORD)

        if attr == "word_size":
            # System'Word_Size - bits per machine word
            # Z80: 16-bit words (even though it's an 8-bit CPU)
            return Immediate(16, IRType.WORD)

        if attr == "max_int" or attr == "max_integer":
            # System'Max_Int - largest integer value
            return Immediate(32767, IRType.WORD)

        if attr == "min_int" or attr == "min_integer":
            # System'Min_Int - smallest integer value
            return Immediate(-32768, IRType.WORD)

        if attr == "tick":
            # System'Tick - clock tick duration (in seconds)
            # For Z80/CP/M, this is system-dependent
            # Return a small positive value (1/100 second = 10ms)
            return Immediate(10, IRType.WORD)  # milliseconds

        if attr == "target_name":
            # System'Target_Name - target platform name
            # Return pointer to string "Z80-CPM"
            result = self.builder.new_vreg(IRType.PTR, "_target_name")
            # Use a string constant (would need to be in data section)
            self.builder.emit(IRInstr(
                OpCode.LEA, result, Label("_target_name_str"),
                comment="System'Target_Name"
            ))
            return result

        if attr == "compiler_version":
            # GNAT specific but useful - return version string pointer
            result = self.builder.new_vreg(IRType.PTR, "_compiler_version")
            self.builder.emit(IRInstr(
                OpCode.LEA, result, Label("_compiler_version_str"),
                comment="Compiler_Version"
            ))
            return result

        if attr == "null_parameter":
            # Used in imported subprograms - returns null pointer
            return Immediate(0, IRType.WORD)

        if attr == "passed_by_reference":
            # T'Passed_By_Reference - True if type is passed by reference
            # For Z80: arrays, records > 2 bytes, tagged types
            ada_type = None
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    ada_type = sym.ada_type

            if ada_type:
                if isinstance(ada_type, ArrayType):
                    return Immediate(1, IRType.WORD)
                if isinstance(ada_type, RecordType):
                    size = (ada_type.size_bits + 7) // 8 if ada_type.size_bits else 4
                    return Immediate(1 if size > 2 else 0, IRType.WORD)
            return Immediate(0, IRType.WORD)

        if attr == "type_class":
            # T'Type_Class - returns enumeration indicating type classification
            # Values: 0=Integer, 1=Boolean, 2=Character, 3=Enumeration,
            #         4=Float, 5=Fixed, 6=Array, 7=Record, 8=Access, 9=Task, etc.
            ada_type = None
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    ada_type = sym.ada_type

            if ada_type:
                from uada80.type_system import IntegerType
                # Boolean and Character are EnumerationType with specific names
                if isinstance(ada_type, EnumerationType):
                    type_name = getattr(ada_type, 'name', '').lower()
                    if type_name == 'boolean':
                        return Immediate(1, IRType.WORD)
                    if type_name == 'character':
                        return Immediate(2, IRType.WORD)
                    return Immediate(3, IRType.WORD)  # Other enumeration
                if isinstance(ada_type, ArrayType):
                    return Immediate(6, IRType.WORD)
                if isinstance(ada_type, RecordType):
                    return Immediate(7, IRType.WORD)
                if isinstance(ada_type, AccessType):
                    return Immediate(8, IRType.WORD)
                if isinstance(ada_type, IntegerType):
                    return Immediate(0, IRType.WORD)
            return Immediate(0, IRType.WORD)  # Default to Integer

        if attr == "put_image":
            # T'Put_Image(Buffer, Item) - Ada 2022 custom image output
            # Calls the Put_Image procedure associated with the type
            if len(expr.args) >= 2:
                buffer = self._lower_expr(expr.args[0])
                item = self._lower_expr(expr.args[1])
                # Call runtime Put_Image procedure
                self.builder.push(item)
                self.builder.push(buffer)
                self.builder.call(Label("_put_image"), comment="T'Put_Image")
                temp = self.builder.new_vreg(IRType.WORD, "_discard")
                self.builder.pop(temp)
                self.builder.pop(temp)
            return Immediate(0, IRType.WORD)

        if attr == "max_size_in_storage_elements":
            # T'Max_Size_In_Storage_Elements - max size in storage elements
            # For Z80: size in bytes (storage element = 1 byte)
            ada_type = None
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    ada_type = sym.ada_type
            if ada_type and hasattr(ada_type, 'size_bits'):
                return Immediate((ada_type.size_bits + 7) // 8, IRType.WORD)
            return Immediate(2, IRType.WORD)

        if attr == "index":
            # T'Index(Iterator) - Ada 2012 iterator index
            # Returns current index in generalized iteration
            if expr.args:
                return self._lower_expr(expr.args[0])
            return Immediate(0, IRType.WORD)

        if attr == "finalization_size":
            # T'Finalization_Size - size needed for finalization
            # For Z80 with no finalization, return 0
            return Immediate(0, IRType.WORD)

        if attr == "definite":
            # T'Definite - True if type is definite (not indefinite)
            # Most types on Z80 are definite (unconstrained arrays are indefinite)
            ada_type = None
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    ada_type = sym.ada_type
            if ada_type and isinstance(ada_type, ArrayType):
                return Immediate(1 if ada_type.is_constrained else 0, IRType.WORD)
            return Immediate(1, IRType.WORD)

        if attr == "has_discriminants":
            # T'Has_Discriminants - True if type has discriminants
            ada_type = None
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    ada_type = sym.ada_type
            if ada_type and isinstance(ada_type, RecordType):
                return Immediate(1 if ada_type.discriminants else 0, IRType.WORD)
            return Immediate(0, IRType.WORD)

        if attr == "preelaborable_initialization":
            # T'Preelaborable_Initialization - True if type has preelaborable init
            # For simple types on Z80, return True
            return Immediate(1, IRType.WORD)

        if attr == "denorm_min":
            # T'Denorm_Min - smallest denormalized value
            # Not applicable to integers, return 0
            return Immediate(0, IRType.WORD)

        if attr == "safe_first" or attr == "safe_last":
            # T'Safe_First / T'Safe_Last - safe range bounds
            # For integers, same as First/Last
            ada_type = None
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    ada_type = sym.ada_type
            if ada_type and hasattr(ada_type, 'low') and hasattr(ada_type, 'high'):
                if attr == "safe_first":
                    return Immediate(ada_type.low, IRType.WORD)
                else:
                    return Immediate(ada_type.high, IRType.WORD)
            return Immediate(-32768 if attr == "safe_first" else 32767, IRType.WORD)

        if attr == "model_small":
            # T'Model_Small - smallest model number > 0
            # For integers, return 1
            return Immediate(1, IRType.WORD)

        if attr == "model_epsilon":
            # T'Model_Epsilon - model epsilon (spacing at 1.0)
            # For integers, return 1
            return Immediate(1, IRType.WORD)

        if attr == "model_emin":
            # T'Model_Emin - minimum model exponent
            # For 16-bit integers, log2(1) = 0
            return Immediate(0, IRType.WORD)

        if attr == "model_mantissa":
            # T'Model_Mantissa - model mantissa digits
            # For 16-bit signed integers, ~15 bits of precision
            return Immediate(15, IRType.WORD)

        if attr == "small":
            # T'Small - smallest positive value
            # For fixed-point types, Small is the delta value.
            # In scaled integer representation, this is always 1
            # (since delta / delta = 1).
            ada_type = None
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    ada_type = sym.ada_type
            return Immediate(1, IRType.WORD)

        if attr == "signed_zeros":
            # T'Signed_Zeros - True if type has signed zeros
            # Not applicable to integers
            return Immediate(0, IRType.WORD)

        if attr == "stream_size":
            # T'Stream_Size - size for streaming in bits
            ada_type = None
            if isinstance(expr.prefix, Identifier):
                sym = self.symbols.lookup(expr.prefix.name)
                if sym and sym.ada_type:
                    ada_type = sym.ada_type
            if ada_type and hasattr(ada_type, 'size_bits'):
                return Immediate(ada_type.size_bits, IRType.WORD)
            return Immediate(16, IRType.WORD)

        if attr == "write":
            # T'Write(Stream, Item) - Write Item to Stream
            # Stream is treated as a file handle on Z80/CP/M
            if len(expr.args) >= 2:
                stream = self._lower_expr(expr.args[0])
                item_arg = expr.args[1]
                # Get address of item
                item_addr = self._get_lvalue_address(item_arg)
                if item_addr is None:
                    # For expressions, evaluate and store to temp
                    item_val = self._lower_expr(item_arg)
                    self.builder.push(item_val)
                    item_addr = self.builder.new_vreg(IRType.PTR, "_item_addr")
                    self.builder.emit(IRInstr(OpCode.GETSP, dst=item_addr))
                # Get item size
                item_size = self._get_type_size(item_arg)
                # Call file write (stream = file handle)
                self.builder.push(Immediate(item_size, IRType.WORD))
                self.builder.push(item_addr)
                self.builder.push(stream)
                self.builder.call(Label("_file_write"), comment="T'Write")
                for _ in range(3):
                    temp = self.builder.new_vreg(IRType.WORD, "_discard")
                    self.builder.pop(temp)
            return Immediate(0, IRType.WORD)

        if attr == "read":
            # T'Read(Stream, Item) - Read Item from Stream
            # Stream is treated as a file handle on Z80/CP/M
            if len(expr.args) >= 2:
                stream = self._lower_expr(expr.args[0])
                item_arg = expr.args[1]
                # Get address of item for writing result
                item_addr = self._get_lvalue_address(item_arg)
                if item_addr is None:
                    item_addr = self._lower_expr(item_arg)
                # Get item size
                item_size = self._get_type_size(item_arg)
                # Call file read (stream = file handle)
                self.builder.push(Immediate(item_size, IRType.WORD))
                self.builder.push(item_addr)
                self.builder.push(stream)
                self.builder.call(Label("_file_read"), comment="T'Read")
                for _ in range(3):
                    temp = self.builder.new_vreg(IRType.WORD, "_discard")
                    self.builder.pop(temp)
            return Immediate(0, IRType.WORD)

        if attr == "input":
            # T'Input(Stream) - Read and return value from Stream
            # For Z80, read a word (2 bytes) from the stream/file
            result = self.builder.new_vreg(IRType.WORD, "_stream_input")
            if expr.args:
                stream = self._lower_expr(expr.args[0])
                # Allocate temp buffer on stack
                self.builder.push(Immediate(0, IRType.WORD))  # Reserve space
                temp_buf = self.builder.new_vreg(IRType.PTR, "_buf")
                self.builder.emit(IRInstr(OpCode.GETSP, dst=temp_buf))
                # Read 2 bytes
                self.builder.push(Immediate(2, IRType.WORD))
                self.builder.push(temp_buf)
                self.builder.push(stream)
                self.builder.call(Label("_file_read"), comment="T'Input")
                for _ in range(3):
                    temp = self.builder.new_vreg(IRType.WORD, "_discard")
                    self.builder.pop(temp)
                # Pop result from stack
                self.builder.pop(result)
            return result

        if attr == "output":
            # T'Output(Stream, Item) - Write Item with tag to Stream
            # For Z80, this is similar to T'Write but includes type tag
            if len(expr.args) >= 2:
                stream = self._lower_expr(expr.args[0])
                item_arg = expr.args[1]
                # Get address of item
                item_addr = self._get_lvalue_address(item_arg)
                if item_addr is None:
                    item_val = self._lower_expr(item_arg)
                    self.builder.push(item_val)
                    item_addr = self.builder.new_vreg(IRType.PTR, "_item_addr")
                    self.builder.emit(IRInstr(OpCode.GETSP, dst=item_addr))
                # Get item size
                item_size = self._get_type_size(item_arg)
                # Write item to stream (stream = file handle)
                self.builder.push(Immediate(item_size, IRType.WORD))
                self.builder.push(item_addr)
                self.builder.push(stream)
                self.builder.call(Label("_file_write"), comment="T'Output")
                for _ in range(3):
                    temp = self.builder.new_vreg(IRType.WORD, "_discard")
                    self.builder.pop(temp)
            return Immediate(0, IRType.WORD)

        if attr == "external_tag":
            # T'External_Tag - Get external tag string for tagged type
            result = self.builder.new_vreg(IRType.PTR, "_ext_tag")
